'Cr_Guide_S_booked' => 'ऑर्डर कूरियर के पास है; अभी किसी ने उसे उठाया नहीं है। बुकिंग केवल इसी समय रद्द की जा सकती है।',
'Cr_Guide_S_picked_up' => 'कूरियर ने पार्सल उठा लिया है।',
'Cr_Guide_S_in_transit' => 'हब के बीच जा रहा है, कस्टम में है या रोका गया है।',
'Cr_Guide_S_out_for_delivery' => 'आज राइडर के पास है।',
'Cr_Guide_S_failed_attempt' => 'ग्राहक घर पर नहीं था, उसने मना कर दिया या पता गलत था। कूरियर फिर से प्रयास करता है या उसे लौटा देता है।',
'Cr_Guide_S_delivered' => 'ग्राहक को सौंप दिया गया। COD राशि की स्थिति कूरियर ने वसूला हो जाती है।',
'Cr_Guide_S_returning' => 'आपके पास वापस आ रहा है।',
'Cr_Guide_S_returned' => 'आपके पास वापस आ गया: यह समीक्षा हेतु वापसी में प्रतीक्षा करता है, या अपने आप स्टॉक में वापस डाल दिया जाता है।',
'Cr_Guide_S_cancelled' => 'बुकिंग रद्द कर दी गई।',
'Cr_Guide_T_Booking' => 'ऑर्डर बुक करना',
'Cr_Guide_B_Booking' => 'कूरियर को भेजें बिक्री से फ़ॉर्म भर देता है: प्राप्तकर्ता, पता, COD के रूप में अभी देय राशि, और उत्पादों का वज़न। जिन कूरियर की अपनी शहर सूची होती है, वे एक पिकर दिखाते हैं, और उस शहर के लिए आपकी पसंद याद रखी जाती है। एग्रीगेटर, DHL, FedEx, UPS और Lalamove दरों की तुलना करें की सुविधा देते हैं: कोई कीमत चुनें और बुक करें उसे खरीद लेता है। बिक्री सूची से कई बिक्रियाँ एक साथ बुक की जा सकती हैं।',
'Cr_Guide_T_Cod' => 'कैश ऑन डिलीवरी',
'Cr_Guide_B_Cod' => 'COD पार्सल वसूला नहीं गया से कूरियर ने वसूला (डिलीवरी पर) और फिर आपको भुगतान किया गया तक जाता है। जो कूरियर पेआउट की सूचना देते हैं, वे अंतिम चरण खुद आगे बढ़ाते हैं; बाकी के लिए COD अपडेट करें का उपयोग करें। कूरियर सेटिंग्स में खाता चुना हो, तो पेआउट बिक्री पर भुगतान के रूप में दर्ज होता है। पार्सल पूरा होने के बाद कूरियर शुल्क को व्यय के रूप में सहेजा जा सकता है।',
'Cr_Guide_T_Returns' => 'लौटाए गए पार्सल',
'Cr_Guide_B_Returns' => 'डिफ़ॉल्ट रूप से लौटाया गया पार्सल कूरियर शिपमेंट में समीक्षा हेतु वापसी के अंतर्गत प्रतीक्षा करता है। स्टॉक में वापस डालें पूरे ऑर्डर के लिए बिक्री वापसी बनाता है और आइटम को स्टॉक में वापस डालता है; खारिज करें कुछ भी वापस नहीं डालता, यह क्षतिग्रस्त या खोए हुए पार्सल के लिए है। इसके बजाय कूरियर सेटिंग्स अपने आप स्टॉक में वापस डाल सकती हैं।',
'Cr_Guide_T_Customers' => 'ग्राहक संदेश और ट्रैकिंग पेज',
'Cr_Guide_B_Customers' => 'कूरियर सेटिंग्स में ग्राहक सूचनाएँ आपकी टिक की गई स्थितियों पर SMS, ईमेल या WhatsApp भेजती हैं, हर पार्सल पर एक बार, आपके अपने टेक्स्ट के साथ। आपकी ऑनलाइन दुकान का ट्रैकिंग पेज ग्राहकों को ट्रैकिंग नंबर से, या ऑर्डर नंबर और फ़ोन से पार्सल ट्रैक करने देता है। जो ग्राहक अक्सर पार्सल लौटाते हैं, उन्हें बुकिंग के समय वापसी-जोखिम बैज मिलता है।',
'Cr_Guide_T_Labels' => 'लेबल',
'Cr_Guide_B_Labels' => 'लेबल प्रिंट करें कूरियर का अपना लेबल देता है जब वह जारी करता है (PDF, लिंक या इमेज), अन्यथा ट्रैकिंग बारकोड और वसूली जाने वाली राशि के साथ एक Stocky लेबल। प्रिंट करने के लिए इस साइट के पॉप-अप की अनुमति दें। DHL, FedEx और UPS अपना लेबल केवल एक बार, बुकिंग के समय देते हैं, और Stocky उसे दोबारा प्रिंट के लिए रखता है।',
'Cr_Guide_T_Faq' => 'समस्या निवारण',
'Cr_Guide_Q_Test' => 'कनेक्शन जाँच विफल होती है',
'Cr_Guide_A_Test' => 'टेस्ट-मोड कुंजियाँ टेस्ट मोड के साथ और लाइव कुंजियाँ लाइव के साथ चलती हैं; ये अलग-अलग होती हैं। सटीक कारण के लिए कूरियर लॉग खोलें और कूरियर का जवाब पढ़ें।',
'Cr_Guide_Q_City' => 'कूरियर शहर या पता अस्वीकार करता है',
'Cr_Guide_A_City' => 'बुकिंग फ़ॉर्म में कूरियर शहर सूची से शहर चुनें; कूरियर केवल अपने नाम स्वीकार करते हैं। जो कूरियर डाक पतों के साथ काम करते हैं, उन्हें राज्य, पोस्टल कोड और दो-अक्षर वाला देश कोड भी चाहिए।',
'Cr_Guide_Q_Webhook' => 'स्थितियाँ अपने आप नहीं बदलतीं',
'Cr_Guide_A_Webhook' => 'अपडेट भेजने वाले कूरियर के लिए जाँचें कि वेबहुक URL कूरियर के यहाँ पंजीकृत है: कूरियर लॉग में हर प्राप्त अपडेट दिखता है, या यह कि कोई अपडेट क्यों अस्वीकार हुआ (जैसे गलत secret)। अन्य कूरियर कूरियर सेटिंग्स में दी गई समय-सारणी पर जाँचे जाते हैं, और अभी स्थिति जाँचें तुरंत पूछता है।',
'Cr_Guide_Q_Stuck' => 'शिपमेंट पर स्थिति जाँच त्रुटि दिखती है',
'Cr_Guide_A_Stuck' => 'कूरियर ने पिछली जाँचें अस्वीकार कर दीं; कारण शिपमेंट पर और कूरियर लॉग में है। बार-बार विफल होने के बाद शिपमेंट की अपने आप जाँच बंद हो जाती है: कारण ठीक करें, फिर अभी स्थिति जाँचें का उपयोग करें।',
'Cr_Guide_Q_Label' => 'लेबल प्रिंट करते समय कुछ नहीं खुलता',
'Cr_Guide_A_Label' => 'आपके ब्राउज़र ने पॉप-अप रोक दिया। इस साइट के पॉप-अप की अनुमति दें और फिर से प्रयास करें।',
'Cr_Guide_Q_Cod' => 'COD पेआउट बिक्री पर दर्ज नहीं हुआ',
'Cr_Guide_A_Cod' => 'कूरियर सेटिंग्स में कैश ऑन डिलीवरी के लिए स्विच चालू होना और खाता चुना होना ज़रूरी है। खाते के बिना पेआउट केवल भुगतान किया गया चिह्नित होते हैं।',
