'Sold_at_several_prices' => 'इस अवधि में कई कीमतों पर बेचा गया; यह भारित औसत है।',
'Restrict_Master_Data_By_Warehouse' => 'मास्टर डेटा को गोदाम के अनुसार सीमित करें',
'Restrict_Master_Data_By_Warehouse_Help' => 'चालू होने पर, विशिष्ट गोदामों को सौंपा गया उपयोगकर्ता केवल उन्हीं गोदामों से जुड़े उत्पाद, ग्राहक, प्रदायक, ब्रांड और श्रेणियाँ देखता है। जिन रिकॉर्ड का अभी कहीं उपयोग नहीं हुआ है वे दिखाई देते रहते हैं, ताकि नए बनाए गए रिकॉर्ड कभी छिपें नहीं। बिक्री, खरीद और वापसी हमेशा सीमित रहती हैं और इस स्विच से प्रभावित नहीं होतीं।',
'Restrict_Products_By_Warehouse' => 'उत्पादों को गोदाम के अनुसार सीमित करें',
'Restrict_Products_By_Warehouse_Help' => 'हर उत्पाद का एक मुख्य गोदाम होता है — वह शाखा जिसके लिए उसे बनाया गया था। चालू होने पर, विशिष्ट गोदामों को सौंपा गया उपयोगकर्ता केवल वही उत्पाद देखता, बेचता और संपादित करता है जिनका मुख्य गोदाम उसका है, साथ ही वे उत्पाद जिनका वास्तविक स्टॉक उसके किसी गोदाम में है (स्थानांतरण या खरीद से आया)। जिन उपयोगकर्ताओं को सभी गोदामों की पहुँच है, वे हमेशा सब कुछ देखते हैं। ऑनलाइन दुकान भी यही नियम मानती है: यह केवल स्टोर सेटिंग्स में चुने गए गोदामों के उत्पाद दिखाती है।',
'Virtual_Combo_Stock' => 'वर्चुअल कॉम्बो स्टॉक',
'Virtual_Combo_Stock_Help' => 'चालू होने पर, कॉम्बो उत्पाद का अपना कोई स्टॉक नहीं होता: उसकी उपलब्धता उतने कॉम्बो के बराबर होती है जितने उसके घटक उत्पाद अभी भी पूरे कर सकते हैं, और कॉम्बो बेचने पर स्टॉक घटकों से घटता है। बंद होने पर, कॉम्बो को पहले समायोजन से स्टॉक में जोड़ा (असेंबल किया) जाता है।',
'Virtual_Combo_Stock_Warning' => 'इसे कॉम्बो बेचने से पहले चुनना सबसे अच्छा है। कॉम्बो बिकने या वापस होने के बाद स्विच बदलने पर, उन दस्तावेज़ों के बाद के संपादन, हटाने और वापसी उनका स्टॉक गलत तरीके से उलट देते हैं।',
'Virtual_Combo_Stock_Confirm_On_Title' => 'वर्चुअल कॉम्बो स्टॉक चालू करें?',
'Virtual_Combo_Stock_Confirm_On_Body' => 'कॉम्बो सीधे अपने घटक उत्पादों से बिकेंगे, और उनका अपना स्टॉक अब उपयोग नहीं होगा।',
'Virtual_Combo_Stock_Confirm_Off_Title' => 'वर्चुअल कॉम्बो स्टॉक बंद करें?',
'Virtual_Combo_Stock_Confirm_Off_Body' => 'कॉम्बो फिर से अपने स्टॉक पर लौट आएँगे, जिसे बेचने से पहले घटकों से समायोजन के ज़रिए असेंबल करना होगा।',
'Home_Warehouse' => 'मुख्य गोदाम',
'Home_Warehouse_Hint' => 'वह शाखा जिससे यह उत्पाद संबंधित है। दूसरे गोदामों तक सीमित उपयोगकर्ता इसे तब तक नहीं देखेंगे जब तक स्टॉक उनके गोदाम में स्थानांतरित न हो।',
'Home_Warehouse_Required' => 'वह गोदाम चुनें जिससे यह उत्पाद संबंधित है।',
'Combo_products_required' => 'कॉम्बो में कम से कम एक उत्पाद जोड़ें।',
'Customer_Performance_Help' => 'ग्राहक पेज पर प्रदर्शन स्कोर और रेटिंग दिखाएँ, जो भुगतान विश्वसनीयता, उन्होंने कितनी हाल में खरीदारी की और उनकी वापसी दर से बनती है।',
'Product_Supplier' => 'उत्पादों पर प्रदायक',
'Product_Supplier_Help' => 'उत्पाद फ़ॉर्म में एक डिफ़ॉल्ट प्रदायक फ़ील्ड जोड़ता है, उसे उत्पाद सूची में कॉलम के रूप में दिखाता है, और रीऑर्डर सूची बनाने के लिए आपको उत्पादों को प्रदायक के अनुसार फ़िल्टर करने देता है।',
'Default_Supplier_Hint' => 'आप यह उत्पाद आमतौर पर जिससे दोबारा मँगाते हैं। उनसे मँगाई जाने वाली हर चीज़ देखने के लिए उत्पाद सूची को प्रदायक के अनुसार फ़िल्टर करें।',
'Account_Ledger' => 'खाता बही',
'Closing_Balance' => 'अंतिम शेष',
'Recon_Intro' => 'हर नकद और बैंक खाते के परिचालन शेष की तुलना उसके जुड़े लेजर खाते के सामान्य खाता-बही (General Ledger) शेष से करता है। यह पेज केवल पढ़ने के लिए है: यह किसी भी शेष को कभी नहीं बदलता।',
'Recon_Auto_Off' => 'स्वचालित जर्नल बंद हैं, इसलिए नए लेन-देन सामान्य खाता-बही में पोस्ट नहीं होते और गायब जर्नल के रूप में दिखेंगे। उन्हें सेटिंग्स → सुविधा स्विच में चालू करें।',
'Recon_Operational_Balance' => 'परिचालन शेष',
'Recon_GL_Balance' => 'GL शेष',
'Recon_Difference' => 'अंतर',
'Recon_Unreconciled' => 'बिना मिलान वाले खाते',
'Recon_Reconciled' => 'मिलान हो गया',
'Recon_Out_Of_Balance' => 'शेष मेल नहीं खाता',
'Recon_Not_Linked' => 'इस खाते में अभी तक कोई लेजर पोस्टिंग नहीं है।',
'Recon_Unassigned_Cash' => 'बिना खाते के दर्ज भुगतान सामान्य नकद (Cash) लेजर खाते में पोस्ट किए गए ({amount})। वे नीचे किसी भी खाते में शामिल नहीं हैं।',
'Recon_Details' => 'विवरण',
