'Recon_Load_Failed' => 'मिलान लोड नहीं किया जा सका।',
'Recon_Help_Matched' => 'लेजर इस लेन-देन के लिए वही राशि दिखाता है।',
'Recon_Help_Missing' => 'इस लेन-देन के लिए कोई जर्नल पोस्ट नहीं हुआ — आमतौर पर इसलिए कि यह स्वचालित जर्नल चालू होने से पहले हुआ था।',
'Recon_Help_Mismatch' => 'जर्नल मौजूद है लेकिन अलग राशि का — लेन-देन शायद पोस्ट होने के बाद संपादित किया गया था।',
'Recon_Help_Not_Journaled' => 'इस तरह का लेन-देन (पेरोल, सेवा कार्य, प्रारंभिक-शेष भुगतान) लेजर में अपने आप पोस्ट नहीं होता। यदि आपको यह वहाँ चाहिए, तो मैनुअल जर्नल प्रविष्टि दर्ज करें।',
