'Tg_Guide_Administrator' => 'एडमिन',
'Tg_Guide_GetUpdates_Intro' => 'ग्रुप या चैनल के लिए, यह पता अपने टोकन के साथ ब्राउज़र में खोलें, और संदेश पोस्ट करने के बाद इसे रीफ़्रेश करें:',
