'Tg_Guide_Chat_Id' => 'चैट {id}',
'Tg_Guide_How_Sent' => 'संदेश कैसे भेजे जाते हैं',
'Tg_Guide_A_Title' => 'तुरंत — कुछ भी इंस्टॉल नहीं करना',
'Tg_Guide_A_Body' => 'Stocky में सहेजी गई बिक्री, खरीद, भुगतान या व्यय — POS पर या एडमिन में — सहेजे जाने के {rightAfter} उसी अनुरोध में Telegram पर भेज दिया जाता है। न cron एंट्री, न queue worker, और कैशियर को कभी Telegram का इंतज़ार नहीं करना पड़ता: संदेश जाने से पहले ही बिक्री का उत्तर दिया जा चुका होता है।',
'Tg_Guide_Right_After' => 'तुरंत बाद',
'Tg_Guide_B_Title' => 'Cron एंट्री — पुनः प्रयास और बैकग्राउंड इवेंट के लिए',
'Tg_Guide_B_Body' => 'दो तरह के संदेश इसके बजाय Telegram की अपनी कतार में प्रतीक्षा करते हैं: विफल हुआ भेजना (Telegram कुछ पल के लिए उपलब्ध न हो), जिसे अगले कुछ मिनटों में तीन बार तक फिर से भेजा जाता है; और एडमिन के बाहर उत्पन्न इवेंट — WooCommerce या Shopify से आयात किए गए ऑर्डर, artisan कमांड। यह cron एंट्री इन्हें भेजती है, और कुछ नहीं:',
'Tg_Guide_B_Note' => 'हर मिनट सही है: जब कुछ भी प्रतीक्षा में न हो तो रन तुरंत समाप्त हो जाता है। cPanel पर यह {cronJobs} में जाता है — यदि {php} पुराना है तो PHP 8.2+ का पूरा पाथ उपयोग करें। Windows पर Task Scheduler का उपयोग करें: प्रोग्राम {php2}, आर्गुमेंट {args}, और {path} में शुरू करें।',
'Tg_Guide_N_Waiting' => '{n} भेजे जाने की प्रतीक्षा में',
'Tg_Guide_Nothing_Waiting' => 'कुछ भी प्रतीक्षा में नहीं',
'Tg_Guide_N_Gave_Up' => '{n} पुनः प्रयासों के बाद छोड़ दिए गए',
'Tg_Guide_Growing_Hint' => '— यदि यह संख्या बढ़ती रहती है, तो cron एंट्री नहीं चल रही है।',
'Tg_Guide_Without_Cron' => 'Cron एंट्री के बिना भी Stocky में सहेजी गई हर चीज़ तुरंत पहुँचती है; आप केवल पुनः प्रयास और आयात किए गए ऑर्डर खोते हैं।',
'Tg_Guide_Else_Title' => 'बाकी सब कुछ',
'Tg_Guide_Else_Body' => 'बैकग्राउंड में उत्पन्न इवेंट के संदेश प्लेटफ़ॉर्म द्वारा भेजे जाते हैं — कुछ भी सेटअप नहीं करना है।',
'Tg_Guide_Not_Arrive' => 'यदि संदेश नहीं पहुँचता',
'Tg_Guide_Err_401' => '{code} — बॉट टोकन गलत है। इसे BotFather से फिर से पेस्ट करें।',
'Tg_Guide_Err_400' => '{code} — चैट ID गलत है, या बॉट ग्रुप में नहीं है। निजी चैट के लिए पहले बॉट को संदेश भेजें।',
'Tg_Guide_Err_403' => '{code} — बॉट को ग्रुप में फिर से जोड़ें, या चैनल का एडमिन बनाएँ।',
'Tg_Guide_Test_Works' => 'टेस्ट काम करता है लेकिन बिक्री नहीं',
'Tg_Guide_Test_Works_Item' => '{label} — जाँचें कि इवेंट पर टिक लगा है (या {allEvents} चुना गया है) और स्विच चालू है।',
'Tg_Guide_Imported_Never' => 'आयात किए गए ऑर्डर कभी नहीं पहुँचते',
'Tg_Guide_Imported_Never_Item' => '{label} — ऊपर दी गई cron एंट्री नहीं चल रही है।',
'Jumia_Hero_Title' => 'Jumia मार्केटप्लेस सिंक',
'Jumia_Hero_Desc' => 'कीमतें और स्टॉक अपनी Jumia Seller Center लिस्टिंग पर भेजें और मार्केटप्लेस ऑर्डर को बिक्री के रूप में आयात करें।',
'Jumia_Api_Url_Label' => 'API URL (आपके देश का Seller Center एंडपॉइंट)',
'Jumia_Account_Email' => 'खाता ईमेल (User ID)',
'Jumia_Prices_Stock' => 'कीमतें और स्टॉक',
'Jumia_Push_Card_Title' => 'कीमतें और स्टॉक Jumia पर भेजें',
'Jumia_Push_Desc' => 'हर उस उत्पाद (और वेरिएंट) की वर्तमान कीमत और मात्रा भेजता है जिसका SKU Jumia लिस्टिंग के {sellerSku} से मेल खाता है। अपडेट Seller Center फ़ीड के रूप में सबमिट होते हैं और असिंक्रोनस रूप से लागू होते हैं — फ़ीड ID लॉग टैब में दर्ज होती है, और प्रति-आइटम अस्वीकृतियाँ Seller Center की फ़ीड स्थिति स्क्रीन पर दिखती हैं।',
'Jumia_Push_Prices_Stock' => 'कीमतें और स्टॉक भेजें',
'Jumia_Orders_Desc' => 'मार्केटप्लेस ऑर्डर को बिक्री के रूप में आयात करता है ({ref} जैसे संदर्भ), Seller SKU द्वारा आपके उत्पादों से मिलाकर। पहले से आयात किए गए और रद्द ऑर्डर छोड़ दिए जाते हैं, इसलिए नियमित रूप से प्राप्त करना सुरक्षित है। भुगतान केवल डिलीवर हो चुके ऑर्डर के लिए भुगतान किए गए के रूप में चिह्नित होते हैं (Jumia में ज़्यादातर COD होता है)।',
'Jumia_Guide_1' => 'Jumia {sellerCenter} में Settings → {integrationMgmt} खोलें और एक API कुंजी जनरेट करें।',
'Jumia_Guide_2' => 'अपने देश का API URL (जैसे नाइजीरिया के लिए {ng}, केन्या के लिए {ke}, मिस्र के लिए {eg}), अपना Seller Center खाता ईमेल, और कुंजी दर्ज करें — फिर {test} चलाएँ।',
'Jumia_Guide_3' => 'सुनिश्चित करें कि हर Jumia लिस्टिंग का {sellerSku} Stocky उत्पाद कोड के बराबर हो — स्टॉक भेजने और ऑर्डर मिलाने, दोनों के लिए यही पहचान उपयोग होती है।',
'Jumia_Guide_4' => 'इन्वेंटरी बदलने के बाद कीमतें और स्टॉक भेजें; ऑर्डर नियमित रूप से प्राप्त करें (इस API में Jumia के वेबहुक नहीं हैं)।',
'Jumia_Guide_5' => 'नई लिस्टिंग बनाना Seller Center में ही होता है — Jumia को श्रेणी-विशिष्ट विशेषताओं और इमेज समीक्षा की आवश्यकता होती है, जिन्हें केवल उनका पोर्टल ठीक से संभालता है।',
'Mc_Hero_Title' => 'Mailchimp ऑडियंस सिंक',
'Mc_Hero_Desc' => 'Mailchimp ऑडियंस को अपने ग्राहकों से भरा रखें, ताकि आप अपने वास्तविक ग्राहक आधार पर ईमेल अभियान चला सकें।',
'Mc_Account_Audience' => 'खाता और ऑडियंस',
'Mc_Api_Key_Placeholder' => 'जैसे a1b2c3…-us14 (Account → Extras → API keys)',
'Mc_Audience' => 'ऑडियंस',
'Mc_N_Members' => '({n} सदस्य)',
'Mc_Load_Audiences_To_Pick' => 'एक चुनने के लिए ऑडियंस लोड करें',
'Mc_Load_Audiences' => 'ऑडियंस लोड करें',
'Mc_Double_Opt_In_Label' => 'डबल ऑप्ट-इन — नए सदस्यों को जुड़ने से पहले पुष्टि ईमेल मिलता है',
'Mc_Recommended_GDPR' => '(GDPR के लिए अनुशंसित)',
'Mc_Auto_Sync_New' => 'नए ग्राहक बनते ही उन्हें ऑटो-सिंक करें',
'Mc_With_Email' => 'ईमेल वाले',
'Mc_Push_Desc' => 'ईमेल पते वाले हर ग्राहक को चयनित ऑडियंस में जोड़ता या अपडेट करता है (नाम और फ़ोन सहित)। मौजूदा सदस्यों की सदस्यता स्थिति बनी रहती है — जिसने अनसब्सक्राइब किया है उसे फिर से सब्सक्राइब नहीं किया जाता। बिना ईमेल वाले ग्राहक छोड़ दिए जाते हैं।',
'Mc_Double_Opt_In_Off' => 'डबल ऑप्ट-इन बंद है',
'Mc_Double_Opt_In_Off_Desc' => 'नए सदस्य बिना पुष्टि ईमेल के सब्सक्राइब्ड के रूप में जोड़े जाएँगे। ऐसा केवल उन ग्राहकों के लिए करें जो पहले से मार्केटिंग संदेश प्राप्त करने के लिए सहमत हैं।',
'Mc_Guide_1' => 'Mailchimp में {path} खोलें और एक कुंजी बनाएँ (यह {suffix} पर समाप्त होती है — यह प्रत्यय आपका डेटासेंटर है)।',
'Mc_Guide_2' => 'कुंजी यहाँ पेस्ट करें, सहेजें, फिर {load} पर क्लिक करें और भरने के लिए ऑडियंस चुनें।',
'Mc_Guide_3' => '{doi} चालू रखें, जब तक कि आपके ग्राहक पहले से मार्केटिंग ईमेल के लिए सहमति न दे चुके हों।',
'Mc_Double_Opt_In_Lower' => 'डबल ऑप्ट-इन',
'Mc_Guide_4' => 'पहली बार भरने के लिए {push} चलाएँ; {autoSync} चालू करें ताकि नए ग्राहक अपने-आप जुड़ जाएँ।',
'Mc_Auto_Sync_Lower' => 'ऑटो-सिंक',
'Mc_Consent_Matters' => 'सहमति महत्वपूर्ण है',
'Mc_Consent_Desc' => 'मार्केटिंग के लिए कभी सहमति न देने वाले लोगों को ईमेल भेजना GDPR/CAN-SPAM का उल्लंघन हो सकता है और आपका Mailchimp खाता निलंबित हो सकता है। डबल ऑप्ट-इन पुष्टि की ज़िम्मेदारी Mailchimp पर डालता है — यही सुरक्षित डिफ़ॉल्ट है।',
'Mc_No_Audiences' => 'इस खाते में कोई ऑडियंस नहीं मिली।',
'Presta_Hero_Desc' => 'अपने PrestaShop स्टोर के साथ उसके webservice API के माध्यम से उत्पाद, स्टॉक और ऑर्डर सिंक करें।',
'Presta_Webservice_Key' => 'Webservice कुंजी',
'Presta_Key_Placeholder' => 'Advanced Parameters → Webservice से',
'Presta_Key_Help' => 'PrestaShop में webservice सक्षम करें (Advanced Parameters → Webservice), products, stock_availables, orders और customers पर अनुमतियों वाली एक कुंजी बनाएँ, और उसे यहाँ पेस्ट करें। केवल-लेखन रूप में संग्रहीत।',
'Presta_Shop_Language_ID' => 'शॉप भाषा ID',
'Presta_Language_Help' => 'उत्पाद भेजते समय उत्पाद नामों के लिए उपयोग की जाने वाली भाषा id (1 = शॉप की पहली भाषा)।',
'Presta_Push_Desc' => 'PrestaShop पर अनुपलब्ध सरल उत्पाद (उनके वर्तमान स्टॉक के साथ) बनाता है। पहले से जुड़े उत्पाद और वेरिएंट उत्पाद छोड़ दिए जाते हैं — उत्पाद विवरण PrestaShop में ही संपादित करते रहें, या स्थानीय प्रति ताज़ा करने के लिए प्राप्त करें।',
'Presta_Pull_Desc' => 'PrestaShop उत्पादों को आयात करता है, मौजूदा उत्पादों को reference (SKU) से मिलाकर और बाकी को बनाकर। Combinations को उनके मूल उत्पाद के रूप में आयात किया जाता है।',
'Presta_Reset_Confirm' => 'उत्पाद लिंक रीसेट करें? ऑर्डर इतिहास के लिंक बने रहते हैं।',
'Presta_Stock_Desc' => 'हर जुड़े हुए उत्पाद के लिए शॉप का स्टॉक (stock_availables) अपडेट करता है।',
'Presta_Orders_Desc' => 'शॉप ऑर्डर को बिक्री के रूप में आयात करता है ({ref} जैसे संदर्भ), सबसे नए पहले। पहले से आयात किए गए और रद्द ऑर्डर छोड़ दिए जाते हैं, इसलिए नियमित रूप से प्राप्त करना सुरक्षित है। PrestaShop में वेबहुक नहीं हैं — व्यस्त समय के बाद इसे चलाएँ।',
'Presta_Guide_1' => 'अपने PrestaShop बैक ऑफ़िस में {path} खोलें और webservice सक्षम करें।',
'Presta_Guide_2' => 'एक नई कुंजी जोड़ें, {products} और {stock} पर {vae}, और {orders} व {customers} पर {view} अनुमति दें।',
'Presta_Guide_3' => 'कनेक्शन टैब पर स्टोर URL और कुंजी पेस्ट करें, सहेजें, और {test} चलाएँ।',
'Presta_Guide_4' => 'यदि शॉप में पहले से कैटलॉग है तो पहले उत्पाद प्राप्त करें (reference/SKU से मिलान होता है); अनुपलब्ध सरल उत्पाद बनाने के लिए भेजें।',
'Presta_Guide_5' => 'मात्रा बदलने पर हर बार स्टॉक भेजें, और ऑर्डर नियमित रूप से प्राप्त करें — PrestaShop में वेबहुक नहीं हैं, इसलिए ऑर्डर तभी आते हैं जब आप प्राप्त करते हैं।',
'Presta_Identity_Title' => 'उत्पाद की पहचान reference (SKU) है',
'Presta_Identity_Desc' => 'Stocky का उत्पाद कोड PrestaShop के reference से मिलाया जाता है। दोनों ओर references एक जैसे रखें; combinations (वेरिएंट) ऑर्डर में reference से मिलाए जाते हैं, लेकिन इस संस्करण में भेजे नहीं जाते।',
'Gs_Hero_Title' => 'Google Sheets निर्यात',
'Gs_Hero_Desc' => 'अपनी बिक्री, उत्पाद और ग्राहकों को एक लाइव Google स्प्रेडशीट में निर्यात करें — हर एक के लिए अलग टैब, मांग पर ताज़ा।',
'Gs_OAuth_Credentials' => 'Google OAuth क्रेडेंशियल',
'Gs_Secret_Placeholder' => 'आपके Google Cloud OAuth client से',
'Gs_Auto_Export_Nightly' => 'हर रात स्वतः निर्यात',
'Gs_Auto_Export_Hint' => '(सभी टैब सर्वर समय के अनुसार लगभग 02:30 बजे ताज़ा होते हैं)',
'Gs_Enable_Exports' => 'Google Sheets निर्यात सक्षम करें',
'Gs_Account_Spreadsheet' => 'खाता और स्प्रेडशीट',
'Gs_Connect' => 'Google खाता कनेक्ट करें',
'Gs_Reconnect' => 'Google खाता फिर से कनेक्ट करें',
'Gs_Disconnect_Confirm' => 'Google खाता डिस्कनेक्ट करें? फिर से कनेक्ट करने तक निर्यात रुक जाएँगे।',
'Gs_Target_Spreadsheet' => 'लक्ष्य स्प्रेडशीट (ID या पूरा URL)',
'Gs_Spreadsheet_Placeholder' => 'स्प्रेडशीट URL पेस्ट करें, या नई बनाएँ →',
