'Gs_Open_Spreadsheet' => 'स्प्रेडशीट खोलें ↗',
'Gs_Last_Export' => 'अंतिम निर्यात {date}',
'Gs_Redirect_Uri_Title' => 'Google OAuth client के लिए Redirect URI',
'Gs_Export_Desc' => 'हर निर्यात अपने टैब को शुरू से फिर से लिखता है (हेडर + सभी पंक्तियाँ), इसलिए शीट हमेशा एक पूर्ण, वर्तमान स्नैपशॉट होती है। बड़े डेटासेट बैच में भेजे जाते हैं — काउंटर रुकने तक पेज खुला रखें।',
