'Gs_Job_Sales_Desc' => 'ग्राहक, कुल राशि, भुगतान स्थिति और गोदाम के साथ हर बिक्री।',
'Gs_Job_Products_Desc' => 'कीमतों, लागतों और वर्तमान स्टॉक मात्राओं के साथ पूरा कैटलॉग।',
'Gs_Job_Customers_Desc' => 'संपर्क विवरण के साथ सभी ग्राहक।',
'Gs_Guide_1' => '{console} पर एक प्रोजेक्ट बनाएँ और {api} सक्षम करें (APIs & Services → Library)।',
'Gs_Guide_2' => '{consent} (External) कॉन्फ़िगर करें। जब तक यह "Testing" में रहे, अपने Google खाते को test user के रूप में जोड़ें — ध्यान दें कि testing मोड के refresh token 7 दिनों के बाद समाप्त हो जाते हैं, इसलिए स्थायी कनेक्शन के लिए ऐप को {publish} करें।',
'Gs_OAuth_Consent_Screen' => 'OAuth consent screen',
'Gs_Publish' => 'पब्लिश',
'Gs_Guide_3' => 'Web application प्रकार का एक {clientId} बनाएँ और कनेक्शन टैब पर दिखाया गया redirect URI पंजीकृत करें।',
'Gs_OAuth_Client_ID' => 'OAuth client ID',
