'Gs_Guide_5' => 'बटन से एक स्प्रेडशीट बनाएँ (या ऐसी स्प्रेडशीट का URL पेस्ट करें जिसे आपका Google खाता संपादित कर सके), फिर निर्यात चलाएँ।',
'Gs_Snapshots_Title' => 'स्नैपशॉट, लाइव सिंक नहीं',
