'Fbr_Guide_What_Body' => 'SRO 69(I)/2025 के अंतर्गत, फ़ेडरल बोर्ड ऑफ़ रेवेन्यू (पाकिस्तान) एकीकृत व्यवसायों से अपेक्षा करता है कि वे बिक्री बीजकों की रिपोर्ट PRAL डिजिटल इनवॉइसिंग (DI) API के माध्यम से वास्तविक समय में इलेक्ट्रॉनिक रूप से करें। हर स्वीकृत बिक्री को एक आधिकारिक FBR बीजक संख्या मिलती है, और रसीदों पर वह संख्या एक सत्यापन QR कोड के साथ दिखनी चाहिए।',
'Fbr_Guide_Steps_Title' => 'लाइव होने के चरण',
'Fbr_Guide_Step_1' => 'FBR IRIS ई-इनवॉइसिंग पोर्टल पर पंजीकरण करें और {sandbox} सुरक्षा टोकन प्राप्त करें।',
'Fbr_Guide_Step_2' => 'कॉन्फ़िगरेशन टैब पर अपनी विक्रेता प्रोफ़ाइल (NTN/CNIC, व्यवसाय का नाम, प्रांत, पता) सेट करें, टोकन चिपकाएँ, और एनवायरनमेंट को {sandbox} पर रखकर एकीकरण सक्षम करें।',
'Fbr_Guide_Step_3' => 'FBR द्वारा आपको सौंपे गए परिदृश्यों को कवर करते हुए परीक्षण बिक्री करें (सैंडबॉक्स परिदृश्य फ़ील्ड में परिदृश्य चुनें)। दस्तावेज़ टैब में पुष्टि करें कि वे {valid} के रूप में लौटती हैं।',
'Fbr_Guide_Step_4' => 'FBR द्वारा आपके सैंडबॉक्स परीक्षण को स्वीकृति मिलने के बाद, पोर्टल से {production} टोकन प्राप्त करें, उसे यहाँ चिपकाएँ, और एनवायरनमेंट को {production} पर बदलें।',
'Fbr_Guide_Step_5' => 'बिक्री स्वीकार होते ही रसीदों पर FBR बीजक संख्या और QR कोड अपने-आप दिखते हैं — पॉइंट ऑफ़ सेल पर कोई अतिरिक्त कदम आवश्यक नहीं।',
'Fbr_Sandbox_Lower' => 'सैंडबॉक्स',
'Fbr_Production_Lower' => 'प्रोडक्शन',
'Fbr_Guide_Note_1' => 'उत्पाद फ़ॉर्म पर प्रति उत्पाद HS कोड सेट करें (फ़ील्ड "HS कोड")। यहाँ कॉन्फ़िगर किया गया डिफ़ॉल्ट HS कोड केवल बिना HS कोड वाले उत्पादों के लिए उपयोग होता है।',
'Fbr_Guide_Note_2' => 'अपंजीकृत वॉक-इन ग्राहकों की रिपोर्ट FBR को "Unregistered" (अपंजीकृत) के रूप में की जाती है।',
'Fbr_Guide_Note_3' => 'पंजीकृत खरीदारों का NTN ग्राहक के कर संख्या फ़ील्ड में दर्ज होना चाहिए, ताकि उनकी रिपोर्ट पंजीकृत के रूप में हो।',
'Fbr_Guide_Note_4' => 'असफल या अमान्य सबमिशन को कारण ठीक करने के बाद दस्तावेज़ टैब से दोबारा भेजा जा सकता है; समस्या निवारण के लिए लॉग टैब कच्चे API आदान-प्रदान दिखाता है।',
