'Woo_Automatic_Sync' => 'स्वचालित सिंक',
'Woo_Auto_Sync_Intro' => 'Stocky में किए गए बदलाव होते ही WooCommerce पर भेजें, इस पेज को खोले बिना। हर बार भेजने की प्रक्रिया कार्रवाई सहेजे जाने के ठीक बाद चलती है, इसलिए कैशियर को कभी WooCommerce का इंतज़ार नहीं करना पड़ता। परिणाम लॉग टैब में दिखते हैं।',
'Woo_Auto_Sync_Products_Help' => 'Stocky में बनाया, संपादित या डुप्लिकेट किया गया उत्पाद WooCommerce पर भेजा जाता है (विवरण, मूल्य, वेरिएंट, छवियाँ, स्टॉक)। थोक आयात नहीं भेजे जाते; आयात के बाद उत्पाद टैब में सिंक — POS → WooCommerce का उपयोग करें।',
'Woo_Auto_Sync_Stock_Help' => 'कोई भी स्टॉक मूवमेंट (POS बिक्री, बिक्री, वापसी, खरीद, समायोजन, स्थानांतरण) WooCommerce पर संबंधित उत्पादों की मात्रा अपडेट करता है। केवल वे उत्पाद अपडेट होते हैं जो पहले से WooCommerce से लिंक हैं।',
'Woo_Sync_Tuning' => 'सिंक ट्यूनिंग',
'Woo_Sync_Tuning_Intro' => 'डिफ़ॉल्ट मान अधिकतर स्टोर के लिए उपयुक्त हैं। इन्हें केवल तभी बदलें जब आपकी होस्टिंग पर सिंक धीमा हो या टाइमआउट हो। हर मान एक सुरक्षित सीमा में रखा जाता है, और किसी फ़ील्ड को खाली करने पर उसका डिफ़ॉल्ट लौट आता है।',
'Woo_Sync_Guide' => 'WooCommerce सिंक गाइड',
'Woo_Guide_Getting_Keys' => 'API कुंजियाँ प्राप्त करना',
'Woo_Guide_Keys_1' => 'WooCommerce में: WooCommerce → Settings → Advanced → REST API।',
'Woo_Guide_Keys_2' => 'Add key पर क्लिक करें, Read/Write चुनें, फिर Consumer key और Consumer secret कॉपी करें।',
'Woo_Guide_Keys_3' => 'स्टोर URL: आपकी साइट का URL, अंत में स्लैश के बिना (उदा. {example})।',
'Woo_Guide_WP_Title' => 'WP उपयोगकर्ता नाम और एप्लिकेशन पासवर्ड (वैकल्पिक)',
'Woo_Guide_WP_Intro' => 'ये फ़ील्ड केवल उत्पाद छवियों के लिए उपयोग होते हैं। WooCommerce API (स्टोर URL + Consumer key/secret) उत्पादों, स्टॉक, श्रेणियों, ब्रांड, ग्राहकों और ऑर्डर का सिंक संभालता है; WordPress REST API मीडिया लाइब्रेरी (Media Library — छवियाँ खोजना और अपलोड करना) संभालता है।',
'Woo_Guide_WP_1' => 'उत्पाद या स्टॉक सिंक करते समय Stocky उत्पाद छवियाँ जोड़ सकता है: वह पहले फ़ाइल नाम से WordPress Media Library में मौजूदा छवि खोजता है; न मिलने पर वह WordPress API के ज़रिए छवि अपलोड करता है।',
'Woo_Guide_WP_2' => 'ऐसे WordPress उपयोगकर्ता का उपयोग करें जो मीडिया प्रबंधित कर सके (उदा. Administrator)। WordPress में एक Application Password बनाएँ: Users → Profile (या आपका उपयोगकर्ता) → Application Passwords — एक नया जोड़ें और उसे यहाँ चिपकाएँ।',
'Woo_Guide_WP_3' => 'यदि आप इन्हें खाली छोड़ते हैं, तब भी सिंक सभी डेटा (उत्पाद, स्टॉक, श्रेणियाँ, ब्रांड, ग्राहक, ऑर्डर) के लिए काम करता है; केवल उत्पाद छवि जोड़ना (खोज/अपलोड) छोड़ दिया जाता है।',
'Woo_Guide_How_To_Enable' => 'सक्षम कैसे करें',
'Woo_Guide_Enable_1' => 'ऊपर स्टोर URL, उपभोक्ता कुंजी (Consumer key) और उपभोक्ता सीक्रेट (Consumer secret) दर्ज करें, फिर सहेजें पर क्लिक करें।',
'Woo_Guide_Enable_2' => 'क्रेडेंशियल सत्यापित करने के लिए कनेक्शन टेस्ट करें का उपयोग करें।',
'Woo_Guide_Enable_3' => 'जब भी सिंक करना हो, किसी भी टैब से मैन्युअल सिंक का उपयोग करें।',
'Woo_Guide_Enable_4' => 'नए और संपादित उत्पादों तथा हर स्टॉक बदलाव को होते ही WooCommerce पर भेजने के लिए ऊपर स्वचालित सिंक चालू करें।',
'Woo_Guide_Manual_Sync' => 'मैन्युअल सिंक (आवश्यकता पर)',
'Woo_Guide_Manual_1' => 'सिंक दोनों दिशाओं में काम करता है: Stocky → WooCommerce और WooCommerce → Stocky।',
'Woo_Guide_Manual_2' => 'मैन्युअल सिंक सभी WooCommerce टैब (उत्पाद, स्टॉक आदि) में उपलब्ध है; आवश्यकता पर सिंक चलाने के लिए हर टैब में सिंक क्रियाओं का उपयोग करें।',
'Woo_Guide_Auto_1' => 'उत्पाद: चालू होने पर, Stocky में आपके द्वारा बनाया, संपादित या डुप्लिकेट किया गया उत्पाद सहेजते ही WooCommerce पर भेजा जाता है, उसके बाद उसका स्टॉक।',
'Woo_Guide_Auto_2' => 'स्टॉक: चालू होने पर, हर स्टॉक बदलाव (POS बिक्री, बिक्री, वापसी, खरीद, समायोजन, स्थानांतरण) WooCommerce पर मात्रा अपडेट करता है। केवल वे उत्पाद अपडेट होते हैं जो पहले से WooCommerce से लिंक हैं।',
'Woo_Guide_Auto_3' => 'स्वचालित सिंक केवल Stocky से WooCommerce पर बदलाव भेजता है। WooCommerce से Stocky में डेटा (ऑर्डर, ग्राहक, उत्पाद) लाना हमेशा ऑर्डर, ग्राहक और उत्पाद टैब के बटनों से किया जाता है।',
'Woo_Guide_Auto_4' => 'थोक उत्पाद आयात अपने-आप नहीं भेजे जाते। आयात के बाद उत्पाद टैब में सिंक — POS → WooCommerce का उपयोग करें।',
'Woo_Guide_Auto_5' => 'हर स्वचालित भेजना लॉग टैब में दर्ज होता है, ताकि आप देख सकें कि क्या भेजा गया और त्रुटियाँ पहचान सकें।',
'Woo_Guide_First_Setup' => 'पहला सेटअप',
'Woo_Guide_First_1' => 'इन्हें एक बार, इसी क्रम में चलाएँ ताकि आपका मौजूदा कैटलॉग लिंक हो जाए: श्रेणियाँ टैब में सिंक — POS → WooCommerce, फिर ब्रांड टैब, फिर उत्पाद टैब, और अंत में स्टॉक टैब में सिंक स्टॉक। इसके बाद WooCommerce को अद्यतन रखने के लिए ऊपर स्वचालित सिंक चालू करें।',
'Woo_Guide_First_2' => 'बड़े उत्पाद और स्टॉक सिंक छोटे बैचों में चलते हैं और टैब में अपनी प्रगति दिखाते हैं। सिंक पूरा होने तक पेज खुला रखें; आप इसे कभी भी रोक सकते हैं।',
'Woo_Guide_First_3' => 'यदि कोई सिंक कई मिनट तक आगे नहीं बढ़ता, तो लॉग टैब देखें, फिर सहायता टीम से संपर्क करें।',
'Woo_Guide_Notes_1' => 'स्टोर URL या API कुंजियाँ बदलने से मैपिंग (उत्पाद, श्रेणियाँ, ब्रांड, ग्राहक) रीसेट हो जाती है; आइटम (नए) स्टोर पर फिर से सिंक होंगे।',
'Woo_Guide_Notes_2' => 'डुप्लिकेट उत्पादों से बचने और सुरक्षित रूप से फिर से लिंक करने के लिए Stocky और WooCommerce के बीच SKU एक जैसे रखें।',
