'Pg_Credentials_Kept' => 'आपके क्रेडेंशियल बने रहते हैं — ऑनलाइन दुकान का चेकआउट बस तब तक {name} पेश नहीं करता जब तक आप उसे फिर से चालू न करें।',
'Pg_Remove_Credentials_Confirm' => 'संग्रहीत {name} क्रेडेंशियल हटाएँ? चेकआउट {short} पेश करना बंद कर देगा।',
'Pg_Remove_Keys_Confirm' => 'संग्रहीत {name} कुंजियाँ हटाएँ? चेकआउट {short} पेश करना बंद कर देगा।',
