'Pg_Stripe_Shared_Notice' => 'Stripe कुंजियाँ पूरे सिस्टम में साझा होती हैं।',
'Pg_Store_Feature_Not_In_Plan' => 'ऑनलाइन दुकान के गेटवे और ऑफ़लाइन भुगतान विधियाँ ऑनलाइन ऑर्डर सुविधा का हिस्सा हैं, जो आपकी वर्तमान योजना में शामिल नहीं है।',
'Pg_Intro_Title' => 'यहाँ का हर गेटवे क्रेडेंशियल संग्रहीत होने और स्विच चालू होने पर ऑनलाइन दुकान के चेकआउट में पेश किया जाता है।',
'Pg_Intro_Desc' => 'हर टैब का अपना चालू/बंद स्विच है, जो बदलते ही सहेज लिया जाता है: गेटवे बंद करने पर उसके क्रेडेंशियल बने रहते हैं, चेकआउट बस उसे पेश करना बंद कर देता है। Stripe कुंजियाँ वैश्विक रूप से साझा होती हैं (एडमिन और ऑनलाइन दुकान एक ही Stripe एकीकरण का उपयोग करते हैं)। ऑफ़लाइन भुगतान में कैश ऑन डिलीवरी और मोबाइल मनी शामिल हैं, जिनका भुगतान सिस्टम के बाहर होता है।',
'Pg_Label_Stripe_Key' => 'STRIPE कुंजी',
'Pg_Label_Stripe_Secret' => 'STRIPE सीक्रेट',
'Pg_Card_Payments_Off' => 'कार्ड भुगतान बंद हैं',
'Pg_Card_Keys_Kept' => 'आपकी कुंजियाँ बनी रहती हैं — ऑनलाइन दुकान का चेकआउट बस तब तक कार्ड विकल्प पेश नहीं करता जब तक आप उसे फिर से चालू न करें।',
'Pg_No_Stripe_Key' => 'कोई Stripe कुंजी संग्रहीत नहीं है',
'Pg_Enter_Stripe_Key' => 'ऑनलाइन दुकान में कार्ड भुगतान स्वीकार करना शुरू करने के लिए अपनी Stripe कुंजी और सीक्रेट दर्ज करें।',
'Pg_Label_Razorpay_Key_Id' => 'RAZORPAY कुंजी ID',
'Pg_Label_Razorpay_Key_Secret' => 'RAZORPAY कुंजी सीक्रेट',
'Pg_Razorpay_Help' => 'स्टोरफ़्रंट पर Razorpay Checkout का उपयोग करता है (कार्ड, UPI, नेटबैंकिंग, वॉलेट)। टेस्ट या लाइव, यह कुंजी जोड़ी (rzp_test_/rzp_live_) से तय होता है — कोई अलग सैंडबॉक्स स्विच नहीं है। दोनों कुंजियाँ संग्रहीत होते ही चेकआउट Razorpay पेश करता है।',
'Pg_Label_Bkash_App_Key' => 'BKASH ऐप कुंजी',
'Pg_Label_Bkash_App_Secret' => 'BKASH ऐप सीक्रेट',
'Pg_Label_Bkash_Username' => 'BKASH उपयोगकर्ता नाम',
'Pg_Label_Bkash_Password' => 'BKASH पासवर्ड',
'Pg_Bkash_Sandbox_Help' => 'चालू होने पर आपके सैंडबॉक्स क्रेडेंशियल के साथ tokenized.sandbox.bka.sh का उपयोग होता है; tokenized.pay.bka.sh पर वास्तविक bKash खातों से शुल्क लेने के लिए बंद करें।',
'Pg_Bkash_Help' => 'bKash Tokenized Checkout का उपयोग करता है (bKash मर्चेंट पोर्टल से मर्चेंट क्रेडेंशियल)। BDT में शुल्क लेता है। चारों क्रेडेंशियल संग्रहीत होते ही चेकआउट bKash पेश करता है।',
'Pg_Label_Sslcommerz_Store_Id' => 'SSLCOMMERZ स्टोर ID',
'Pg_Label_Sslcommerz_Store_Password' => 'SSLCOMMERZ स्टोर पासवर्ड',
'Pg_Sslcommerz_Sandbox_Help' => 'चालू होने पर सैंडबॉक्स क्रेडेंशियल के साथ sandbox.sslcommerz.com का उपयोग होता है; securepay.sslcommerz.com पर वास्तविक ग्राहकों से शुल्क लेने के लिए बंद करें।',
'Pg_Sslcommerz_Help' => 'बांग्लादेश में कार्ड, bKash/Nagad/Rocket मोबाइल बैंकिंग और इंटरनेट बैंकिंग को कवर करने वाला होस्टेड चेकआउट। BDT में शुल्क लेता है।',
'Pg_Sslcommerz_Ipn_Help' => 'IPN URL (अनुशंसित बैकअप — इसे SSLCommerz मर्चेंट पैनल पर My Stores → IPN Settings में सेट करें):',
