'Pg_Paymob_Integration_Help' => 'Paymob Dashboard → Developers → Payment Integrations से; कई विधियाँ पेश करने के लिए कई ID अल्पविराम से अलग करके दर्ज करें।',
'Pg_Paymob_Integration_Placeholder' => 'उदा. 4419544 या 4419544,4419545',
'Pg_Label_Hmac_Secret' => 'HMAC सीक्रेट',
'Pg_Label_Charge_Currency' => 'चार्ज मुद्रा',
'Pg_Paymob_Currency_Help' => 'आपके Paymob खाते की मुद्रा (EGP, SAR, AED, PKR या OMR) और आपके स्टोर की आधार मुद्रा से मेल खानी चाहिए।',
'Pg_Paymob_Help' => 'Paymob Unified Checkout का उपयोग करता है (मिस्र, KSA, UAE, पाकिस्तान और ओमान में कार्ड, वॉलेट और स्थानीय विधियाँ)। पाँचों क्रेडेंशियल Paymob Dashboard → Settings → Account Info + Payment Integrations से मिलते हैं।',
'Pg_Paymob_Webhook_Help' => 'वेबहुक हर भुगतान के लिए अपने-आप सेट होता है — डैशबोर्ड में कोई सेटअप आवश्यक नहीं। संदर्भ के लिए बैकअप कॉलबैक URL:',
'Pg_Label_Api_Token' => 'API टोकन',
'Pg_Label_Account_Country_Live' => 'खाते का देश (लाइव)',
'Pg_Myfatoorah_Country_Help' => 'आपके MyFatoorah खाते के देश का ISO कोड — KWT, SAU, QAT, EGY, ARE, BHR, OMN या JOR। लाइव API होस्ट चुनता है; सैंडबॉक्स मोड में अनदेखा किया जाता है।',
'Pg_Myfatoorah_Currency_Help' => 'आपके MyFatoorah खाते की मुद्रा (KWD, SAR, AED, QAR, BHD, OMR, JOD, EGP…) और आपके स्टोर की आधार मुद्रा से मेल खानी चाहिए।',
'Pg_Myfatoorah_Sandbox_Help' => 'चालू होने पर डेमो API टोकन के साथ apitest.myfatoorah.com का उपयोग होता है; लाइव API पर वास्तविक ग्राहकों से शुल्क लेने के लिए बंद करें।',
'Pg_Myfatoorah_Help' => 'GCC भर में KNET, mada, कार्ड, Apple Pay और STC Pay को कवर करने वाला होस्टेड बीजक लिंक। API टोकन MyFatoorah Vendor Portal → Integration Settings → API Key से मिलता है।',
