'Shp_Hook_Register_Token' => 'नीचे “वेबहुक पंजीकृत करें” पर क्लिक करें, और ऐप की API सीक्रेट कुंजी को स्टोर सेटिंग्स में साइनिंग सीक्रेट के रूप में पेस्ट करें।',
'Shp_Hook_Note_Register' => 'पंजीकरण Shopify में सब्सक्रिप्शन बनाता है और उन्हें अपने-आप इस पते पर निर्देशित करता है। इसे Shopify → Settings → Notifications → Webhooks के अंतर्गत मैन्युअल रूप से न जोड़ें: वे किसी दूसरे सीक्रेट से साइन होते हैं और हर डिलीवरी अस्वीकार कर दी जाएगी।',
