'Shp_Hook_Verified_Token' => 'वैध हस्ताक्षर के बिना डिलीवरी अस्वीकार कर दी जाती हैं, इसलिए वेबहुक के काम करने से पहले सीक्रेट सेट होना ज़रूरी है।',
