'Shp_Instant_Push_Hint' => 'बिक्री, वापसी या समायोजन सहेजते ही सिर्फ़ उन्हीं उत्पादों का स्टॉक भेज दिया जाता है, ताकि स्टोर अगले शेड्यूल्ड रन के बजाय कुछ सेकंड में सही हो जाए। और कुछ इंस्टॉल नहीं करना है — स्टॉक भेजना बिक्री का जवाब दिए जाने के बाद चलता है, इसलिए काउंटर को कभी Shopify की प्रतीक्षा नहीं करनी पड़ती।',
