'Shp_G_Lead_Store' => 'इस स्टोर को अपने-आप तालमेल में रखने के लिए क्या चाहिए। यहाँ सब कुछ इसी स्टोर के लिए है — वेबहुक URL और id असली हैं।',
'Shp_G_Lead_Store_Cmd' => 'इस स्टोर को अपने-आप तालमेल में रखने के लिए क्या चाहिए। यहाँ सब कुछ इसी स्टोर के लिए है — वेबहुक URL और id असली हैं, इसलिए कमांड सीधे सर्वर पर कॉपी की जा सकती हैं।',
'Shp_G_Lead_Generic' => 'Shopify स्टोर ERP के साथ अपने-आप तालमेल में कैसे रहता है। उसकी अपनी स्थिति देखने के लिए ऊपर कोई स्टोर चुनें, या इसे ऐसे ही पढ़ें — आप कोई भी स्टोर कनेक्ट करें, वेबहुक URL वही रहता है।',
'Shp_G_Lead_Generic_Cron' => 'Shopify स्टोर ERP के साथ अपने-आप तालमेल में कैसे रहता है। उसकी अपनी स्थिति देखने के लिए ऊपर कोई स्टोर चुनें, या इसे ऐसे ही पढ़ें — आप कोई भी स्टोर कनेक्ट करें, वेबहुक URL और क्रॉन लाइन वही रहते हैं।',
'Shp_G_Ways_Note' => 'ज़्यादातर स्टोर दोनों चलाते हैं: पहला स्टोर को मिनट-दर-मिनट अपडेट रखता है, दूसरा वह सब पकड़ लेता है जो पहले से छूट गया — कोई वेबहुक जो कभी नहीं पहुँचा, Shopify एडमिन में सीधे किया गया बदलाव, या कोई रात जब साइट बंद थी।',
'Shp_G_Both_Need' => 'दोनों तरीकों के लिए पहले यह ज़रूरी है',
'Shp_G_Credentials' => 'Shopify क्रेडेंशियल',
'Shp_G_Cred_Intro' => 'जनवरी 2026 से Shopify एडमिन के अंदर कस्टम ऐप नहीं बनाता, इसलिए कनेक्शन दो प्रकार के होते हैं:',
'Shp_G_Cred_Dev' => '{app} (अब कनेक्ट होने वाला कोई भी स्टोर) — {path}। यह स्टोर जो सिंक करता है उसके लिए Admin API स्कोप दें, ऐप को स्टोर पर इंस्टॉल करें, फिर ऐप के Settings पेज से {clientId} और {clientSecret} को {edit} में कॉपी करें। ERP इनके बदले खुद एक्सेस टोकन लेता है और हर 24 घंटे में उसकी समय-सीमा खत्म होने से पहले उसे नवीनीकृत करता है। क्लाइंट सीक्रेट वेबहुक भी साइन करता है, इसलिए और कुछ नहीं चाहिए। ऐप और स्टोर एक ही Shopify संगठन में होने चाहिए।',
'Shp_G_Dev_App' => 'Dev Dashboard ऐप',
'Shp_G_Cred_Legacy' => '{app} (2026 से पहले एडमिन में बनाया गया) — अपने {token} ({prefix}) और वेबहुक साइनिंग सीक्रेट के रूप में अपनी {secret} के साथ बिना बदलाव के काम करता रहता है। यह टोकन वाला मान नहीं है, और इन्हें उलटा भर देना ही वेबहुक अस्वीकार होने का आम कारण है।',
'Shp_G_Legacy_App' => 'पुराना कस्टम ऐप',
'Shp_G_Api_Secret_Key' => 'API सीक्रेट कुंजी',
'Shp_G_Stored' => 'सहेजा गया',
'Shp_G_Missing_Refused' => 'मौजूद नहीं — डिलीवरी अस्वीकार होंगी',
'Shp_G_Targets' => '{path} वह ERP गोदाम जिसका स्टॉक यह स्टोर बेचता है, और वह Shopify स्थान जहाँ वह स्टॉक लिखा जाता है। इनके बिना इन्वेंट्री सिंक और ऑर्डर आयात दोनों चलने से मना कर देते हैं।',
