'Shp_G_Not_Set_Lc' => 'सेट नहीं है',
'Shp_G_Ready' => 'तैयार',
'Shp_G_Incomplete' => 'अधूरा',
'Shp_G_Manual_Syncs' => 'मैन्युअल रूप से शुरू किए गए सिंक',
'Shp_G_Manual_Body' => '{centre} से शुरू किया गया सिंक तुरंत जवाब देता है और बैकग्राउंड में छोटे-छोटे हिस्सों में चलता है, जिनमें से हर एक वहीं से आगे बढ़ता है जहाँ पिछला रुका था। बड़ा कैटलॉग कभी किसी वेब अनुरोध का समय खत्म होने से बीच में नहीं कटता, और पेज बंद करने से सिंक नहीं रुकता।',
'Shp_G_Worker_Managed' => 'इसके लिए वर्कर आपका प्लेटफ़ॉर्म चलाता है, इसलिए कुछ इंस्टॉल नहीं करना है।',
'Shp_G_Worker_Cron' => 'इसके लिए वर्कर एक और क्रॉन लाइन है:',
'Shp_G_Cron_Copied' => 'क्रॉन लाइन कॉपी की गई',
'Shp_G_Worker_Busy' => 'अगर वर्कर व्यस्त है, तो खुला सिंक सेंटर पेज कुछ सेकंड बाद खुद रन को आगे बढ़ाता है, एक बार में एक छोटा अनुरोध — इसलिए आपके देखते-देखते सिंक हमेशा पूरा हो जाता है।',
'Shp_G_Pick_How' => 'फिर चुनें कि यह तालमेल कैसे बनाए रखे',
'Shp_G_Right_Away' => 'तुरंत',
'Shp_G_Stock_Live' => 'स्टॉक लाइव',
'Shp_G_Stock_Not_Live' => 'स्टॉक लाइव नहीं',
'Shp_G_Realtime_Lead' => 'हर बदलाव होते ही कुछ सेकंड में भेजा जाता है। इसके दो हिस्से हैं, और दोनों के स्विच अलग हैं: {webhooks} स्टोर के अपने इवेंट अंदर लाते हैं, और {push} स्टॉक बाहर भेजता है।',
'Shp_G_Webhooks_Lc' => 'वेबहुक',
'Shp_G_Instant_Push_Lc' => 'तत्काल स्टॉक भेजना',
'Shp_G_Webhooks_Heading' => 'वेबहुक — स्टोर → ERP',
'Shp_G_Webhooks_Body' => 'ऑर्डर, ऑर्डर स्थिति में बदलाव, और Shopify में किए गए उत्पाद, ग्राहक व स्टॉक के बदलाव। स्टोर खोलें और उसके {tab} पर {button} दबाएँ — दो बार दबाना भी सुरक्षित है। Shopify यहाँ पोस्ट करता है:',
'Shp_G_Webhooks_Tab' => 'वेबहुक टैब',
'Shp_G_Webhooks_Note' => 'यह पता इंटरनेट से HTTPS पर पहुँच योग्य होना चाहिए — Shopify {localhost} या {test} डोमेन पर डिलीवरी नहीं करेगा। हर डिलीवरी एक ही बार दर्ज होती है, इसलिए Shopify के दोबारा प्रयास डुप्लिकेट ऑर्डर नहीं बना सकते, और विफल डिलीवरी को दोबारा चलाया जा सकता है। जब तक चरण 1 का साइनिंग सीक्रेट सहेजा नहीं जाता, डिलीवरी अस्वीकार होती हैं।',
'Shp_G_Push_Heading' => 'तत्काल स्टॉक भेजना — ERP → स्टोर',
'Shp_G_People_Miss' => 'यही सेटिंग लोग अक्सर भूल जाते हैं',
'Shp_G_Push_P1' => 'POS बिक्री अपने आप Shopify तक {not} पहुँचती। इसे बंद छोड़ने पर, स्टोर को अगले भंडार भेजने के चरण पर ही पता चलता है — और उस बीच वह ऐसी यूनिट बेच सकता है जो आप काउंटर पर पहले ही बेच चुके हैं।',
'Shp_G_Not' => 'नहीं',
'Shp_G_Push_P2' => '{path} पर {setting} पर टिक करें। बस इतना ही सेटअप है — न वर्कर, न क्रॉन। इसके बाद हर बिक्री, वापसी और समायोजन बिक्री सहेजे जाते ही सिर्फ़ उन्हीं उत्पादों का स्टॉक भेजता है, और बीस लाइनों वाली बिक्री पर बीस नहीं, एक ही बार स्टॉक भेजा जाता है। काउंटर को कभी इसकी प्रतीक्षा नहीं करनी पड़ती।',
'Shp_G_This_Store' => 'यह स्टोर:',
'Shp_G_Push_On' => 'चालू — बदलाव पर स्टॉक भेजा जाता है',
'Shp_G_Push_Off' => 'बंद — स्टॉक केवल शेड्यूल पर',
'Shp_G_Push_Note' => 'केवल वे उत्पाद जिनकी पहले से Shopify मैपिंग है, और केवल इस स्टोर के गोदाम की गतिविधियाँ ही भेजी जाती हैं। थोक कार्य — कोई उत्पाद हटाना, किसी गोदाम को रीसेट करना — बिना कोई इवेंट चलाए स्टॉक लिखते हैं, और यही एक कारण है कि शेड्यूल्ड इन्वेंट्री चरण भी रखा जाए।',
'Shp_G_Nothing_Else' => 'और कुछ इंस्टॉल नहीं करना है',
'Shp_G_Nothing_Else_Body' => 'किसी भी हिस्से को क्यू वर्कर या क्रॉन एंट्री की ज़रूरत नहीं है। आने वाला वेबहुक उसी अनुरोध में संभाला जाता है जो Shopify भेजता है; बाहर जाने वाला स्टॉक पुश उसी प्रोसेस में चलता है जिसने बिक्री संभाली, जवाब वापस जाने के {after} — इसलिए काउंटर कभी Shopify की प्रतीक्षा नहीं करता, और जवाब देना बंद कर चुके स्टोर को दस सेकंड बाद उसकी प्रतीक्षा बंद कर दी जाती है और काम अगले शेड्यूल्ड इन्वेंट्री पुश पर छोड़ दिया जाता है।',
'Shp_G_After' => 'बाद',
'Shp_G_Exception' => 'एक अपवाद: बैकग्राउंड कार्य द्वारा किए गए स्टॉक बदलाव के बाद भेजने के लिए कोई जवाब नहीं होता, इसलिए उसे इसके बजाय {queue} पर क्यू में डाला जाता है।',
'Shp_G_Queue_Managed' => 'आपका प्लेटफ़ॉर्म उस क्यू पर पहले से एक वर्कर चलाता है, इसलिए वे भी अपने-आप चले जाते हैं।',
'Shp_G_Queue_Cron' => 'अगर आप चाहते हैं कि वे भी तुरंत जाएँ, तो उस क्यू को खाली करें:',
'Shp_G_On_Schedule' => 'शेड्यूल पर',
'Shp_G_On_Lc' => 'चालू',
'Shp_G_Off_Lc' => 'बंद',
'Shp_G_Scheduled_Lead' => 'सब कुछ समय-समय पर दोनों दिशाओं में दोबारा जाँचा जाता है। यह रियल-टाइम से धीमा है, लेकिन यही उन स्टोर पर स्टॉक भेजता है जो तत्काल भेजने का उपयोग नहीं करते, यही छूटे हुए वेबहुक को पकड़ता है, और पूरा कैटलॉग ले जाने का यही एकमात्र तरीका है।',
'Shp_G_Nothing_To_Install' => 'कुछ इंस्टॉल नहीं करना है',
'Shp_G_Managed_Body' => 'शेड्यूलर आपके लिए चलाया जाता है: हर पाँच मिनट में आपका प्लेटफ़ॉर्म हर स्टोर से पूछता है कि उसकी योजना का कोई चरण देय है या नहीं, और जो देय हैं उन्हें चलाता है। कोई क्रॉन एंट्री जोड़नी नहीं है और कोई सर्वर नहीं संभालना है।',
'Shp_G_Managed_Note' => 'पाँच मिनट वह सबसे बारीक अंतराल भी है जिसका कोई योजना उपयोग कर सकती है, क्योंकि पाँच मिनट सबसे छोटा चरण अंतराल है। लंबे अंतराल ठीक-ठीक माने जाते हैं — 30 मिनट पर सेट चरण छह बार जाँचा जाता है और एक बार चलता है।',
'Shp_G_Cron_Entry' => 'क्रॉन एंट्री',
'Shp_G_Cron_Body' => 'इसके बिना कुछ भी शेड्यूल्ड नहीं चलता। एक लाइन, केवल इस मॉड्यूल के लिए — इसे आपके द्वारा शेड्यूल की गई बाकी चीज़ों के साथ जोड़ें:',
'Shp_G_Cron_Note' => 'हर पाँच मिनट वह सबसे बारीक अंतराल है जिसका कोई योजना उपयोग कर सकती है, क्योंकि पाँच मिनट सबसे छोटा चरण अंतराल है। इससे बड़ी एंट्री न्यूनतम सीमा बन जाती है — {every15} के साथ, 5 मिनट पर सेट चरण हर 15 मिनट में चलता है। Windows पर Task Scheduler का उपयोग करें: प्रोग्राम {php}, आर्ग्युमेंट {args}, {path} में शुरू किया गया।',
'Shp_G_Switch_On' => 'इसे चालू करें, और योजना चुनें',
'Shp_G_Plan_Body' => '{path} स्विच तय करता है कि शेड्यूलर कुछ कर भी सकता है या नहीं; योजना तय करती है कि वह क्या करे। एक {step} अपने अंतराल के साथ एक दिशा में एक इकाई है — {ex1}, {ex2}। डिफ़ॉल्ट अंतराल हर उस चरण द्वारा उपयोग होता है जिसका अपना बॉक्स खाली है।',
'Shp_G_Step_Lc' => 'चरण',
'Shp_G_Ex1' => 'ऑर्डर · Shopify → ERP हर 15 मिनट',
'Shp_G_Ex2' => 'भंडार · ERP → Shopify हर 30 मिनट',
'Shp_G_Plan_Note' => 'योजना खाली छोड़ें, तो स्टोर डिफ़ॉल्ट अंतराल पर ऑर्डर लाता है और स्टॉक भेजता है, ज़्यादातर स्टोर यही चाहते हैं। ऑर्डर केवल लाए जाते हैं: ग्राहक ऑर्डर Shopify पर ही देते हैं।',
'Shp_G_Schedule_On' => 'शेड्यूल चालू',
'Shp_G_Schedule_Off' => 'शेड्यूल बंद — केवल मैन्युअल',
'Shp_G_When_Runs' => 'कोई चरण वास्तव में कब चलता है',
'Shp_G_When_Body' => 'कोई चरण तब देय होता है जब वही चरण पिछली बार अपने अंतराल से अधिक समय पहले {started} हुआ था, जो रन इतिहास से पढ़ा जाता है। इसलिए मैन्युअल रूप से शुरू किया गया सिंक अगले स्वचालित सिंक को आगे खिसका देता है, और बार-बार विफल होने वाला चरण हर टिक पर नहीं, अपने अंतराल पर दोबारा चलाया जाता है। स्टोर का अवलोकन हर चरण का पिछला रन, अगला देय समय, और रुके होने पर उसका कारण दिखाता है। शेड्यूल पर डालने से पहले पहला कैटलॉग पुश सिंक सेंटर से मैन्युअल रूप से चलाएँ — पहले ड्राई रन के रूप में।',
'Shp_G_Started_Lc' => 'शुरू',
'Shp_G_Where_Setting' => 'हर सेटिंग कहाँ है',
'Shp_G_Where_Note' => 'ये सभी किसी मौजूदा स्टोर पर हैं: {path}, फिर पेंसिल (या स्टोर के अपने पेज पर {edit})।',
'Shp_G_Product_Images' => 'उत्पाद छवियाँ',
'Shp_G_Img1' => '{push} पर तस्वीरें उत्पाद के साथ जाती हैं — पहले मुख्य छवि, फिर गैलरी, फिर हर उस वेरिएंट की एक छवि जिसकी अपनी छवि है, पचास तक।',
'Shp_G_Products_Push' => 'उत्पाद भेजने',
'Shp_G_Img2' => 'वेरिएंट की तस्वीर उत्पाद के साथ अपलोड होती है और फिर {assigned}, Shopify इसी तरह काम करता है: वेरिएंट उत्पाद की किसी एक छवि की ओर इशारा करता है। मुख्य छवि दोबारा उपयोग करने वाला वेरिएंट उसे दो बार अपलोड नहीं करता।',
'Shp_G_Assigned' => 'उस वेरिएंट को सौंपी जाती है',
'Shp_G_Img3' => 'फ़ाइल के रूप में सहेजी गई छवि Shopify पर लिंक नहीं, बल्कि {uploaded} की जाती है, इसलिए यह तब भी काम करती है जब यह इंस्टॉलेशन इंटरनेट से पहुँच योग्य न हो। पेस्ट किए गए लिंक के रूप में जोड़ी गई छवि Shopify को उसी URL के रूप में दी जाती है, जो सार्वजनिक रूप से पहुँच योग्य होना चाहिए।',
'Shp_G_Uploaded' => 'अपलोड',
'Shp_G_Img4' => 'इन्हें तभी दोबारा भेजा जाता है जब ये वास्तव में बदलती हैं — केवल मूल्य बदलने वाला पुश स्टोर की छवियों को नहीं छूता, क्योंकि उन्हें भेजने से पूरा सेट बदल जाता है।',
'Shp_G_Img5' => 'ERP में छवि हटाने से वह Shopify में {not} हटती। उसे वहाँ भी हटाएँ, वरना स्टोर उसे दिखाता रहेगा।',
'Shp_G_Commands' => 'काम की कमांड',
'Shp_G_Command_Copied' => 'कमांड कॉपी की गई',
'Shp_G_Foot' => 'हर सिंक {logs} में लिखता है, और हर स्टोर का अवलोकन दिखाता है कि हर चरण पिछली बार कब चला, अगली बार कब देय है, और कुछ रुका हो तो उसे क्या रोक रहा है। जब कोई सिंक उम्मीद के मुताबिक काम न करे, तो सबसे पहले यहीं देखें।',
'Shp_G_Covers' => 'क्या शामिल है',
'Shp_G_Speed' => 'गति',
'Shp_G_Needs' => 'आवश्यकताएँ',
'Shp_G_Switched_On_At' => 'कहाँ चालू होता है',
'Shp_G_Way_Covers_Rt' => 'Shopify में किए गए ऑर्डर और बदलाव; ERP से निकलने वाला स्टॉक (POS बिक्री, वापसी, समायोजन)',
'Shp_G_Way_Covers_Sc' => 'सब कुछ, दोनों दिशाओं में — कैटलॉग पुश और तेज़ तरीके से छूटी हर चीज़ समेत',
'Shp_G_Seconds' => 'सेकंड',
'Shp_G_Way_Speed_Sc' => 'चरण का अंतराल (5 मिनट से 7 दिन)',
'Shp_G_Way_Needs_Rt' => 'आने वाले वेबहुक के लिए एक सार्वजनिक HTTPS पता और साइनिंग सीक्रेट। बाहर जाने वाले स्टॉक के लिए कुछ नहीं चाहिए',
'Shp_G_Way_Needs_Sc' => 'शेड्यूलर, हर पाँच मिनट में',
'Shp_G_Way_Switch_Sc' => '{path}, साथ में योजना',
'Shp_G_Scope_Orders' => '{a} (60 दिन से पुराने ऑर्डर के लिए {b})',
'Shp_G_Admin_Scopes' => 'Admin API स्कोप',
'Shp_G_Setting' => 'सेटिंग',
'Shp_G_Tab_In_Edit' => 'स्टोर संपादन में टैब',
'Shp_G_Set1' => 'क्लाइंट ID + सीक्रेट या एक्सेस टोकन, साइनिंग सीक्रेट, API संस्करण',
'Shp_G_What1' => 'Shopify ऐप (Dev Dashboard या पुराना कस्टम ऐप) के क्रेडेंशियल।',
'Shp_G_Set2' => 'ERP गोदाम, Shopify स्थान',
'Shp_G_What2' => 'यह स्टोर कौन सा स्टॉक बेचता है, और ऑर्डर कहाँ दर्ज होते हैं।',
'Shp_G_What3' => 'खुदरा, थोक या न्यूनतम मूल्य।',
'Shp_G_Set4' => 'मौजूद न होने वाले उत्पाद / ग्राहक बनाएँ',
'Shp_G_What4' => 'क्या लाते समय वे ERP रिकॉर्ड बनाए जा सकते हैं जिनका मिलान नहीं होता।',
'Shp_G_Set5' => 'कौन सी इकाइयाँ सिंक हों',
'Shp_G_What5' => 'यहाँ बंद का मतलब हर जगह बंद — मैन्युअल, शेड्यूल्ड और वेबहुक।',
'Shp_G_What6' => 'शेड्यूलर स्विच।',
'Shp_G_What7' => 'तत्काल स्टॉक भेजना, बिक्री या समायोजन पर क्यू में डाला जाता है।',
'Shp_G_Set8' => 'डिफ़ॉल्ट अंतराल, और चरणों की योजना',
'Shp_G_What8' => 'क्या अपने-आप चलता है, किस दिशा में, और कितनी बार।',
'Shp_G_Cmd1' => 'हर स्टोर: क्या चलेगा, और कब। कुछ नहीं बदलता।',
'Shp_G_Cmd2' => 'एक स्टोर की पूरी योजना अभी, समय की परवाह किए बिना।',
'Shp_G_Cmd3' => 'पहला कैटलॉग पुश: केवल वे उत्पाद जो अभी लिंक नहीं हुए।',
'Shp_G_Cmd4' => 'किसी तारीख से ऑर्डर बैकफ़िल करें।',
'Shp_G_Cmd5' => 'पूरा चलाकर रिपोर्ट दें, कहीं कुछ लिखे बिना।',
'Shp_Guide_Subtitle' => 'स्टोर कनेक्ट करना, क्या अपने-आप चलता है, और हर सेटिंग कहाँ है',
'Shp_Show_Store_State' => 'किसी स्टोर की अपनी स्थिति दिखाएँ',
