'Agt_Late' => '> 24 घंटे',
'Agt_Check' => 'जाँचें',
'Agt_Correct_Confirm' => 'इस अस्वीकृत दस्तावेज़ के लिए नई संख्या के साथ सुधार जारी करें?',
'Agt_Correct' => 'सुधारें',
'Agt_Guide_What_Title' => 'यह क्या करता है',
'Agt_Guide_What_Body' => 'हर पूर्ण बिक्री AGT इलेक्ट्रॉनिक बीजक के रूप में जारी होती है (बनाते समय भुगतान होने पर FR, अन्यथा FT) और हर प्राप्त वापसी क्रेडिट नोट (NC) के रूप में। हर दस्तावेज़ को उसकी AGT सीरीज़ की अगली संख्या मिलती है, आपकी AGT कुंजी से हस्ताक्षरित होकर AGT को भेजा जाता है, जो कुछ मिनट बाद उसे सत्यापित करता है। रसीद और PDF बीजक पर AGT संख्या, सुरक्षा अंश और एक QR कोड छपता है।',
'Agt_Guide_Steps_Title' => 'सेटअप',
'Agt_Guide_Step_1' => 'Portal do Contribuinte पर ई-इनवॉइसिंग (adesão) में शामिल हों और अपनी AGT प्राइवेट की डाउनलोड करें।',
'Agt_Guide_Step_2' => 'कॉन्फ़िगरेशन टैब पर अपना NIF, प्रतिष्ठान और की दर्ज करें, Homologação चुनें, सहेजें और "कनेक्शन टेस्ट करें" का उपयोग करें।',
'Agt_Guide_Step_3' => 'सीरीज़ टैब पर, चालू वर्ष के लिए आपके द्वारा उपयोग किए जाने वाले प्रत्येक दस्तावेज़ प्रकार (FR, FT, NC) के लिए एक सीरीज़ का अनुरोध करें।',
'Agt_Guide_Step_4' => 'अपनी IVA दरों को AGT कोड से मैप करें और 0% वाली पंक्तियों के लिए छूट कोड सेट करें।',
'Agt_Guide_Step_5' => 'सिस्टम सेटिंग्स > विशेषताएँ में मॉड्यूल चालू करें, एक परीक्षण बिक्री करें और जाँचें कि वह दस्तावेज़ टैब पर मान्य हो जाती है।',
'Agt_Guide_Step_6' => 'जब AGT आपको प्रोडक्शन के लिए स्वीकृत कर दे, तो Produção पर स्विच करें और प्रोडक्शन सीरीज़ का अनुरोध करें।',
'Agt_Guide_Note_1' => 'भेजी जा चुकी बिक्री या वापसी को अब संपादित या हटाया नहीं जा सकता। इसे बिक्री वापसी (क्रेडिट नोट) से सुधारें।',
'Agt_Guide_Note_2' => 'AGT द्वारा अस्वीकृत दस्तावेज़ों को एक नए नंबर से सुधारा जाता है जो अस्वीकृत नंबर का संदर्भ देता है; पुराना नंबर कभी दोबारा उपयोग नहीं होता।',
'Agt_Guide_Note_3' => 'ऑफ़लाइन POS बिक्री सिंक होने पर भेजी जाती है। AGT 24 घंटे से अधिक देर से भेजे गए दस्तावेज़ों पर जुर्माना लगाता है।',
'Agt_Guide_Note_4' => 'एक पंक्ति पर उत्पाद कर और ऑर्डर कर दोनों नहीं हो सकते; AGT को प्रति पंक्ति एक IVA दर चाहिए। शिपिंग को कर-मुक्त पंक्ति के रूप में भेजा जाता है।',
'Agt_Guide_Note_5' => 'AGT का कुल योग प्रति पंक्ति गणना किया जाता है और राउंडिंग के कारण Stocky के कुल से कुछ सेंट भिन्न हो सकता है।',
