'VG_Intro' => 'एक वेरिएबल उत्पाद कई वेरिएंट के रूप में बेचा जाता है। इन्हें विकल्पों से (अनुशंसित) या नामों की सरल सूची के रूप में बनाएँ। हर वेरिएंट का अपना कोड, मूल्य, छवि और स्टॉक होता है।',
'VG_Options_Title' => 'विकल्प मोड (रंग, साइज़...)',
'VG_Opt_Step1' => 'कार्ड हेडर के स्विच को "विकल्प" पर रखें।',
'VG_Opt_Step2' => 'रंग या साइज़ जैसा कोई विकल्प नाम टाइप करें, या सुझावों में से एक चुनें।',
'VG_Opt_Step3' => 'एक मान (उदाहरण के लिए लाल) टाइप करें और Enter दबाएँ। हर मान के लिए दोहराएँ; अल्पविराम से भी मान अलग होते हैं। किसी मान को हटाने के लिए उस पर x क्लिक करें।',
'VG_Opt_Step4' => 'दूसरे या तीसरे विकल्प के लिए "विकल्प जोड़ें" पर क्लिक करें (अधिकतम 3 विकल्प)।',
'VG_Opt_Step5' => '"वेरिएंट बनाएँ" पर क्लिक करें। प्रत्येक संयोजन के लिए एक पंक्ति बनती है और उसका नाम अपने-आप बनता है, उदाहरण के लिए "लाल / S"।',
'VG_Opt_Step6' => 'हर पंक्ति पर लागत और मूल्य दर्ज करें, या "सभी पर लागू करें" में एक मान टाइप करें और उसे हर पंक्ति में कॉपी करने के लिए लागत या मूल्य पर क्लिक करें।',
'VG_Opt_Step7' => 'कोड आपके लिए अपने-आप बनते हैं। अपना कोड टाइप करें या दूसरा कोड बनाने के लिए रिफ़्रेश आइकन पर क्लिक करें।',
'VG_Opt_Step8' => 'वैकल्पिक: किसी विकल्प पर "रंग स्वैच" पर टिक करें और हर मान के लिए एक रंग चुनें; स्टोर इसे रंगीन बिंदु के रूप में दिखाता है।',
'VG_Rows_Title' => 'वेरिएंट पंक्तियाँ',
'VG_Rows_Text' => 'हर पंक्ति में छवि, कोड, बारकोड, लागत, मूल्य, थोक मूल्य और न्यूनतम विक्रय मूल्य होता है। उत्पाद बनाते समय आप हर वेरिएंट के लिए प्रति गोदाम प्रारंभिक स्टॉक भी दर्ज कर सकते हैं। "अपूर्ण" टैग का अर्थ है कि पंक्ति में किसी एक विकल्प का मान नहीं है।',
'VG_List_Title' => 'सरल सूची मोड',
'VG_List_Text' => 'एक पंक्ति जोड़ने के लिए वेरिएंट का नाम टाइप करें और Enter दबाएँ (या जोड़ें पर क्लिक करें), फिर उसका कोड और मूल्य भरें। यह पारंपरिक तरीका है और मौजूदा उत्पादों के लिए उपलब्ध रहता है।',
'VG_Edit_Title' => 'बाद में संपादन',
'VG_Edit_1' => 'एक मान जोड़ें और "वेरिएंट बनाएँ" पर क्लिक करें: केवल छूटे हुए संयोजन जोड़े जाते हैं। मौजूदा पंक्तियों के कोड, मूल्य और इतिहास बने रहते हैं।',
'VG_Edit_2' => 'किसी मान या विकल्प को हटाने से उसका उपयोग करने वाली पंक्तियाँ हट जाती हैं। पहले से सहेजी गई पंक्तियाँ पुष्टि के बाद, उत्पाद सहेजने पर हटाई जाती हैं।',
'VG_Edit_3' => 'जिस वेरिएंट में अभी भी स्टॉक है, उसे हटाया नहीं जा सकता। पहले उसके स्टॉक का समायोजन या स्थानांतरण करें।',
'VG_Edit_4' => '"सरल सूची" पर स्विच करने से पंक्तियाँ और उनके नाम बने रहते हैं, लेकिन विकल्प परिभाषाएँ हट जाती हैं।',
'VG_Store_Title' => 'ऑनलाइन दुकान पर',
'VG_Store_Text' => 'ग्राहक प्रति विकल्प एक मान चुनते हैं, उदाहरण के लिए पहले रंग फिर साइज़। जो संयोजन मौजूद नहीं हैं वे अक्षम होते हैं और स्टॉक से बाहर वाले कटे हुए दिखते हैं। चुना गया वेरिएंट ही कार्ट में जाता है।',
'Style' => 'स्टाइल',
'Max_Options_Reached' => 'एक उत्पाद में अधिकतम 3 विकल्प हो सकते हैं।',
'Variants_Removed' => '{count} डुप्लिकेट वेरिएंट हटाए गए।',
'Remove_Option_Confirm' => 'यह विकल्प हटाएँ? जो वेरिएंट केवल इसी से भिन्न हैं, उन्हें मिला दिया जाएगा।',
'Saved_Variants_Removed_On_Save' => 'यहाँ से हटाए गए सहेजे गए वेरिएंट उत्पाद सहेजने पर हटा दिए जाते हैं।',
'Remove_Option_Values_Confirm' => 'यह मान हटाने से इसका उपयोग करने वाले {count} वेरिएंट भी हट जाएँगे। जारी रखें?',
'Options_Required' => 'मानों के साथ कम से कम एक विकल्प जोड़ें, या सरल सूची पर स्विच करें।',
'Too_Many_Variants' => 'बहुत अधिक वेरिएंट (अधिकतम {max})। विकल्पों के मान कम करें।',
'Variants_Generated' => '{count} वेरिएंट बनाए गए।',
'No_New_Combinations' => 'सभी संयोजन पहले से मौजूद हैं।',
'Switch_To_List_Confirm' => 'सरल सूची पर स्विच करें? विकल्प परिभाषाएँ हटा दी जाएँगी; वेरिएंट पंक्तियाँ बनी रहेंगी।',
'Variant_Missing_Option_Values' => 'हर वेरिएंट में प्रत्येक विकल्प का एक मान होना चाहिए।',
'Fashion_Theme' => 'फ़ैशन और परिधान थीम',
'Fashion_Theme_Hint' => 'संपादकीय शैली का कपड़ों का स्टोरफ्रंट: सेरिफ़ शीर्षक, बड़ी तस्वीरें, श्रेणी टाइलें, श्रेणी टैब के साथ नए आगमन, एक लुकबुक बैनर और एक सेल पंक्ति। उत्पाद कार्ड पर साइज़ दिखते हैं (बिक चुके साइज़ कटे हुए) और होवर करने पर गैलरी की दूसरी फ़ोटो दिखती है। आपका प्राथमिक रंग सेल कीमतों और बैज के लिए उपयोग होता है। हीरो स्लाइडर और लुकबुक बैनर नीचे जोड़ने के बाद दिखाई देते हैं।',
'FaSection_categories' => 'श्रेणी टाइलें',
'FaSection_new_arrivals' => 'नए आगमन',
