'FaSection_brands' => 'ब्रांड',
'Announcement_Bar_Text' => 'घोषणा पट्टी का टेक्स्ट',
'New_Arrivals_Title' => 'नए आगमन का शीर्षक',
'Best_Sellers_Title' => 'सबसे ज़्यादा बिकने वाले का शीर्षक',
'Sale_Kicker' => 'सेल लेबल',
'Sale_Title' => 'सेल शीर्षक',
'Show_Sizes_On_Cards' => 'उत्पाद कार्ड पर साइज़ दिखाएँ',
'Card_Quick_Add' => 'उत्पाद कार्ड पर क्विक ऐड',
'Fashion_Sizes_Hint' => 'साइज़ "Size" (साइज़) नाम वाले उत्पाद विकल्प (उत्पाद > वेरिएंट विकल्प) से, या S, M, L या 38 जैसे वेरिएंट नामों से लिए जाते हैं। जिन उत्पादों में केवल साइज़ विकल्प है, उन्हें सीधे कार्ड से कार्ट में जोड़ा जा सकता है।',
'Fashion_Category_Tiles_Auto' => 'जब नीचे कोई टाइल नहीं जोड़ी गई हो, तो मेरी सबसे बड़ी श्रेणियाँ दिखाएँ (उनके उत्पादों की एक फ़ोटो के साथ)',
'Lookbook_Banners' => 'लुकबुक बैनर',
'Size_Guides_Hint' => 'साइज़ गाइड एक साइज़ चार्ट है (एक तालिका, एक छवि, या दोनों)। हर उत्पाद पर एक चुनें (उत्पाद > संपादित करें > आकार मार्गदर्शिका) और खरीदारों को उत्पाद पेज पर "आकार मार्गदर्शिका" लिंक मिलेगा।',
'Size_Guide_Name_Placeholder' => 'जैसे महिलाओं की ड्रेसें',
'Size_Guide_Image_Hint' => 'वैकल्पिक। एक चार्ट छवि अपलोड करें (उदाहरण के लिए नाप लेने का तरीका दिखाने वाला चित्र)। केवल छवि वाली गाइड उसी छवि को चार्ट के रूप में दिखाती है।',
'Size_Guide_Template' => 'टेम्पलेट से शुरू करें',
'Size_Guide_Tpl_Women' => 'महिलाओं के कपड़े',
'Size_Guide_Tpl_Men' => 'पुरुषों के कपड़े',
'Size_Guide_Tpl_Shoes' => 'जूते (EU / UK / US)',
'Add_Column' => 'कॉलम जोड़ें',
'Column_Header' => 'हेडर',
'Size_Guide_Columns_Hint' => 'साइज़, छाती, कमर और कूल्हे जैसे कॉलम जोड़ें, या किसी टेम्पलेट से शुरू करें।',
'Size_Guide_Rows' => 'पंक्तियाँ',
'Add_Row' => 'पंक्ति जोड़ें',
'Size_Guide_No_Rows' => 'अभी तक कोई पंक्ति नहीं',
'Remove_Image' => 'छवि हटाएँ',
'Size_Guide_Product_Hint' => 'ऑनलाइन दुकान के उत्पाद पेज पर "आकार मार्गदर्शिका" लिंक के रूप में दिखाया जाता है।',
'Select_Sales_Agent' => 'बिक्री एजेंट चुनें',
'No_Sales_Agent' => 'कोई एजेंट नहीं',
'Pos_Sales_Agent_Hint' => 'चुने गए एजेंट को इस बिक्री पर कमीशन मिलता है। कोई एजेंट न होने पर, कमीशन विक्रेता से जुड़े एजेंट को मिलता है।',
'Sold_By' => 'किसने बेचा',
'Auto_Sales_Agent' => 'स्वचालित',
'Commission_Guide' => 'कमीशन गाइड',
'Comm_G_Intro_Title' => 'एक वाक्य में, कमीशन कैसे काम करता है',
'Comm_G_Intro' => 'जब कोई पूर्ण बिक्री सहेजी जाती है, तो बिक्री के बिक्री एजेंट से मेल खाने वाले नियम लंबित कमीशन बनाते हैं। आप उन्हें कमीशन रिपोर्ट में स्वीकृत करते हैं और कमीशन रसीद से उनका भुगतान करते हैं। अगर बाद में बिक्री बदलती है (भुगतान, वापसी, संपादन, हटाना), तो उसके कमीशन की अपने-आप पुनर्गणना होती है।',
'Comm_G_Your_Setup' => 'आपका सेटअप',
'Comm_G_Your_Setup_Help' => 'इस वर्कस्पेस की लाइव स्थिति। प्रत्येक चरण पूरा होने पर हरा हो जाता है।',
'Comm_G_Optional' => 'अनुशंसित',
'Comm_G_Step_Program' => 'एक कमीशन कार्यक्रम बनाएँ',
'Comm_G_Step_Program_Help' => 'एक कार्यक्रम आपके नियमों को समूहित करता है, उदाहरण के लिए "2026 सेल्स टीम" या "समर कैंपेन"। यह सक्रिय होना चाहिए, और आज की तारीख इसकी "से वैध" और "तक वैध" तारीखों के बीच होनी चाहिए।',
'Comm_G_Step_Program_Warn' => 'आपके पास कार्यक्रम हैं, लेकिन आज कोई भी सक्रिय नहीं है। "सक्रिय" बॉक्स और "से वैध" / "तक वैध" तारीखें जाँचें।',
'Comm_G_Step_Agent' => 'अपने बिक्री एजेंट जोड़ें',
'Comm_G_Step_Agent_Help' => 'बिक्री एजेंट वह व्यक्ति है जो कमीशन कमाता है। एजेंट स्टाफ़ सदस्य या रेफ़र करने वाले या रीसेलर जैसे बाहरी लोग हो सकते हैं।',
'Comm_G_Step_Link' => 'एजेंटों को उपयोगकर्ता खातों से जोड़ें',
'Comm_G_Step_Link_Help' => 'किसी एजेंट को उपयोगकर्ता से जोड़ने पर उस उपयोगकर्ता की बिक्री अपने-आप उस एजेंट के खाते में जाती है, हर बिक्री पर एजेंट चुनने की ज़रूरत नहीं पड़ती।',
'Comm_G_Step_Link_Warn' => '{n} सक्रिय एजेंट किसी उपयोगकर्ता से जुड़े नहीं हैं। वे तभी कमाते हैं जब कोई उन्हें बिक्री पर चुनता है।',
'Comm_G_Step_Rule' => 'कम से कम एक नियम जोड़ें',
'Comm_G_Step_Rule_Help' => 'नियम बताता है कि कितना भुगतान करना है, उदाहरण के लिए बिक्री कुल का 5%। यह सक्रिय होना चाहिए और ऐसे कार्यक्रम का हिस्सा होना चाहिए जो आज सक्रिय है।',
'Comm_G_Step_Rule_Warn' => 'आपके पास नियम हैं, लेकिन आज सक्रिय किसी कार्यक्रम में कोई भी नियम सक्रिय नहीं है।',
'Comm_G_Step_Sale' => 'एक पूर्ण बिक्री करें',
'Comm_G_Step_Sale_Help' => 'कमीशन तब बनते हैं जब कोई पूर्ण बिक्री सहेजी जाती है (बिक्री बनाएँ, बिक्री संपादित करें या POS)। आपके नियम बनने से पहले की गई बिक्री की गणना नहीं होती।',
'Comm_G_Step_Sale_Done' => 'अब तक {n} कमीशन की गणना हुई।',
'Comm_G_Step_Approve' => 'कमीशन स्वीकृत करें',
'Comm_G_Step_Approve_Help' => 'कमीशन रिपोर्ट में, जिन लंबित पंक्तियों से आप सहमत हैं उन पर टिक करें और "स्वीकृत" पर क्लिक करें। अभी कुछ भी प्रतीक्षा में नहीं है।',
'Comm_G_Step_Approve_Warn' => '{n} कमीशन स्वीकृति की प्रतीक्षा में हैं।',
'Comm_G_Step_Pay' => 'अपने एजेंटों को भुगतान करें',
'Comm_G_Step_Pay_Help' => 'कमीशन रसीदें में, एक एजेंट चुनें, उसके स्वीकृत कमीशन पर टिक करें और रसीद सहेजें। वे "भुगतान किया गया" हो जाते हैं। अभी भुगतान के लिए कुछ भी प्रतीक्षा में नहीं है।',
'Comm_G_Step_Pay_Warn' => '{n} स्वीकृत कमीशन भुगतान की प्रतीक्षा में हैं।',
'Comm_G_Try_Rule' => 'नियम आज़माएँ',
'Comm_G_Try_Rule_Help' => 'नियम ठीक-ठीक कितना भुगतान करेगा, यह देखने के लिए एक बिक्री और एक नियम दर्ज करें। गणना वही है जो सिस्टम उपयोग करता है।',
'Comm_G_Sale_Total' => 'बिक्री कुल',
'Comm_G_None' => 'कोई नहीं',
'Comm_G_Commission' => 'इस नियम का कमीशन',
'Comm_G_No_Commission' => 'कोई कमीशन नहीं',
'Comm_G_Calc_Base' => 'आधार राशि ({source}): {base}',
'Comm_G_Calc_Zero_Base' => 'आधार राशि 0 है, इसलिए यह नियम कुछ नहीं बनाता। स्रोत के रूप में "भुगतान की गई राशि" होने पर, अदत्त बिक्री तब तक कुछ नहीं कमाती जब तक कोई भुगतान दर्ज न हो।',
'Comm_G_Calc_Below_Min' => 'आधार {min} की न्यूनतम सीमा से कम है, इसलिए यह नियम इस बिक्री के लिए कुछ नहीं बनाता।',
'Comm_G_Calc_Pct' => '{base} का {value}% = {amount}',
'Comm_G_Calc_Fixed' => 'निश्चित राशि: प्रति बिक्री {amount}, बिक्री का आकार चाहे जो हो',
'Comm_G_Calc_Capped' => 'अधिकतम सीमा से अधिक, इसलिए इसे घटाकर {cap} किया गया',
'Comm_G_Calc_Zero' => 'परिणाम 0 है, इसलिए कोई कमीशन नहीं बनता।',
'Comm_G_The_Flow' => 'प्रक्रिया, चरण दर चरण',
'Comm_G_Flow_Program' => 'कार्यक्रम',
'Comm_G_Flow_Program_Help' => 'एक कार्यक्रम बनाएँ और वे तारीखें सेट करें जिनके लिए यह मान्य है।',
'Comm_G_Flow_Agent' => 'बिक्री एजेंट',
'Comm_G_Flow_Agent_Help' => 'कमीशन कमाने वाले लोगों को जोड़ें और स्टाफ़ को उनके उपयोगकर्ता खातों से जोड़ें।',
'Comm_G_Flow_Rule' => 'नियम',
'Comm_G_Flow_Rule_Help' => 'कार्यक्रम के अंदर नियम जोड़ें: प्रतिशत या निश्चित, सभी एजेंटों के लिए या एक एजेंट के लिए।',
'Comm_G_Flow_Sale' => 'बिक्री',
'Comm_G_Flow_Sale_Help' => 'एक पूर्ण बिक्री सहेजी जाती है। हर मेल खाने वाला नियम एक लंबित कमीशन बनाता है।',
'Comm_G_Flow_Approve' => 'स्वीकृत करें',
'Comm_G_Flow_Approve_Help' => 'कमीशन रिपोर्ट में लंबित कमीशन की समीक्षा करें और उन्हें स्वीकृत या रद्द करें।',
'Comm_G_Flow_Pay' => 'भुगतान करें',
'Comm_G_Flow_Pay_Help' => 'एजेंट के लिए एक कमीशन रसीद दर्ज करें। इसमें शामिल कमीशन "भुगतान किया गया" हो जाते हैं।',
'Comm_G_How_It_Works' => 'यह कैसे काम करता है',
'Comm_G_T_Credit' => 'कमीशन किस एजेंट को मिलता है?',
'Comm_G_Credit_Intro' => 'हर बिक्री का श्रेय अधिकतम एक एजेंट को जाता है। सिस्टम इस क्रम में जाँच करता है:',
'Comm_G_Credit_Picked' => 'बिक्री पर चुना गया बिक्री एजेंट: बिक्री बनाएँ और बिक्री संपादित करें पर "बिक्री एजेंट" फ़ील्ड, या POS पर "किसने बेचा" बटन। अगर वह एजेंट बाद में निष्क्रिय कर दिया गया है, तो बिक्री कुछ नहीं कमाती; यह अगले विकल्पों पर नहीं जाती।',
'Comm_G_Credit_Seller' => 'अन्यथा, POS पर चुने गए विक्रेता से जुड़ा एजेंट (जब POS विक्रेता स्विच चालू हो)।',
'Comm_G_Credit_Cashier' => 'अन्यथा, बिक्री सहेजने वाले उपयोगकर्ता से जुड़ा एजेंट।',
'Comm_G_Credit_Nobody' => 'अगर इनमें से किसी से भी सक्रिय एजेंट नहीं मिलता, तो बिक्री पर कोई कमीशन नहीं बनता।',
'Comm_G_Credit_Note' => 'POS पर, एजेंट को "स्वचालित" पर छोड़ने से विकल्प 2 और 3 उपयोग होते हैं। "स्वचालित" के बगल में दिखाया गया नाम उस एजेंट का है जिसे श्रेय मिलेगा।',
'Comm_G_T_When' => 'कमीशन की गणना और अपडेट कब होता है?',
'Comm_G_When_Intro' => 'कमीशन पहली बार तब बनते हैं जब "पूर्ण" स्थिति वाली बिक्री इनमें से किसी भी जगह सहेजी जाती है:',
'Comm_G_When_Create' => 'बिक्री बनाएँ: जब बिक्री "पूर्ण" के रूप में सहेजी जाती है।',
'Comm_G_When_Edit' => 'बिक्री संपादित करें: पूर्ण बिक्री सहेजने पर उसके मौजूदा कुल, भुगतान और एजेंट के साथ शुरू से पुनर्गणना होती है, जिसमें रद्द किए गए कमीशन भी शामिल हैं।',
'Comm_G_When_Pos' => 'POS: जब बिक्री पूर्ण होती है, जिसमें बाद में पूर्ण किया गया ड्राफ्ट भी शामिल है।',
'Comm_G_When_Payment' => 'पूर्ण बिक्री में भुगतान जोड़ना, जिससे "भुगतान की गई राशि" वाले नियम बिक्री के बाद लिए गए भुगतान भी पकड़ पाते हैं।',
'Comm_G_When_Cod' => 'कूरियर कैश ऑन डिलीवरी: जब कूरियर द्वारा एकत्रित नकद को बिक्री पर भुगतान के रूप में दर्ज किया जाता है।',
'Comm_G_When_Not_Intro' => 'इनसे कमीशन नहीं बनते:',
'Comm_G_When_Not_Status' => 'लंबित या ऑर्डर किया गया के रूप में सहेजी गई बिक्री। इन्हें संपादित करके "पूर्ण" के रूप में सहेजने पर ये कमाना शुरू करती हैं।',
'Comm_G_When_Not_Before' => 'कार्यक्रम या नियम के बनने से पहले सहेजी गई बिक्री। पृष्ठभूमि में इनकी गणना नहीं होती। ऐसी बिक्री को "बिक्री संपादित करें" में खोलकर सहेजने पर बिक्री की तारीख पर सक्रिय नियमों के साथ उसकी गणना होती है।',
'Comm_G_When_Not_Import' => 'फ़ाइल से इम्पोर्ट की गई बिक्री।',
'Comm_G_When_Not_Online' => 'ऑनलाइन दुकान पर दिए गए ऑर्डर।',
'Comm_G_T_Statuses' => 'कमीशन की स्थितियाँ',
'Comm_G_Meaning' => 'इसका क्या अर्थ है',
'Comm_G_S_Pending' => 'अभी-अभी किसी बिक्री से गणना हुई। अभी किसी ने इसकी जाँच नहीं की है। इसे कमीशन रिपोर्ट में स्वीकृत या रद्द करें।',
'Comm_G_S_Approved' => 'जाँचा गया और सहमति दी गई। यह एजेंट को देय है और कमीशन रसीद में शामिल किया जा सकता है। अगर बिक्री बदलती है और राशि बदल जाती है, तो यह दोबारा समीक्षा के लिए लंबित में लौट जाता है।',
'Comm_G_S_Paid' => 'कमीशन रसीद में शामिल। अंतिम: भुगतान किए गए कमीशन कभी नहीं बदलते। अगर बाद में बिक्री बदलती है, तो अंतर एक अलग समायोजन के रूप में जोड़ा जाता है।',
'Comm_G_S_Cancelled' => 'भुगतान नहीं किया जाएगा। बाद में भुगतान या वापसी आने पर भी यह रद्द ही रहता है। बिक्री को "बिक्री संपादित करें" में सहेजने, या रिपोर्ट में इस पर टिक करके "पुनर्गणना करें" पर क्लिक करने से इसकी फिर से गणना होती है।',
'Comm_G_Field' => 'फ़ील्ड',
'Comm_G_T_Programs' => 'कमीशन कार्यक्रम',
'Comm_G_Programs_Body' => 'कार्यक्रम नियमों का एक समूह है, आमतौर पर प्रति अवधि या अभियान एक। कोई नियम तभी काम करता है जब उसका कार्यक्रम सक्रिय हो और बिक्री की तारीख कार्यक्रम की तारीखों के भीतर हो। एक ही समय में कई कार्यक्रम सक्रिय हो सकते हैं, और सभी लागू होते हैं।',
'Comm_G_F_Program_Name' => 'कोई भी नाम जो कार्यक्रम पहचानने में मदद करे, उदाहरण के लिए "Q4 2026" या "ब्लैक फ़्राइडे"।',
'Comm_G_F_Program_Active' => 'कार्यक्रम के सभी नियमों को एक साथ रोकने के लिए इसका टिक हटाएँ। पहले से बने कमीशन प्रभावित नहीं होते।',
'Comm_G_F_Program_From' => 'इस दिन से पहले की तारीख वाली बिक्री को कार्यक्रम अनदेखा करता है। कोई प्रारंभ तिथि न रखने के लिए इसे खाली छोड़ें।',
'Comm_G_F_Program_To' => 'इस दिन के बाद की तारीख वाली बिक्री को कार्यक्रम अनदेखा करता है। कभी समाप्त न होने वाले कार्यक्रम के लिए इसे खाली छोड़ें।',
'Comm_G_T_Agents' => 'बिक्री एजेंट',
'Comm_G_Agents_Body' => 'बिक्री एजेंट वह व्यक्ति है जो कमीशन कमाता है। एजेंट का सिस्टम का उपयोगकर्ता होना ज़रूरी नहीं है: बाहरी रेफ़रर या रीसेलर भी एजेंट हो सकते हैं, और जब भी उन्हें किसी बिक्री पर चुना जाता है तो वे कमाते हैं।',
'Comm_G_F_Agent_Name' => 'बिक्री, रिपोर्ट और रसीदों पर दिखाया जाने वाला नाम।',
'Comm_G_F_Agent_Code' => 'वैकल्पिक संदर्भ, जैसे कर्मचारी संख्या। एजेंट सूची में खोजा जा सकता है।',
'Comm_G_F_Agent_User' => 'एजेंट को किसी स्टाफ़ उपयोगकर्ता से जोड़ता है। उस उपयोगकर्ता द्वारा की गई बिक्री (या जिनके लिए उसे POS पर विक्रेता चुना गया) का श्रेय अपने-आप इस एजेंट को जाता है।',
'Comm_G_F_Agent_Active' => 'निष्क्रिय एजेंट नई बिक्री पर कुछ नहीं कमाते और एजेंट चयन सूचियों से गायब हो जाते हैं। उनके पिछले कमीशन बने रहते हैं।',
'Comm_G_T_Rules' => 'कमीशन नियम: हर फ़ील्ड की व्याख्या',
'Comm_G_Rules_Body' => 'नियम तय करता है कि किसी बिक्री पर कितना भुगतान होगा। नियम सहेजने से पहले उसे जाँचने के लिए ऊपर दिए "नियम आज़माएँ" बॉक्स का उपयोग करें।',
'Comm_G_F_Rule_Program' => 'वह कार्यक्रम जिसका यह नियम हिस्सा है। नियम तभी काम करता है जब वह कार्यक्रम सक्रिय हो और उसकी तारीखों के भीतर हो।',
'Comm_G_F_Rule_Type' => 'प्रतिशत आधार राशि का एक हिस्सा देता है। निश्चित हर योग्य बिक्री पर, उसके आकार की परवाह किए बिना, एक ही राशि देता है।',
'Comm_G_F_Rule_Source' => 'प्रतिशत किस पर लिया जाता है। "बिक्री कुल" बिक्री का कुल योग है। "भुगतान की गई राशि" वह है जो कमीशन की गणना के समय तक ग्राहक ने भुगतान किया था।',
'Comm_G_F_Rule_Value' => 'प्रकार के अनुसार, प्रतिशत (5 का अर्थ 5%) या निश्चित राशि।',
'Comm_G_F_Rule_Min' => 'वैकल्पिक। जिन बिक्री की आधार राशि इससे कम है, वे इस नियम से कुछ नहीं कमातीं। ठीक सीमा के बराबर वाली बिक्री कमाती है।',
'Comm_G_F_Rule_Cap' => 'वैकल्पिक। यह नियम एक बिक्री पर अधिकतम कितना भुगतान कर सकता है। प्रतिशत और निश्चित दोनों नियमों पर लागू होता है।',
'Comm_G_F_Rule_Applies' => 'सभी एजेंट: हर एजेंट इस नियम से कमाता है। विशिष्ट एजेंट: केवल आपके द्वारा चुना गया एजेंट। बिना चुने एजेंट वाला विशिष्ट एजेंट नियम किसी को भुगतान नहीं करता।',
'Comm_G_F_Rule_Priority' => '"केवल सर्वोच्च प्राथमिकता वाला नियम भुगतान करता है" पर सेट कार्यक्रम में, सबसे बड़ी संख्या वाला योग्य नियम जीतता है और बाकी छोड़ दिए जाते हैं। बराबरी होने पर, विशिष्ट एजेंट नियम सभी एजेंट नियम से ऊपर रहता है। "हर मेल खाने वाला नियम भुगतान करता है" पर सेट कार्यक्रम में, प्राथमिकता केवल क्रम तय करती है।',
'Comm_G_F_Rule_Active' => 'केवल इस नियम को रोकने के लिए इसका टिक हटाएँ। इसके द्वारा पहले से बने कमीशन प्रभावित नहीं होते।',
'Comm_G_T_Stacking' => 'एक बिक्री पर कई नियम',
'Comm_G_Stacking_Body' => 'हर कार्यक्रम तय करता है कि उसके नियम कैसे मिलते हैं (कार्यक्रम पर "जब कई नियम मेल खाएँ" सेटिंग)।

केवल सर्वोच्च प्राथमिकता वाला नियम भुगतान करता है (नए कार्यक्रमों के लिए डिफ़ॉल्ट): नियम सबसे ऊँची प्राथमिकता से नीचे की ओर आज़माए जाते हैं, और बिक्री के लिए योग्य होने वाला पहला नियम भुगतान करता है। कोई नियम तब योग्य होता है जब बिक्री उसकी न्यूनतम सीमा तक पहुँचती है और परिणाम 0 से अधिक होता है। इससे स्तर बनाना आसान होता है: प्राथमिकता 10 पर "10,000 या उससे अधिक की बिक्री पर 7%" और प्राथमिकता 0 पर "5%"। सारा को विशेष दर देने के लिए, सभी एजेंट नियम से ऊँची प्राथमिकता वाला उसके लिए एक विशिष्ट एजेंट नियम जोड़ें।

हर मेल खाने वाला नियम भुगतान करता है: सभी मेल खाने वाले नियम भुगतान करते हैं और राशियाँ जुड़ जाती हैं। 3% का सभी एजेंट नियम और सारा के लिए 2% का विशिष्ट एजेंट नियम सारा को 5% देता है।

कार्यक्रम एक-दूसरे से अलग हैं: हर सक्रिय कार्यक्रम अपने-आप में भुगतान करता है, इसलिए एक बिक्री एक ही समय में आधार कार्यक्रम और अभियान कार्यक्रम दोनों से कमा सकती है।',
'Comm_G_T_Paying' => 'कमीशन रसीदों से एजेंटों को भुगतान',
'Comm_G_Paying_Body' => 'कमीशन रसीदें खोलें और जोड़ें पर क्लिक करें। एजेंट चुनें: उसके स्वीकृत कमीशन सूचीबद्ध हो जाते हैं। जिनका आप भुगतान कर रहे हैं उन पर टिक करें; राशि उनके कुल से भर जाती है, और आप इसे समायोजित कर सकते हैं। संदर्भ अपने-आप भरता है (CR-000001, CR-000002...), और आप भुगतान का तरीका, तारीख और एक नोट जोड़ सकते हैं।

रसीद सहेजने पर टिक किए गए कमीशन "भुगतान किया गया" के रूप में चिह्नित हो जाते हैं और रसीद से जुड़ जाते हैं। केवल स्वीकृत कमीशन का भुगतान किया जा सकता है, इसलिए पहले उन्हें कमीशन रिपोर्ट में स्वीकृत करें।

ऋणात्मक समायोजन (एजेंट को अधिक भुगतान की गई राशि) भी सूचीबद्ध होते हैं। उन्हें एजेंट के अगले कमीशन के साथ टिक करें ताकि वे उस भुगतान से घट जाएँ।

रसीद केवल भुगतान का रिकॉर्ड है: यह कोई व्यय नहीं बनाती और न ही आपके खातों में पैसा स्थानांतरित करती है। अगर आप भुगतान व्यय या लेखांकन में ट्रैक करते हैं, तो उन्हें वहाँ भी दर्ज करें।',
'Comm_G_T_Snapshot' => 'जब कोई बिक्री बदलती है',
'Comm_G_Snapshot_Body' => 'कमीशन बिक्री के साथ चलते हैं। जब भी कमीशन वाली कोई बिक्री बदलती है, तो उसके मौजूदा आँकड़ों से उनकी पुनर्गणना होती है: बिक्री कुल में से प्राप्त वापसियाँ घटाकर, और भुगतान की गई राशि में से रिफ़ंड घटाकर।

अदत्त कमीशन (लंबित या स्वीकृत) बस अपडेट हो जाते हैं। जिस स्वीकृत कमीशन की राशि बदलती है, वह लंबित में लौट जाता है ताकि कोई इसे फिर से जाँचे। जो अब देय नहीं है (बिक्री हटाई गई, पूरी वापसी हुई, एजेंट बदला गया), उसे हटा दिया जाता है।

भुगतान किए गए कमीशन कभी नहीं बदलते। अंतर समायोजन के रूप में चिह्नित एक नई लंबित पंक्ति बन जाता है: अधिक देय होने पर धनात्मक (उदाहरण के लिए "भुगतान की गई राशि" वाली बिक्री का बाकी भुगतान हो गया), एजेंट को अधिक भुगतान होने पर ऋणात्मक (उदाहरण के लिए वापसी के बाद)। इसे स्वीकृत करें और एजेंट की अगली रसीद में शामिल करें।

हर कमीशन नियम की वे शर्तें (प्रकार, दर, सीमा, अधिकतम सीमा) रखता है जो उसके पहली बार कमाए जाने के समय थीं। बाद में किसी नियम को बदलने या बंद करने से पुनर्गणना होने पर पुरानी बिक्री की कीमत दोबारा तय नहीं होती।',
'Comm_G_T_Permissions' => 'कौन क्या कर सकता है',
'Comm_G_Permission' => 'अनुमति',
'Comm_G_Lets_You' => 'यह क्या करने देता है',
'Comm_G_P_View' => 'सभी कमीशन पेज देखें: कार्यक्रम, एजेंट, नियम, रसीदें, रिपोर्ट और यह गाइड।',
'Comm_G_P_Add' => 'कार्यक्रम, एजेंट और नियम बनाएँ, और कमीशन रसीदें दर्ज करें (एजेंटों को भुगतान करें)।',
'Comm_G_P_Edit' => 'कार्यक्रम, एजेंट और नियम संपादित करें, और कमीशन रिपोर्ट में कमीशन स्वीकृत या रद्द करें।',
'Comm_G_P_Delete' => 'कार्यक्रम, एजेंट और नियम हटाएँ।',
'Comm_G_T_Faq' => 'प्रश्न और उत्तर',
'Comm_G_Q_Empty' => 'मैंने सब कुछ सेट कर दिया, लेकिन कमीशन रिपोर्ट खाली है।',
'Comm_G_A_Empty' => 'जाँचें कि: बिक्री नियम बनने के बाद सहेजी गई थी; बिक्री पूर्ण है; बिक्री में एक एजेंट है (बिक्री पर चुना गया, या बिक्री करने वाला उपयोगकर्ता किसी एजेंट से जुड़ा है); कार्यक्रम सक्रिय है और बिक्री की तारीख उसकी तारीखों के भीतर है; नियम सक्रिय है और उस एजेंट पर लागू होता है; और बिक्री नियम की न्यूनतम सीमा के बराबर या उससे अधिक है। रिपोर्ट का तारीख फ़िल्टर भी जाँचें: यह कमीशन की गणना की तारीख के अनुसार फ़िल्टर करता है।',
'Comm_G_Q_Twice' => 'एक एजेंट को एक बिक्री पर दो कमीशन मिले।',
'Comm_G_A_Twice' => 'दो नियमों ने भुगतान किया: या तो कार्यक्रम "हर मेल खाने वाला नियम भुगतान करता है" पर सेट है, या नियम दो अलग-अलग सक्रिय कार्यक्रमों में हैं (हर कार्यक्रम अपने-आप में भुगतान करता है)। अगर केवल एक को भुगतान करना चाहिए, तो कार्यक्रम को "केवल सर्वोच्च प्राथमिकता वाला नियम भुगतान करता है" पर सेट करें। बिक्री दोबारा सहेजने से कभी कोई कमीशन डुप्लिकेट नहीं होता।',
'Comm_G_Q_Rate' => 'अगर मैं किसी नियम की दर बदलूँ, तो क्या पुराने कमीशन बदलेंगे?',
'Comm_G_A_Rate' => 'नहीं। हर कमीशन उस नियम की शर्तें रखता है जिसके तहत वह कमाया गया था, भले ही बाद में उसकी बिक्री की पुनर्गणना हो। नई दर अब से कमाए जाने वाले कमीशन पर लागू होती है।',
'Comm_G_Q_Return' => 'ग्राहक ने सामान वापस कर दिया। कमीशन का क्या होगा?',
'Comm_G_A_Return' => 'यह अपने-आप घट जाता है। प्राप्त वापसी बिक्री कुल को घटाती है और रिफ़ंड भुगतान की गई राशि को घटाता है। अगर कमीशन का अभी भुगतान नहीं हुआ है, तो यह अपडेट हो जाता है (या पूरी वापसी पर हटा दिया जाता है)। अगर इसका पहले ही भुगतान हो चुका है, तो एक ऋणात्मक समायोजन जोड़ा जाता है और एजेंट की अगली रसीद से घटा दिया जाता है।',
'Comm_G_Q_Wrong_Agent' => 'मैंने गलत एजेंट को श्रेय दे दिया। मैं इसे कैसे ठीक करूँ?',
'Comm_G_A_Wrong_Agent' => 'बिक्री संपादित करें, सही बिक्री एजेंट चुनें और सहेजें। कमीशन सही एजेंट के पास चले जाते हैं। अगर पहले एजेंट को पहले ही भुगतान हो चुका था, तो उसके लिए एक ऋणात्मक समायोजन जोड़ा जाता है।',
'Comm_G_Q_Inactive' => 'किसी एजेंट को निष्क्रिय करने पर क्या होता है?',
'Comm_G_A_Inactive' => 'वह नई बिक्री पर कमाना बंद कर देता है और एजेंट चयन सूचियों से छिप जाता है। उसके मौजूदा कमीशन बने रहते हैं, अभी भी स्वीकृत और भुगतान किए जा सकते हैं, और उसकी बिक्री में बदलावों के साथ चलते रहते हैं। जिस बिक्री को उस एजेंट को चुनकर सहेजा गया था, वह किसी दूसरे एजेंट पर नहीं जाएगी।',
'Comm_G_Q_Partial' => '"भुगतान की गई राशि" वाले नियम आंशिक भुगतान को कैसे संभालते हैं?',
'Comm_G_A_Partial' => 'अदत्त बिक्री कुछ नहीं कमाती। कमीशन तब बनता है जब पहली बार पैसा प्राप्त होता है (चेकआउट पर या भुगतान जोड़ने पर) और जैसे-जैसे और भुगतान आते हैं, बढ़ता है। अगर इसका कुछ हिस्सा पहले ही भुगतान किया जा चुका था, तो बाकी धनात्मक समायोजन के रूप में आता है।',
'Comm_G_Q_Undo' => 'क्या मैं किसी भुगतान या रद्दीकरण को पूर्ववत कर सकता हूँ?',
'Comm_G_A_Undo' => 'भुगतान, नहीं: "भुगतान किया गया" अंतिम है और रसीदें संपादित या हटाई नहीं जा सकतीं, इसलिए सहेजने से पहले टिक किए गए कमीशन और राशि जाँच लें। रद्दीकरण, हाँ: कमीशन रिपोर्ट में पंक्ति पर टिक करें और "पुनर्गणना करें" पर क्लिक करें, या बिक्री को "बिक्री संपादित करें" में फिर से सहेजें।',
'Comm_G_Q_Dates' => 'कार्यक्रम की तारीखें कौन-सी तारीख उपयोग करती हैं?',
'Comm_G_A_Dates' => 'बिक्री की अपनी तारीख, न कि वह दिन जब उसे सहेजा गया। पिछले महीने की तारीख वाली बिक्री केवल उन्हीं कार्यक्रमों का उपयोग करती है जो पिछले महीने मान्य थे।',
'Comm_G_When_Changes' => 'इसके बाद, जिस बिक्री के पहले से कमीशन हैं उसमें कोई भी बदलाव उन्हें अपने-आप अपडेट कर देता है: भुगतान संपादित या हटाए जाना, वापसी और रिफ़ंड, स्थिति का "पूर्ण" से बदलना, या बिक्री का हटाया जाना।',
'Comm_G_F_Program_Mode' => 'जब इस कार्यक्रम के कई नियम एक ही बिक्री से मेल खाते हैं तो क्या होता है। "केवल सर्वोच्च प्राथमिकता वाला नियम भुगतान करता है": नियम सबसे ऊँची प्राथमिकता से नीचे की ओर आज़माए जाते हैं और योग्य होने वाला पहला नियम भुगतान करता है। "हर मेल खाने वाला नियम भुगतान करता है": सभी भुगतान करते हैं और राशियाँ जुड़ जाती हैं।',
'Comm_G_Q_Mode_Old' => 'मैंने प्राथमिकताएँ सेट कीं, लेकिन नियम अभी भी जुड़ रहे हैं।',
'Comm_G_A_Mode_Old' => 'वह कार्यक्रम "हर मेल खाने वाला नियम भुगतान करता है" पर सेट है। इस सेटिंग के आने से पहले बने कार्यक्रम यही व्यवहार रखते हैं ताकि उनके भुगतान न बदलें। कार्यक्रम संपादित करें और "केवल सर्वोच्च प्राथमिकता वाला नियम भुगतान करता है" चुनें।',
'Comm_G_Q_Negative' => 'ऋणात्मक कमीशन क्यों है?',
'Comm_G_A_Negative' => 'यह एक समायोजन है: एजेंट को उससे अधिक भुगतान किया गया जितना बिक्री अब कमाती है, किसी वापसी, रिफ़ंड, कम कुल, बदले गए एजेंट या हटाई गई बिक्री के कारण। इसे स्वीकृत करें और एजेंट की अगली रसीद में इस पर टिक करें ताकि यह घटा दिया जाए।',
'Comm_Rule_Mode' => 'जब कई नियम मेल खाएँ',
'Comm_Mode_Highest' => 'केवल सर्वोच्च प्राथमिकता वाला नियम भुगतान करता है',
'Comm_Mode_All' => 'हर मेल खाने वाला नियम भुगतान करता है (राशियाँ जुड़ती हैं)',
'Comm_Mode_Highest_Short' => 'सर्वोच्च प्राथमिकता जीतती है',
'Comm_Mode_All_Short' => 'नियम जुड़ते हैं',
'Comm_Mode_Highest_Help' => 'नियम सबसे ऊँची प्राथमिकता से नीचे की ओर आज़माए जाते हैं; बिक्री के लिए योग्य होने वाला पहला नियम भुगतान करता है और बाकी छोड़ दिए जाते हैं। स्तरों के लिए उपयुक्त, उदाहरण के लिए प्राथमिकता 10 पर 10,000 से ऊपर 7% और प्राथमिकता 0 पर बाकी सब पर 5%।',
'Comm_Mode_All_Help' => 'एजेंट से मेल खाने वाला हर नियम बिक्री पर भुगतान करता है, इसलिए राशियाँ जुड़ जाती हैं। प्राथमिकता केवल क्रम तय करती है।',
'Comm_Priority_Help_Highest' => 'यह कार्यक्रम केवल सर्वोच्च प्राथमिकता वाले योग्य नियम का भुगतान करता है। इस नियम को उन नियमों से ऊँची प्राथमिकता दें जिनसे इसे जीतना चाहिए। बराबरी होने पर, विशिष्ट एजेंट नियम सभी एजेंट नियम से ऊपर रहता है।',
'Comm_Priority_Help_All' => 'यह कार्यक्रम हर मेल खाने वाले नियम का भुगतान करता है, इसलिए यह नियम बाकी में जुड़ता है। प्राथमिकता केवल क्रम तय करती है।',
'Comm_Recalculate' => 'पुनर्गणना करें',
'Comm_Recalculate_Help' => 'टिक की गई पंक्तियों की बिक्री की उनके मौजूदा आँकड़ों से फिर से गणना करता है, जिसमें रद्द किए गए कमीशन भी शामिल हैं।',
'Comm_Adjustment' => 'समायोजन',
'Comm_Adjustment_Help' => 'पहले से भुगतान किए गए कमीशन में सुधार, क्योंकि बाद में बिक्री बदल गई। ऋणात्मक राशि एजेंट की अगली रसीद से घटा दी जाती है।',
'Comm_Cancel_Confirm' => 'चयनित कमीशन रद्द करें?',
'Comm_Cancel_Confirm_Help' => 'इनका भुगतान नहीं किया जाएगा, और बाद में भुगतान या वापसी आने पर भी ये रद्द ही रहेंगे। बिक्री को "बिक्री संपादित करें" में सहेजने या "पुनर्गणना करें" पर क्लिक करने से इनकी फिर से गणना होती है।',
'Fashion_Tiles_Hint' => 'स्वचालित श्रेणी टाइलों के स्थान पर अपनी टाइलें (छवि, शीर्षक और लिंक) जोड़ें।',

