// Restaurant Management — guide page
'Rst_Guide' => 'गाइड',
'Rst_Guide_Subtitle' => 'रेस्टोरेंट सेट करें और चरण-दर-चरण जानें कि एक सर्विस कैसे चलती है',
'Rst_Guide_Module_Off' => 'इस खाते के लिए रेस्टोरेंट मॉड्यूल सक्रिय नहीं है',
'Rst_Guide_Module_Off_Help' => 'इसके लिए आपकी योजना में रेस्टोरेंट सुविधा और सेटिंग्स › मॉड्यूल में मॉड्यूल चालू होना ज़रूरी है। तब तक ऑनलाइन ऑर्डरिंग, QR मेनू और ऑनलाइन बुकिंग छिपे रहते हैं।',
'Rst_Guide_Your_Setup' => 'आपका सेटअप',
'Rst_Guide_Your_Setup_Help' => 'हर बार यह पृष्ठ खोलने पर आपके अपने डेटा से जाँचा जाता है। ऊपर से शुरू करें; वैकल्पिक चरण बाद में किए जा सकते हैं।',
