'Rst_Guide_Step_Db_Ok' => 'रेस्टोरेंट की सभी डेटाबेस तालिकाएँ मौजूद हैं।',
'Rst_Guide_Step_Db_Help' => 'रेस्टोरेंट की कुछ डेटाबेस तालिकाएँ मौजूद नहीं हैं। नवीनतम डेटाबेस अपडेट (tenant migrations) चलाएँ और यह पृष्ठ फिर से लोड करें।',
'Rst_Guide_Step_Settings' => 'रेस्टोरेंट सेटिंग्स',
'Rst_Guide_Step_Settings_Ok' => 'ऑर्डर प्रकार: {types}। एक डिफ़ॉल्ट शाखा सेट है।',
'Rst_Guide_Step_Settings_Help' => 'चुनें कि आप कौन से ऑर्डर प्रकार लेते हैं, रेस्टोरेंट बिक्री किस शाखा का स्टॉक उपयोग करे, सर्विस चार्ज, टिप और राउंड-ऑफ़।',
'Rst_Guide_Step_Floor' => 'डाइनिंग क्षेत्र और टेबल',
'Rst_Guide_Step_Floor_Ok' => '{areas} क्षेत्र, {tables} टेबल।',
'Rst_Guide_Step_Floor_Help' => 'अपने क्षेत्र (अंदर, टेरेस…) और उनकी टेबल सीटों की संख्या के साथ जोड़ें। "कई जोड़ें" एक बार में T1–T20 बना देता है।',
'Rst_Guide_Step_Stations' => 'किचन स्टेशन',
'Rst_Guide_Step_Stations_Ok' => '{n} स्टेशन।',
'Rst_Guide_Step_Stations_Help' => 'स्टेशन (ग्रिल, फ्रायर, कोल्ड, डेज़र्ट, ड्रिंक्स…) किचन डिस्प्ले को बाँटते हैं ताकि हर कुक केवल अपने व्यंजन देखे।',
'Rst_Guide_Step_Dishes' => 'व्यंजन और ऐड-ऑन',
'Rst_Guide_Step_Dishes_Ok' => '{n} व्यंजन सेट, {groups} ऐड-ऑन समूह।',
'Rst_Guide_Step_Dishes_Help' => 'व्यंजन आपके सामान्य उत्पाद ही हैं। रेस्टोरेंट › मेनू में उन्हें स्टेशन, तैयारी का समय, आहार टैग और ऐड-ऑन समूह (साइज़, एक्स्ट्रा) दें।',
'Rst_Guide_Step_Payments' => 'भुगतान',
'Rst_Guide_Step_Payments_Ok' => '{n} भुगतान विधियाँ तैयार, नकद सहित, और बिना बुकिंग आए ग्राहकों के बिलों के लिए एक डिफ़ॉल्ट ग्राहक।',
'Rst_Guide_Step_Payments_Help' => 'बिलों के लिए कम से कम एक सक्रिय भुगतान विधि, एक नकद विधि (छुट्टे नकद से लौटाए जाते हैं) और सिस्टम सेटिंग्स में एक डिफ़ॉल्ट ग्राहक चाहिए।',
'Rst_Guide_Step_Staff' => 'स्टाफ़ अनुमतियाँ',
'Rst_Guide_Step_Staff_Help' => 'ऑर्डर ले सकने वाली भूमिकाएँ: {waiters}, किचन डिस्प्ले उपयोग कर सकने वाली: {kitchen}, भुगतान ले सकने वाली: {cashiers}। हर भूमिका को केवल वही दें जो उस काम के लिए ज़रूरी है ("कौन क्या करता है" देखें)।',
'Rst_Guide_Step_First' => 'आपका पहला बिल',
'Rst_Guide_Step_First_Ok' => 'अब तक {n} बिल लिए गए।',
'Rst_Guide_Step_First_Help' => 'फ़्लोर प्लान पर एक टेस्ट टेबल पर मेहमान बैठाएँ, एक व्यंजन जोड़ें, उसे भेजें, किचन डिस्प्ले पर उसे तैयार चिह्नित करें और भुगतान लें।',
'Rst_Guide_Step_Qr' => 'QR टेबल ऑर्डरिंग',
'Rst_Guide_Step_Qr_On' => 'चालू। {n} टेबल पर QR कोड है।',
'Rst_Guide_Step_Qr_Help' => 'मेहमान टेबल पर लगा कोड स्कैन करते हैं, अपने फ़ोन पर व्यंजन चुनते हैं और उन्हें टेबल के ऑर्डर में भेजते हैं। इसे रेस्टोरेंट सेटिंग्स में चालू करें, फिर कोड प्रिंट करें।',
'Rst_Guide_Step_Booking' => 'ऑनलाइन टेबल बुकिंग',
'Rst_Guide_Step_Booking_On' => 'चालू। ऑनलाइन दुकान से आने वाली बुकिंग पुष्टि के लिए आरक्षण में आती हैं।',
'Rst_Guide_Step_Booking_Help' => 'मेहमानों को ऑनलाइन दुकान से टेबल बुक करने दें। बुकिंग के घंटे, अंतराल और सबसे बड़ा समूह रेस्टोरेंट सेटिंग्स में सेट करें।',
'Rst_Guide_Step_Store' => 'ऑनलाइन दुकान और रेस्टोरेंट थीम',
'Rst_Guide_Step_Store_On' => 'रेस्टोरेंट थीम सक्रिय है। ऑनलाइन ऑर्डर रसोई तक पहुँचते हैं: {mode}।',
'Rst_Guide_Step_Store_Help' => 'ऑनलाइन दुकान › सेटिंग्स में "रेस्टोरेंट" थीम चुनें: होमपेज आपका मेनू बन जाता है, ऐड-ऑन, पिकअप / डिलीवरी और टेबल बुकिंग के साथ।',
'Rst_Guide_How' => 'यह कैसे काम करता है',
'Rst_Guide_Service' => 'एक सर्विस, चरण-दर-चरण',
'Rst_Guide_Service_1_T' => 'बैठाएँ',
'Rst_Guide_Service_1' => 'फ़्लोर प्लान पर कोई खाली टेबल चुनें, मेहमानों की संख्या और वेटर दर्ज करें, फिर "मेहमानों को बैठाएँ और ऑर्डर लें"। बुकिंग वाले समूह को उसकी बुकिंग से बैठाया जाता है।',
'Rst_Guide_Service_2_T' => 'ऑर्डर',
'Rst_Guide_Service_2' => 'ऑर्डर स्क्रीन पर व्यंजनों पर टैप करें। ऐड-ऑन, सीट और कोर्स चुनें; रसोई के लिए नोट जोड़ें। किसी कोर्स को बाद में शुरू कराने के लिए उसे रोकें।',
'Rst_Guide_Service_3_T' => 'भेजें',
'Rst_Guide_Service_3' => '"भेजें" नए व्यंजनों को एक किचन टिकट पर डालता है। जो व्यंजन अभी नहीं भेजे गए, उन्हें अब भी बदला या हटाया जा सकता है; उसके बाद उन्हें केवल कारण के साथ वॉयड किया जा सकता है।',
'Rst_Guide_Service_4_T' => 'पकाएँ',
'Rst_Guide_Service_4' => 'किचन डिस्प्ले हर स्टेशन पर टिकट दिखाता है। कुक उसे शुरू करते हैं, व्यंजन पूरे होते ही उन पर टिक करते हैं और सब तैयार होने पर उसे बम्प करते हैं।',
'Rst_Guide_Service_5_T' => 'परोसें',
'Rst_Guide_Service_5' => 'तैयार व्यंजन फ़्लोर प्लान और ऑर्डर स्क्रीन पर दिखते हैं। वेटर उन्हें ले जाता है और "परोसा गया चिह्नित करें" पर टैप करता है।',
'Rst_Guide_Service_6_T' => 'बिल',
'Rst_Guide_Service_6' => '"बिल और भुगतान" बिल प्रिंट करता है और भुगतान लेता है: पूरा बिल, बराबर बाँटकर या आइटम के अनुसार। हर भुगतान एक सामान्य POS बिक्री है।',
'Rst_Guide_Service_7_T' => 'खाली करें',
'Rst_Guide_Service_7' => 'सब कुछ भुगतान हो जाने पर ऑर्डर बंद हो जाता है और टेबल "सफ़ाई चाहिए" हो जाती है (या रेस्टोरेंट सेटिंग्स के अनुसार सीधे खाली)।',
'Rst_Guide_Roles' => 'कौन क्या करता है',
'Rst_Guide_Roles_Help' => 'रेस्टोरेंट अनुमतियाँ समूह अनुमतियाँ में हर भूमिका के अनुसार दी जाती हैं। एक उपयोगकर्ता के पास कई भूमिकाओं जितनी अनुमतियाँ हो सकती हैं।',
'Rst_Guide_Job' => 'काम',
'Rst_Guide_Give' => 'ये अनुमतियाँ दें',
'Rst_Guide_Job_Waiter' => 'वेटर',
