'Rst_Guide_Job_Supervisor' => 'सुपरवाइज़र',
'Rst_Guide_Job_Manager' => 'मैनेजर',
'Rst_Guide_Menu' => 'मेनू, स्टेशन और ऐड-ऑन',
'Rst_Guide_Menu_1' => 'आप जो भी उत्पाद बेचते हैं, वह व्यंजन हो सकता है। रेस्टोरेंट › मेनू (या उत्पाद फ़ॉर्म पर "व्यंजन विवरण" कार्ड) रेस्टोरेंट की जानकारी जोड़ता है।',
'Rst_Guide_Menu_2' => 'ऐड-ऑन समूहों में कीमत वाले विकल्प होते हैं: "साइज़" (1 चुनें) या "एक्स्ट्रा" (अधिकतम 3)। नियम हर ऑर्डर पर जाँचे जाते हैं, ऑनलाइन भी।',
'Rst_Guide_Menu_3' => 'कोई ऐड-ऑन किसी सामग्री का उपयोग कर सकता है: "एक्स्ट्रा चीज़" को अपने चीज़ उत्पाद से लिंक करें और हर बार वह उतना स्टॉक घटाएगा।',
'Rst_Guide_Menu_4' => 'एक स्विच से किसी व्यंजन को आज के लिए बिक गया चिह्नित करें; वह कल अपने आप वापस आ जाता है। भोजन के समय (नाश्ता, दोपहर, रात का भोजन) तय करते हैं कि कोई व्यंजन कब उपलब्ध है।',
'Rst_Guide_Menu_5' => 'रेसिपी एक कॉम्बो उत्पाद है: वर्चुअल कॉम्बो स्टॉक चालू होने पर व्यंजन बेचने से उसके घटक स्टॉक से घटते हैं।',
'Rst_Guide_Kitchen' => 'किचन डिस्प्ले',
'Rst_Guide_Kitchen_1' => 'रसोई की किसी स्क्रीन पर रेस्टोरेंट › रसोई खोलें। स्टेशन चुनें; बिना स्टेशन वाले व्यंजन हर स्टेशन पर दिखते हैं।',
'Rst_Guide_Kitchen_2' => 'प्रतीक्षा बढ़ने पर टिकट पहले एम्बर और फिर लाल हो जाते हैं (रेस्टोरेंट सेटिंग्स › N मिनट बाद देर)। नए टिकट आने पर बीप बजती है।',
'Rst_Guide_Kitchen_3' => 'शुरू करें → व्यंजनों पर टिक करें → बम्प। "इस स्टेशन पर पूरा" साझा टिकट पर केवल इस स्टेशन के व्यंजन पूरे करता है।',
'Rst_Guide_Kitchen_4' => 'परोसे गए टिकट 15 मिनट तक रहते हैं ताकि गलती होने पर उन्हें वापस लाया जा सके। टिकट 80 mm प्रिंटर पर प्रिंट किए जा सकते हैं।',
'Rst_Guide_Kitchen_5' => 'ऑनलाइन दुकान और टेबल QR कोड से आए ऑर्डर उनके टिकट पर "ऑनलाइन" या "QR" से चिह्नित होते हैं।',
'Rst_Guide_Bills' => 'बिल और भुगतान',
'Rst_Guide_Bills_1' => 'हर भुगतान एक सामान्य POS बिक्री है: स्टॉक, कैश रजिस्टर, लेखांकन, लॉयल्टी पॉइंट्स और ई-इनवॉइसिंग POS की तरह ही काम करते हैं।',
'Rst_Guide_Bills_2' => 'सर्विस चार्ज कर से पहले व्यंजनों का प्रतिशत है, डाइन-इन के लिए (या आपकी सेटिंग के अनुसार हर ऑर्डर पर)। टिप पहले से तय प्रतिशत या कोई राशि होती है।',
'Rst_Guide_Bills_3' => 'छूट के लिए "रेस्टोरेंट छूट" अनुमति चाहिए और उसकी सीमा रेस्टोरेंट सेटिंग्स में दी गई सबसे बड़ी छूट तक होती है।',
'Rst_Guide_Bills_4' => 'राउंड-ऑफ़ आपके तय अंतराल तक नीचे की ओर होता है, मेहमान के पक्ष में, उस भुगतान पर जो बिल चुकता करता है।',
'Rst_Guide_Bills_5' => 'बराबर बाँटें: एक बिक्री, हर व्यक्ति के लिए एक भुगतान पंक्ति (हिस्से पैसे तक सटीक)। आइटम के अनुसार बाँटें: हर मेहमान के व्यंजन उसकी अपनी बिक्री बनते हैं; किसी सीट के व्यंजन चुनने के लिए वह सीट चुनें।',
'Rst_Guide_Bills_6' => 'अगर बिल दिखाए जाने के बाद बदल गया (QR कोड से कोई व्यंजन जुड़ा, टिप बदली), तो भुगतान अस्वीकार कर दिया जाता है ताकि मेहमान से कभी ऐसी चीज़ का शुल्क न लिया जाए जो उन्होंने नहीं देखी।',
'Rst_Guide_Bills_7' => 'भुगतान हो चुके व्यंजन वॉयड नहीं किए जा सकते। अगर किसी ऑर्डर का बिना भुगतान वाला बाकी हिस्सा वॉयड किया जाता है, तो ऑर्डर भुगतान हो गया के रूप में बंद हो जाता है और टेबल खाली की जा सकती है।',
'Rst_Guide_Bookings' => 'आरक्षण और प्रतीक्षा सूची',
'Rst_Guide_Bookings_1' => 'बुकिंग अपनी अवधि के लिए टेबल रोककर रखती है (डिफ़ॉल्ट रेस्टोरेंट सेटिंग्स में)। किसी टेबल पर दो बुकिंग कभी एक-दूसरे पर नहीं चढ़ सकतीं।',
'Rst_Guide_Bookings_2' => 'फ़्लोर प्लान हर टेबल की अगली बुकिंग दिखाता है और उसके जल्द आने पर चेतावनी देता है; "वे आ गए हैं — बैठाएँ" समूह को बैठा देता है।',
'Rst_Guide_Bookings_3' => 'नो-शो समय के बाद देर से आने वाले समूह को नो-शो चिह्नित किया जा सकता है; गलती होने पर बहाल किया जा सकता है।',
'Rst_Guide_Bookings_4' => 'प्रतीक्षा सूची बिना बुकिंग आए मेहमानों को उनके बताए गए प्रतीक्षा समय के साथ क्रम में रखती है। टेबल तैयार होने पर उन्हें कॉल या WhatsApp करें, फिर बैठाएँ।',
'Rst_Guide_Bookings_5' => 'ऑनलाइन बुकिंग "बुक किया गया" के रूप में आती हैं (साइडबार बैज उन्हें गिनता है), ताकि आप उनकी पुष्टि करें।',
'Rst_Guide_Online' => 'ऑनलाइन ऑर्डर, QR मेनू और ऑनलाइन बुकिंग',
'Rst_Guide_Online_1' => 'रेस्टोरेंट स्टोर थीम के साथ ऑनलाइन दुकान का होमपेज आपका मेनू होता है, ऐड-ऑन और आहार फ़िल्टर के साथ; ग्राहक हमेशा की तरह चेकआउट पर भुगतान करते हैं।',
'Rst_Guide_Online_2' => '"रसोई को ऑनलाइन ऑर्डर" तय करता है कि वे किचन डिस्प्ले तक कब पहुँचें: ऑर्डर देते ही (भुगतान हो चुका हो, या साइन-इन ग्राहक डिलीवरी / पिकअप पर भुगतान कर रहा हो), स्वीकार होने पर, या कभी नहीं।',
'Rst_Guide_Online_3' => 'टेबल QR कोड (फ़्लोर सेटअप › टेबल QR कोड) उस टेबल के लिए मेनू खोलते हैं। "नया लिंक" किसी प्रिंट किए गए कोड को बंद कर देता है।',
'Rst_Guide_Online_4' => 'QR ऑर्डर टेबल के ऑर्डर में रुके रहते हैं और कोई वेटर उन्हें भेजता है, बशर्ते "QR ऑर्डर सीधे रसोई को भेजें" चालू न हो। मेहमान स्टाफ़ को भुगतान करते हैं।',
'Rst_Guide_Online_5' => 'ऑनलाइन बुकिंग केवल वही समय दिखाती है जब समूह के लायक कोई टेबल पूरी बुकिंग के लिए खाली हो, और हर फ़ोन नंबर को अधिकतम 3 आगामी बुकिंग तक सीमित रखती है।',
'Rst_Guide_Online_6' => 'यह सब ऑनलाइन दुकान का हिस्सा है: इसे चालू होना चाहिए और आपकी योजना में शामिल होना चाहिए।',
'Rst_Guide_Reports' => 'डैशबोर्ड और रिपोर्ट',
'Rst_Guide_Reports_1' => 'डैशबोर्ड आज की तुलना पिछले सप्ताह के इसी दिन से दिखाता है: बिक्री, बिल, मेहमान, औसत बिल, वॉयड और छूट, साथ ही इस समय क्या चल रहा है।',
'Rst_Guide_Reports_2' => 'बिक्री में रेस्टोरेंट बिल और रसोई तक पहुँचे ऑनलाइन ऑर्डर शामिल हैं। व्यंजन बिक्री और मार्जिन कर से पहले के हैं, हर उत्पाद की लागत के आधार पर।',
'Rst_Guide_Reports_3' => 'रिपोर्ट: दिन और भुगतान विधि के अनुसार बिक्री, व्यंजन, वॉयड और रद्दीकरण (कारणों सहित), स्टाफ़, रसोई के समय और आरक्षण — हर एक Excel में निर्यात होती है।',
'Rst_Guide_Reports_4' => 'कुछ ही शाखाओं तक सीमित स्टाफ़ केवल अपनी शाखाएँ देखता है; बिना शाखा वाले ऑर्डर सभी के साथ साझा होते हैं।',
'Rst_Guide_Faq' => 'जानने योग्य बातें',
'Rst_Guide_Faq_1_Q' => 'मेरे "भेजें" दबाने से पहले ही एक टेकअवे का भुगतान हो गया। क्या वह पकाया जाएगा?',
'Rst_Guide_Faq_1_A' => 'हाँ। भुगतान करने पर जो व्यंजन अभी नहीं भेजे गए थे, वे रसोई को भेज दिए जाते हैं।',
'Rst_Guide_Faq_2_Q' => 'मैं टेबल खाली क्यों नहीं कर पा रहा/रही?',
'Rst_Guide_Faq_2_A' => 'उसके ऑर्डर में अभी बिना भुगतान वाले व्यंजन हैं। भुगतान लें, जो नहीं खाया गया उसे वॉयड करें, या ऑर्डर रद्द करें (केवल तब जब अभी कुछ भी भुगतान न हुआ हो)।',
'Rst_Guide_Faq_3_Q' => 'दो टेबल आपस में जोड़ दी गईं। उनके ऑर्डर का क्या होगा?',
'Rst_Guide_Faq_3_A' => '"टेबल जोड़ें" दूसरी टेबल के व्यंजन (और कोई भी भुगतान) मुख्य टेबल के ऑर्डर पर ले जाता है; "अलग करें" टेबल को फिर से अलग कर देता है।',
'Rst_Guide_Faq_4_Q' => 'क्या यहाँ कार्ड भुगतान Stripe का उपयोग कर सकते हैं?',
'Rst_Guide_Faq_4_A' => 'नहीं। Stripe कार्ड भुगतान के लिए POS कार्ड फ़ॉर्म चाहिए; कार्ड टर्मिनल के लिए "कार्ड" जैसी भुगतान विधि जोड़ें और बिल पर उसी का उपयोग करें।',
'Rst_Guide_Faq_5_Q' => 'कोई व्यंजन केवल एक शाखा में स्टॉक से बाहर है।',
'Rst_Guide_Faq_5_A' => 'स्टॉक ऑर्डर की शाखा से लिया जाता है (टेबल के क्षेत्र से, वरना रेस्टोरेंट सेटिंग्स की डिफ़ॉल्ट शाखा से)। ऑर्डर जल्दी रोकने के लिए "आज के लिए बिक गया" का उपयोग करें।',
'Rst_Guide_Faq_6_Q' => 'क्या मुझे प्रिंटर चाहिए?',
'Rst_Guide_Faq_6_A' => 'नहीं। बिल, रसीदें और किचन टिकट ब्राउज़र से किसी भी प्रिंटर पर प्रिंट होते हैं; 80 mm रसीद प्रिंटर सबसे उपयुक्त हैं।',
'Rst_Guide_Faq_7_Q' => 'ऑनलाइन दुकान में रेस्टोरेंट मेनू कहाँ से आते हैं?',
'Rst_Guide_Faq_7_A' => 'उन्हीं उत्पादों, श्रेणियों और ऐड-ऑन से। ऑनलाइन दुकान से छिपाए गए उत्पाद और स्टोर में न दिखाई जाने वाली श्रेणियाँ ऑनलाइन मेनू और QR मेनू में नहीं आतीं।',

// Rental — business types + website booking (Rental store theme).
'Rental_Website_Not_Ready' => 'व्यवसाय प्रकार और वेबसाइट बुकिंग का उपयोग करने के लिए नवीनतम अपडेट इंस्टॉल करें।',
'Rental_Business_Type' => 'व्यवसाय प्रकार',
'Rental_Business_Type_Help' => 'टिक करें कि आप क्या किराये पर देते हैं। फिर आइटम फ़ॉर्म, श्रेणियाँ, फ़िल्टर और आपकी वेबसाइट केवल ये प्रकार और उनके फ़ील्ड दिखाएँगे।',
'Rental_Business_Type_All' => 'कुछ भी टिक नहीं: हर प्रकार उपलब्ध है।',
'Rental_Website_Booking' => 'वेबसाइट बुकिंग',
'Rental_Website_Theme_Off' => 'आपकी ऑनलाइन दुकान कोई दूसरी थीम उपयोग करती है। अपने किराये के आइटम प्रकाशित करने के लिए स्टोर सेटिंग्स में रेंटल थीम चुनें।',
'Rental_Open_Store_Settings' => 'स्टोर सेटिंग्स खोलें',
'Rental_Website_Booking_Help' => 'आगंतुक आपकी वेबसाइट पर तारीखें चुनकर बुकिंग अनुरोध भेजते हैं। यह आरक्षण में होल्ड के रूप में आता है: इसकी पुष्टि करें, इसे अनुबंध में बदलें या रद्द करें।',
'Rental_Website_Hold' => 'अनुरोध को इतनी देर होल्ड रखें',
'Rental_Website_Hold_Help' => 'जब तक आप जवाब देते हैं, आइटम इतनी देर ब्लॉक रहते हैं। पुष्टि करने पर वे किराये की अवधि खत्म होने तक ब्लॉक रहते हैं।',
'Rental_Website_Notice' => 'न्यूनतम पूर्व सूचना',
'Rental_Website_Notice_Help' => 'वेबसाइट बुकिंग अब से कितनी जल्दी शुरू हो सकती है।',
'Rental_Website_Ahead' => 'इतने आगे तक बुक करें',
'Rental_Website_Ahead_Help' => 'आगंतुक कितने आगे तक बुक कर सकते हैं।',
'Rental_Website_Login' => 'साइन-इन आवश्यक',
'Rental_Website_Login_Help' => 'केवल स्टोर खाते वाले ग्राहक ही अनुरोध भेज सकते हैं।',
'Rental_Pickup_Locations' => 'पिकअप स्थान',
'Rental_Pickup_Locations_Help' => 'वाहन: वे स्थान जिन्हें ग्राहक पिकअप और वापसी के लिए चुन सकते हैं। अगर सब कुछ आपकी शाखा से ही लिया जाता है तो खाली छोड़ें।',
'Rental_Pickup_Locations_Placeholder' => 'जैसे एयरपोर्ट; शहर केंद्र कार्यालय',
'Rental_Booking_Form_Fields' => 'बुकिंग फ़ॉर्म फ़ील्ड',
'Rental_Booking_Form_Fields_Help' => 'व्यवसाय प्रकार के अनुसार वेबसाइट बुकिंग फ़ॉर्म क्या पूछता है। नाम, फ़ोन और ईमेल हमेशा पूछे जाते हैं।',
