'Bkm_Guide_Step_Store_Off' => 'बुकिंग थीम चुनी गई है, लेकिन ऑनलाइन दुकान बंद है।',
'Bkm_Guide_Step_Store_Help' => 'बुकिंग फ़ॉर्म को अपने होम पेज पर लाने के लिए ऑनलाइन दुकान › स्टोर सेटिंग्स में बुकिंग थीम चुनें।',
'Bkm_Guide_Step_Mail' => 'ईमेल सेटअप',
'Bkm_Guide_Step_Mail_Ok' => 'पुष्टि और रिमाइंडर ईमेल से भेजे जा सकते हैं।',
'Bkm_Guide_Step_Mail_Help' => 'मेल सर्वर के बिना कोई बुकिंग ईमेल नहीं जाता। सेटिंग्स › मेल में अपना सर्वर जोड़ें।',
'Bkm_Guide_Mail_Settings' => 'मेल सेटिंग्स',
'Bkm_Guide_Step_First' => 'आपकी पहली बुकिंग',
'Bkm_Guide_Step_First_Ok' => 'अब तक {n} बुकिंग, {web} वेबसाइट से।',
'Bkm_Guide_Step_First_Help' => 'ग्राहक क्या देखते हैं यह जानने के लिए वेबसाइट से खुद बुक करें, फिर अनुरोध में उसकी पुष्टि करें।',
'Bkm_Guide_Step_Deposit' => 'ऑनलाइन अग्रिम राशि लें',
'Bkm_Guide_Step_Deposit_Ok' => 'अग्रिम राशि चालू है और {n} भुगतान प्रदाता इसे ले सकते हैं।',
'Bkm_Guide_Step_Deposit_No_Gateway' => 'अग्रिम राशि चालू है, लेकिन इसके लिए कोई भुगतान प्रदाता सेट नहीं है, इसलिए कोई अग्रिम राशि नहीं माँगी जाती।',
'Bkm_Guide_Step_Deposit_Help' => 'नो-शो कम करने के लिए, ग्राहकों के बुक करते समय मूल्य का कुछ हिस्सा माँगें।',
'Bkm_Guide_Step_Whatsapp' => 'WhatsApp संदेश',
'Bkm_Guide_Step_Whatsapp_Ok' => 'WhatsApp जुड़ा हुआ है; बुकिंग संदेश वहाँ भी भेजे जाते हैं।',
'Bkm_Guide_Step_Whatsapp_Help' => '"WhatsApp से भी भेजें" चालू है, लेकिन WhatsApp जुड़ा नहीं है, इसलिए केवल ईमेल भेजे जाते हैं।',
'Bkm_Guide_Step_Crm' => 'CRM में बुकिंग',
'Bkm_Guide_Step_Crm_Ok' => 'वेबसाइट बुकिंग CRM में दर्ज की जाती हैं।',
'Bkm_Guide_Step_Crm_Help' => 'अपनी पाइपलाइन से ग्राहकों पर फ़ॉलो-अप करने के लिए "वेबसाइट बुकिंग को CRM में जोड़ें" चालू करें।',
'Bkm_Guide_Step_Crm_Unavailable' => 'आपकी योजना में CRM होना और उसका चालू होना आवश्यक है।',
'Bkm_Guide_Step_Portal' => 'क्लाइंट पोर्टल में बुकिंग',
'Bkm_Guide_Step_Portal_Ok' => 'पोर्टल खाते वाले ग्राहक अपनी बुकिंग वहाँ देखते हैं।',
'Bkm_Guide_Step_Portal_Help' => 'क्लाइंट पोर्टल और उसका बुकिंग सेक्शन चालू करें ताकि ग्राहक अपनी विज़िट पर नज़र रख सकें।',
'Bkm_Guide_How' => 'यह कैसे काम करता है',
'Bkm_Guide_Website' => 'वेबसाइट से एक बुकिंग',
'Bkm_Guide_Website_1_T' => 'सेवा चुनें',
'Bkm_Guide_Website_1' => 'ग्राहक आपके होम पेज के फ़ॉर्म या बुक पेज से शुरू करता है।',
'Bkm_Guide_Website_2_T' => 'समय चुनें या अनुरोध भेजें',
'Bkm_Guide_Website_2' => 'खाली समय आपके स्टाफ के कार्य समय, छुट्टी के दिनों और अन्य बुकिंग से तय होते हैं; अनुरोध में केवल एक पसंदीदा दिन और दिन का हिस्सा दिया जाता है।',
'Bkm_Guide_Website_3_T' => 'उनका विवरण',
'Bkm_Guide_Website_3' => 'नाम, फ़ोन, ईमेल और वे प्रश्न जो आपका व्यवसाय प्रकार पूछता है।',
'Bkm_Guide_Website_4_T' => 'अग्रिम राशि',
'Bkm_Guide_Website_4' => 'जब आप इसे माँगते हैं, तो वे समय बनाए रखने के लिए तुरंत इसे चुकाते हैं।',
'Bkm_Guide_Website_5_T' => 'आपकी प्रतीक्षा में',
'Bkm_Guide_Website_5' => 'यह अनुरोध में लंबित के रूप में पहुँचती है, और समय उनके लिए होल्ड पर रहता है (जब तक ऑटो-कन्फ़र्म चालू न हो)।',
'Bkm_Guide_Website_6_T' => 'उनका बुकिंग पेज',
'Bkm_Guide_Website_6' => 'वे अपने ईमेल के लिंक से इस पर नज़र रखते हैं: स्थिति, कैलेंडर में जोड़ना, रद्द करना, सुझाए गए समय का जवाब देना।',
'Bkm_Guide_Requests' => 'अनुरोधों का जवाब देना',
'Bkm_Guide_Requests_1' => 'अनुरोध में आपकी प्रतीक्षा कर रही हर बुकिंग दिखती है, सबसे पुराना होल्ड सबसे पहले, और मेनू में एक बैज के साथ।',
'Bkm_Guide_Requests_2' => 'स्टाफ खाली छोड़ने पर "पुष्टि करें" आपके लिए एक स्टाफ सदस्य चुनता है, और जाँचता है कि समय अभी भी खाली है।',
'Bkm_Guide_Requests_3' => 'जब उनका समय संभव न हो तो दूसरा समय सुझाएँ — वे इसे अपने बुकिंग पेज से स्वीकार करते हैं।',
'Bkm_Guide_Requests_4' => 'कारण के साथ अस्वीकार करें; ग्राहक उसे देखता है।',
'Bkm_Guide_Requests_5' => 'समाप्त हुआ होल्ड समय को खाली कर देता है; आपके जवाब देने तक बुकिंग बनी रहती है।',
'Bkm_Guide_Day' => 'उस दिन',
'Bkm_Guide_Day_1' => 'दिन दृश्य में हर स्टाफ सदस्य की बुकिंग साथ-साथ दिखती हैं।',
'Bkm_Guide_Day_2' => 'ग्राहक के आने पर आगमन दर्ज करें।',
'Bkm_Guide_Day_3' => '"पूर्ण करें और शुल्क लें" POS के माध्यम से बिक्री बनाता है, जिसमें अग्रिम राशि पहले से गिनी होती है।',
'Bkm_Guide_Day_4' => 'जब भुगतान किसी और तरीके से हुआ हो, तो बिना शुल्क लिए पूर्ण करें।',
'Bkm_Guide_Day_5' => 'शुरुआती समय बीत जाने के बाद नो-शो दर्ज करें।',
'Bkm_Guide_Day_6' => 'डैशबोर्ड आज का शेड्यूल, आने वाली बुकिंग और वे बुकिंग दिखाता है जिनका अभी शुल्क नहीं लिया गया।',
'Bkm_Guide_Deposits' => 'अग्रिम राशि',
'Bkm_Guide_Deposits_1' => 'राशि बुकिंग सेटिंग्स › अग्रिम राशि में तय करें; किसी सेवा की अपनी अलग राशि हो सकती है।',
'Bkm_Guide_Deposits_2' => 'ग्राहक ऑनलाइन दुकान › भुगतान गेटवे में सेट किए गए भुगतान प्रदाताओं से, आपकी आधार मुद्रा में भुगतान करते हैं।',
'Bkm_Guide_Deposits_3' => 'भुगतान के लिए समय होल्ड पर रहता है; बिना भुगतान वाली बुकिंग अपने-आप रद्द की जा सकती हैं।',
'Bkm_Guide_Deposits_4' => 'जो भुगतान पूरा हो गया लेकिन ग्राहक वेबसाइट पर वापस नहीं लौटा, वह भी अपने-आप दर्ज हो जाता है।',
'Bkm_Guide_Deposits_5' => 'जब आप बुकिंग का शुल्क लेते हैं, तो अग्रिम राशि बिक्री पर पहला भुगतान होती है।',
'Bkm_Guide_Deposits_6' => 'रिफंड आपके भुगतान प्रदाता में किए जाते हैं; फिर बुकिंग पर अग्रिम राशि को रिफंड किया गया दर्ज करें।',
'Bkm_Guide_Messages' => 'ईमेल, WhatsApp और रिमाइंडर',
'Bkm_Guide_Messages_1' => 'जब ग्राहकों की बुकिंग प्राप्त, पुष्ट, अस्वीकृत, बदली या रद्द होती है, तो उन्हें ईमेल मिलता है।',
'Bkm_Guide_Messages_2' => 'आपको हर नई वेबसाइट बुकिंग, ग्राहक द्वारा रद्दीकरण और चुकाई गई अग्रिम राशि के लिए एक ईमेल मिलता है।',
'Bkm_Guide_Messages_3' => 'हर पुष्ट विज़िट से पहले एक रिमाइंडर भेजा जाता है (बुकिंग सेटिंग्स › सूचनाएँ)।',
'Bkm_Guide_Messages_4' => 'वही संदेश वहाँ भेजने के लिए "WhatsApp से भी भेजें" चालू करें।',
'Bkm_Guide_Messages_5' => 'हर संदेश बुकिंग पर सूचीबद्ध होता है, और जो संदेश नहीं भेजा गया उसके न भेजे जाने का कारण भी।',
'Bkm_Guide_Customers' => 'ग्राहक, CRM और पोर्टल',
'Bkm_Guide_Customers_1' => 'वेबसाइट बुकिंग आपके ग्राहकों में जोड़ी जाती है; उसी ईमेल और फ़ोन से दोबारा बुक करने वाले व्यक्ति का मिलान कर लिया जाता है।',
'Bkm_Guide_Customers_2' => 'आपकी योजना में CRM होने पर, बुकिंग ग्राहक या उनकी लीड पर दर्ज की जा सकती हैं, और अनुरोध एक डील खोल सकते हैं।',
'Bkm_Guide_Customers_3' => 'क्लाइंट पोर्टल खाते वाले ग्राहक अपनी बुकिंग वहाँ देखते हैं और उन्हें रद्द कर सकते हैं या सुझाए गए समय का जवाब दे सकते हैं।',
'Bkm_Guide_Customers_4' => 'साइन-इन किए हुए स्टोर ग्राहक अपनी बुकिंग "मेरा खाता" में पाते हैं।',
'Bkm_Guide_Roles' => 'कौन क्या कर सकता है',
'Bkm_Guide_Roles_Help' => 'हर भूमिका को केवल वही अनुमतियाँ दें जिनकी उसे ज़रूरत है (सेटिंग्स › समूह अनुमतियाँ)।',
'Bkm_Guide_Job' => 'काम',
'Bkm_Guide_Give' => 'उन्हें दें',
'Bkm_Guide_Job_Front_Desk' => 'फ़्रंट डेस्क',
'Bkm_Guide_Job_Staff_Member' => 'स्टाफ सदस्य',
'Bkm_Guide_Job_Manager' => 'मैनेजर',
'Bkm_Guide_Job_Owner' => 'मालिक या अकाउंटेंट',
'Bkm_Guide_Faq' => 'प्रश्न',
'Bkm_Guide_Faq_1_Q' => 'कोई सेवा वेबसाइट पर क्यों नहीं दिखती?',
'Bkm_Guide_Faq_1_A' => 'इसके लिए बुकिंग विवरण (सेवाएँ), "वेबसाइट पर दिखाएँ" चालू, उत्पाद सक्रिय, और — समय चुनने के लिए — इसे करने वाला कोई ऑनलाइन बुक करने योग्य व्यक्ति आवश्यक है।',
'Bkm_Guide_Faq_2_Q' => 'कोई खाली समय क्यों नहीं है?',
'Bkm_Guide_Faq_2_A' => 'स्टाफ का कार्य समय, छुट्टी के दिन, कंपनी की छुट्टियाँ और स्वीकृत छुट्टी, नोटिस समय, और ग्राहक कितने दिन पहले तक बुक कर सकते हैं, यह जाँचें।',
'Bkm_Guide_Faq_3_Q' => 'क्या दो ग्राहक एक ही समय ले सकते हैं?',
'Bkm_Guide_Faq_3_A' => 'नहीं। बुक करते समय समय की फिर से जाँच होती है, और होल्ड वाली या पुष्ट बुकिंग उसे रोक देती है। क्लास अपनी सीमा तक सीटें साझा करती हैं।',
'Bkm_Guide_Faq_4_Q' => 'होल्ड समाप्त होने पर क्या होता है?',
'Bkm_Guide_Faq_4_A' => 'समय दूसरों के लिए फिर से खाली हो जाता है। आपके जवाब देने तक बुकिंग अनुरोध में बनी रहती है (या अग्रिम राशि न चुकाने पर रद्द हो जाती है)।',
'Bkm_Guide_Faq_5_Q' => 'क्या ग्राहकों को खाते की ज़रूरत है?',
'Bkm_Guide_Faq_5_A' => 'नहीं। उन्हें अपने बुकिंग पेज का एक निजी लिंक मिलता है। स्टोर और पोर्टल खातों में भी उनकी बुकिंग सूचीबद्ध होती हैं।',
'Bkm_Guide_Faq_6_Q' => 'पैसा कहाँ जाता है?',
'Bkm_Guide_Faq_6_A' => 'अग्रिम राशि आपके भुगतान प्रदाता के पास जाती है; बाकी राशि बुकिंग का शुल्क लेते समय POS पर ली जाती है। रिपोर्ट उन्हीं बिक्री से राजस्व गिनती हैं।',
'Bkm_Guide_Faq_7_Q' => 'किसी ग्राहक को ईमेल क्यों नहीं मिला?',
'Bkm_Guide_Faq_7_A' => 'बुकिंग खोलें: उसकी संदेश सूची बताती है कि हर ईमेल भेजा गया, विफल हुआ या छोड़ दिया गया, और क्यों।',
'Bkm_Staff_Removed' => 'हटाया गया',
'Bkm_Staff_Not_Bookable' => 'अब बुक करने योग्य नहीं',
'Bkm_Requests_Cut' => 'सबसे पुराने {n} दिखाए जा रहे हैं। बाकी देखने के लिए कुछ का जवाब दें, या खोजें।',

// AI Assistant (Claude)
'AI_Assistant' => 'AI सहायक',
'AI_Settings' => 'AI सहायक सेटिंग्स',
'Ai_Add_To_Existing' => 'मौजूदा में जोड़ें',
'Ai_Api_Key' => 'Claude API कुंजी',
'Ai_Applied' => 'ड्राफ्ट लागू किया गया — इसकी समीक्षा करें और उत्पाद सहेजें।',
'Ai_Apply_To_Form' => 'फ़ॉर्म पर लागू करें',
'Ai_Ask' => 'सहायक से पूछें',
'Ai_Bulk_Count' => '{n} उत्पाद चुने गए',
'Ai_Bulk_Hint' => 'AI हर उत्पाद के सहेजे गए विवरण और फ़ोटो से उसके लिए एक ड्राफ्ट लिखता है। आप ड्राफ्ट की समीक्षा करते हैं और चुनते हैं कि किन्हें सहेजना है।',
'Ai_Bulk_Note' => 'टैग और FAQ मौजूदा में जोड़े जाते हैं; विवरण मौजूदा विवरण की जगह ले लेता है।',
'Ai_Bulk_Title' => 'AI से उत्पाद सामग्री लिखें',
'Ai_Check_Facts' => 'प्रकाशित करने से पहले तथ्यों की जाँच करें — AI केवल आपके दिए विवरण का उपयोग करता है, लेकिन फिर भी गलतियाँ कर सकता है।',
'Ai_Delete_Conversation' => 'यह बातचीत हटाएँ?',
'Ai_Disclaimer' => 'AI के उत्तरों में गलतियाँ हो सकती हैं — महत्वपूर्ण आँकड़े रिपोर्ट में दोबारा जाँचें।',
