'Pf_Guide_1' => 'Printful में {store} प्रकार का एक स्टोर जोड़ें और उसमें अपने उत्पाद डिज़ाइन करें।',
'Pf_Guide_2' => 'उस स्टोर के लिए {portal} पर {scopes} स्कोप के साथ एक निजी टोकन बनाएँ। उसे कनेक्शन टैब पर पेस्ट करें और सहेजें; यदि टोकन कई स्टोर तक पहुँचता है, तो एक चुनें।',
'Pf_Guide_3' => 'पहला सफल कनेक्शन टेस्ट वेबहुक पंजीकृत करता है, ताकि Printful ऑर्डर के बदलाव और शिपमेंट की जानकारी Stocky को वापस भेज सके।',
'Pf_Guide_4' => 'उत्पाद टैब: उत्पाद आयात करें। आपकी मुद्रा से अलग मुद्रा में मूल्य वाले उत्पाद तब तक निष्क्रिय रूप में आयात होते हैं, जब तक आप सेटिंग्स टैब पर विनिमय दर सेट नहीं करते या उनकी कीमत खुद नहीं डालते।',
'Pf_Guide_5' => 'सेटिंग्स टैब: चुनें कि वेब ऑर्डर Printful को कब जाएँ। ऑर्डर के केवल Printful आइटम भेजे जाते हैं; बाकी सब आप खुद भेजते हैं।',
'Pf_Guide_6' => 'जब तक स्वचालित पुष्टि चालू न हो, ऑर्डर Printful में ड्राफ्ट के रूप में आते हैं। उन्हें प्रिंट करवाने के लिए ऑर्डर टैब पर (या Printful में) ड्राफ्ट की पुष्टि करें।',
'Pf_Guide_7' => 'चेकआउट पर Printful की अपनी शिपिंग कीमतों के लिए, स्टोर > शिपिंग विधियाँ में एक शिपिंग विधि जोड़ें और उसका मूल्य निर्धारण Printful दरें पर सेट करें।',
'Pf_Guide_Duplicate' => 'इस Printful स्टोर को वही उत्पाद बेचने वाली किसी Shopify या WooCommerce दुकान से भी न जोड़ें, वरना Printful को वे ऑर्डर दो बार मिलेंगे।',
