'Ai_Gemini_Model_Help' => 'कोई सुझाया गया मॉडल चुनें या कोई भी Gemini मॉडल id टाइप करें जिसे आपकी कुंजी उपयोग कर सकती है।',
'Mkg_Guide' => 'विपणन गाइड',
