'Mkg_Guide_Step_Health_Skipped' => 'पिछले 30 दिनों में {n} संदेश छोड़े गए (ईमेल या फ़ोन नहीं, चैनल बंद, या कोई सर्वर नहीं)। कारण देखने के लिए कोई अभियान खोलें।',
'Mkg_Guide_Step_Health_Ok' => 'पिछले 30 दिनों में कोई विफल या अटका हुआ संदेश नहीं।',
'Mkg_Guide_Flow' => 'अभियान भेजना',
'Mkg_Guide_Flow_1_T' => 'चैनल सेट करें',
'Mkg_Guide_Flow_1' => 'विपणन सेटिंग में ईमेल, SMS या WhatsApp चालू करें और उसका सर्वर या गेटवे जोड़ें।',
'Mkg_Guide_Flow_2_T' => 'दर्शक चुनें',
