'Mkg_Guide_Flow_3_T' => 'संदेश लिखें',
'Mkg_Guide_Flow_3' => 'इसे टाइप करें या किसी टेम्पलेट से शुरू करें, और वैयक्तिकरण वेरिएबल जोड़ें (नीचे देखें)।',
'Mkg_Guide_Flow_4_T' => 'अभी भेजें या शेड्यूल करें',
'Mkg_Guide_Flow_4' => 'अभी भेजें तुरंत शुरू हो जाता है; शेड्यूल आपकी चुनी हुई तारीख और समय पर भेजता है।',
'Mkg_Guide_Flow_5_T' => 'प्राप्तकर्ता सूची बनती है',
'Mkg_Guide_Flow_5' => 'जिस क्षण आप भेजते हैं, हर मेल खाने वाला ग्राहक लंबित के रूप में जोड़ दिया जाता है, ताकि आप तुरंत देख सकें कि यह किसे मिलेगा।',
'Mkg_Guide_Flow_6_T' => 'डिलीवरी बैकग्राउंड में चलती है',
'Mkg_Guide_Flow_6' => 'संदेश बैचों में भेजे जाते हैं (विपणन सेटिंग में बैच आकार) और हर बैच के बाद गिनती अपडेट होती है।',
'Mkg_Guide_Flow_7_T' => 'परिणाम देखें',
'Mkg_Guide_Flow_7' => 'हर प्राप्तकर्ता की स्थिति और कोई त्रुटि देखने के लिए अभियान खोलें; रिपोर्ट सभी चैनलों का सारांश देती है।',
'Mkg_Guide_Audience' => 'यह किसे मिलता है',
'Mkg_Guide_Audience_1' => 'सभी ग्राहक हर उस ग्राहक को भेजता है जिसे हटाया नहीं गया है।',
'Mkg_Guide_Audience_2' => 'खंड ग्राहकों को शहर, पिछली खरीद की तारीख, खरीद की संख्या और कुल खर्च के आधार पर फ़िल्टर करता है। पूर्वावलोकन सहेजने से पहले दिखाता है कि कितने ग्राहक मेल खाते हैं।',
'Mkg_Guide_Audience_3' => 'भेजें पर क्लिक करते ही सूची तय हो जाती है। बाद में जोड़े गए ग्राहक शामिल नहीं होते।',
'Mkg_Guide_Audience_4' => 'बिना ईमेल पते (ईमेल) या फ़ोन नंबर (SMS, WhatsApp) वाले ग्राहक सूची में छोड़ा गया के रूप में रहते हैं।',
'Mkg_Guide_Audience_5' => 'किसी विफल अभियान को दोबारा भेजने पर खंड से सूची फिर से बनती है और सभी के लिए पुनः प्रयास होता है।',
'Mkg_Guide_Audience_Leads' => 'CRM चालू होने पर, खंड ग्राहकों के बजाय CRM लीड को लक्षित कर सकता है (टैग, स्रोत, स्थिति, स्कोर और अधिक)। अनसब्सक्राइब कर चुकी लीड छोड़ दी जाती हैं, और लीड को भेजे गए ईमेल में हमेशा अनसब्सक्राइब लिंक होता है।',
'Mkg_Guide_Channels' => 'चैनल',
'Mkg_Guide_Ch_email_1' => 'आपके अपने मेल सर्वर (सेटिंग्स > मेल सेटिंग्स) के माध्यम से भेजा जाता है। प्लेटफ़ॉर्म का मेलर कभी उपयोग नहीं होता।',
'Mkg_Guide_Ch_email_2' => 'प्रेषक का नाम और पता विपणन सेटिंग से आते हैं, अन्यथा मेल सर्वर से।',
'Mkg_Guide_Ch_email_3' => 'एक विषय और वैकल्पिक अटैचमेंट जोड़ें। संदेश में HTML हो सकता है।',
'Mkg_Guide_Ch_email_4' => 'बिना ईमेल पते वाले ग्राहक छोड़ दिए जाते हैं।',
'Mkg_Guide_Ch_sms_1' => 'किसी भी HTTP SMS गेटवे के साथ काम करता है: उसका API URL, कुंजी, sender ID, मेथड और उसके अपेक्षित फ़ील्ड नाम दर्ज करें।',
'Mkg_Guide_Ch_sms_2' => 'फ़ोन नंबर वाले हर ग्राहक को एक SMS जाता है; बाकी छोड़ दिए जाते हैं।',
'Mkg_Guide_Ch_sms_3' => 'आपका गेटवे हर संदेश का शुल्क लेता है, इसलिए पहले किसी छोटे खंड पर टेस्ट करें।',
'Mkg_Guide_Ch_whatsapp_1' => 'कोई WhatsApp HTTP गेटवे, या Meta WhatsApp Cloud API (graph.facebook.com) जोड़ें।',
'Mkg_Guide_Ch_whatsapp_2' => 'किसी ग्राहक के आपको आखिरी बार लिखने के 24 घंटे से अधिक बाद, WhatsApp केवल Meta-स्वीकृत टेम्पलेट ही डिलीवर करता है।',
'Mkg_Guide_Ch_whatsapp_3' => 'Cloud API के साथ, अभियान में स्वीकृत टेम्पलेट चुनें और उसके पैरामीटर भरें।',
'Mkg_Guide_Ch_whatsapp_4' => 'बिना फ़ोन नंबर वाले ग्राहक छोड़ दिए जाते हैं।',
'Mkg_Guide_Variables' => 'वैयक्तिकरण वेरिएबल',
'Mkg_Guide_Variables_Help' => 'इन्हें विषय या संदेश में टाइप करें। हर प्राप्तकर्ता के लिए हर वेरिएबल बदल दिया जाता है, और मान अज्ञात होने पर खाली छोड़ दिया जाता है।',
'Mkg_Guide_Var_Name' => 'पूरा नाम',
'Mkg_Guide_Var_First_Name' => 'पहला नाम',
'Mkg_Guide_Var_Company' => 'कंपनी का नाम (केवल CRM लीड)',
'Mkg_Guide_Var_Phone' => 'फ़ोन नंबर',
'Mkg_Guide_Var_Email' => 'ईमेल पता',
'Mkg_Guide_Var_Last_Purchase' => 'अंतिम पूर्ण बिक्री की तारीख',
'Mkg_Guide_Var_Total_Spent' => 'सभी पूर्ण बिक्री का कुल योग',
'Mkg_Guide_Var_Unsubscribe' => 'अनसब्सक्राइब लिंक (केवल CRM लीड; न होने पर लीड ईमेल में अपने-आप जोड़ा जाता है)',
'Mkg_Guide_Schedule' => 'शेड्यूलिंग',
'Mkg_Guide_Schedule_1' => 'विपणन सेटिंग में शेड्यूलिंग सक्षम करें चालू करें, फिर अभियान में शेड्यूल और एक तारीख व समय चुनें।',
'Mkg_Guide_Schedule_2' => 'देय अभियान हर मिनट जाँचे जाते हैं और अपने-आप भेजे जाते हैं।',
'Mkg_Guide_Schedule_3' => 'जो अभियान एक दिन से अधिक देर हो चुका है, उसे देर से भेजने के बजाय रद्द कर दिया जाता है। उसे संपादित करें और नया समय चुनें।',
'Mkg_Guide_Schedule_4' => 'शेड्यूल किया गया अभियान अब भी संपादित किया जा सकता है, या अभी भेजें से तुरंत भेजा जा सकता है।',
'Mkg_Guide_Statuses' => 'स्थितियों का अर्थ',
'Mkg_Guide_Campaign_Statuses' => 'अभियान',
'Mkg_Guide_Recipient_Statuses' => 'हर प्राप्तकर्ता',
'Mkg_Guide_Status_draft' => 'सहेजा गया, अभी भेजा नहीं गया।',
'Mkg_Guide_Status_scheduled' => 'अपने भेजने के समय की प्रतीक्षा में।',
'Mkg_Guide_Status_sending' => 'संदेश भेजे जा रहे हैं। 30 मिनट तक कोई प्रगति न होने पर अभी भेजें फिर से दिखता है, ताकि आप इसे दोबारा शुरू कर सकें।',
'Mkg_Guide_Status_sent' => 'पूरा हुआ: हर प्राप्तकर्ता संसाधित हो गया (कुछ छोड़े गए या विफल हो सकते हैं)।',
'Mkg_Guide_Status_failed' => 'हर प्रयास किया गया संदेश विफल रहा। कारण ठीक करें, फिर दोबारा अभी भेजें।',
'Mkg_Guide_Status_cancelled' => 'हाथ से रोका गया, या शेड्यूल होने पर एक दिन से अधिक देर हो गई।',
'Mkg_Guide_Rstatus_pending' => 'भेजे जाने की प्रतीक्षा में।',
'Mkg_Guide_Rstatus_sent' => 'आपके मेल सर्वर या गेटवे ने स्वीकार किया।',
'Mkg_Guide_Rstatus_failed' => 'अस्वीकार किया गया। त्रुटि स्थिति के नीचे दिखाई जाती है।',
'Mkg_Guide_Rstatus_skipped' => 'प्रयास नहीं किया गया: चैनल बंद, कोई सर्वर नहीं, ईमेल या फ़ोन नहीं, या अनसब्सक्राइब किया हुआ।',
'Mkg_Guide_Roles' => 'किसे कौन-सी अनुमति चाहिए',
'Mkg_Guide_Roles_Help' => 'सेटिंग्स > अनुमतियाँ में हर भूमिका को केवल वही दें जिसकी उसे ज़रूरत है। इनमें से कोई भी एक अनुमति यह गाइड खोल देती है।',
'Mkg_Guide_Permission' => 'अनुमति',
'Mkg_Guide_Allows' => 'इससे वे कर सकते हैं',
'Mkg_Guide_Perm_marketing_dashboard' => 'विपणन डैशबोर्ड देखें: कुल योग और हाल के अभियान।',
'Mkg_Guide_Perm_marketing_campaigns' => 'अभियान बनाएँ, संपादित करें, भेजें और हटाएँ, और उनके प्राप्तकर्ता देखें।',
'Mkg_Guide_Perm_marketing_segments' => 'ग्राहक खंड बनाएँ और संपादित करें।',
'Mkg_Guide_Perm_marketing_templates' => 'SMS, WhatsApp और ईमेल टेम्पलेट प्रबंधित करें।',
'Mkg_Guide_Perm_marketing_reports' => 'विपणन रिपोर्ट खोलें।',
'Mkg_Guide_Perm_marketing_settings' => 'चैनल (SMS, WhatsApp, ईमेल प्रेषक), शेड्यूलिंग और बैच आकार सेट करें।',
'Mkg_Guide_Faq' => 'सामान्य प्रश्न',
'Mkg_Guide_Faq_1_Q' => 'मेरा अभियान "भेजा जा रहा है" पर ही रहता है और कुछ नहीं जाता।',
'Mkg_Guide_Faq_1_A' => 'बैकग्राउंड प्रेषक ने इसे अभी तक नहीं उठाया है। 30 मिनट तक कोई प्रगति न होने पर अभी भेजें बटन फिर से दिखता है: फिर से शुरू करने के लिए उस पर क्लिक करें। यदि ऐसा बार-बार हो, तो अपने प्लेटफ़ॉर्म व्यवस्थापक से जाँच करवाएँ कि बैकग्राउंड जॉब (queue worker) चल रहे हैं।',
'Mkg_Guide_Faq_2_Q' => 'प्राप्तकर्ताओं पर "Skipped: Email channel disabled" (छोड़ा गया: ईमेल चैनल अक्षम) दिखता है।',
'Mkg_Guide_Faq_2_A' => 'विपणन सेटिंग में ईमेल सक्षम करें चालू करें, फिर अभियान दोबारा भेजें।',
'Mkg_Guide_Faq_3_Q' => 'प्राप्तकर्ताओं पर "No mail server configured" (कोई मेल सर्वर कॉन्फ़िगर नहीं) दिखता है।',
'Mkg_Guide_Faq_3_A' => 'ईमेल अभियान केवल आपके अपने मेल सर्वर से जाते हैं। इसे सेटिंग्स > मेल सेटिंग्स में जोड़ें।',
'Mkg_Guide_Faq_4_Q' => 'मेरे खंड में जितने लोग हैं, उससे कम लोगों को संदेश मिला।',
'Mkg_Guide_Faq_4_A' => 'बिना ईमेल पते (ईमेल) या फ़ोन नंबर (SMS, WhatsApp) वाले ग्राहक छोड़ दिए जाते हैं। किसे और क्यों छोड़ा गया, यह देखने के लिए अभियान खोलें।',
'Mkg_Guide_Faq_5_Q' => 'क्या भेजा गया का अर्थ है कि ग्राहक को संदेश मिल गया?',
'Mkg_Guide_Faq_5_A' => 'भेजा गया का अर्थ है कि आपके मेल सर्वर या गेटवे ने संदेश स्वीकार कर लिया। इनबॉक्स में डिलीवरी, खोला जाना और स्पैम फ़िल्टरिंग ट्रैक नहीं की जाती।',
'Mkg_Guide_Faq_6_Q' => 'क्या मैं भेजने के बाद अभियान संपादित कर सकता हूँ?',
'Mkg_Guide_Faq_6_A' => 'नहीं। भेजे जा रहे और भेजे जा चुके अभियान लॉक रहते हैं; इसके बजाय नया अभियान बनाएँ।',
'Mkg_Guide_Faq_7_Q' => 'मेरे WhatsApp संदेश नहीं पहुँच रहे हैं।',
'Mkg_Guide_Faq_7_A' => 'किसी ग्राहक के आपको आखिरी बार लिखने के 24 घंटे से अधिक बाद, WhatsApp केवल Meta-स्वीकृत टेम्पलेट ही डिलीवर करता है। WhatsApp Cloud API उपयोग करें और अभियान में कोई स्वीकृत टेम्पलेट चुनें।',
'Mkg_Guide_Faq_8_Q' => 'अगर मैं कोई अभियान दोबारा भेजूँ, तो क्या ग्राहकों को यह दो बार मिलेगा?',
'Mkg_Guide_Faq_8_A' => 'अटके हुए अभियान को फिर से शुरू करने पर केवल अभी भी लंबित प्राप्तकर्ताओं को भेजा जाता है, इसलिए जिन तक संदेश पहुँच चुका है उन्हें दोबारा नहीं भेजा जाता। किसी विफल अभियान को दोबारा भेजने पर नई सूची के साथ शुरुआत से भेजा जाता है।',

