'Pd_Transactions_Help' => 'किसी डिवाइस को भेजा गया हर भुगतान, रिफंड और वॉइड। "बिना बिक्री के शुल्क लिया गया" का अर्थ है कि कार्ड से शुल्क लिया गया लेकिन कोई बिक्री सहेजी नहीं गई — इसे वॉइड या रिफंड करें।',
'Pd_Not_Linked' => 'बिना बिक्री के शुल्क लिया गया',
'Pd_Reversed' => 'रिफंड किया गया',
