'Pd_Refund' => 'रिफंड करें',
'Pd_Refund_Help' => 'राशि डिवाइस के माध्यम से ग्राहक के कार्ड पर वापस जाती है। इससे बिक्री वापसी नहीं बनती — यदि सामान वापस आया है तो वापसी बिक्री वापसी में दर्ज करें।',
'Pd_Refund_Max' => 'अधिकतम {max}',
'Pd_Refund_Done' => 'डिवाइस ने रिफंड स्वीकृत किया।',
'Pd_Void_Confirm' => 'यह कार्ड भुगतान वॉइड करें?',
'Pd_Void_Confirm_Help' => 'पूरी {amount} राशि डिवाइस पर रद्द हो जाती है। आमतौर पर यह केवल उसी दिन संभव है, डिवाइस के अपना बैच बंद करने से पहले।',
'Pd_Void_Done' => 'कार्ड भुगतान वॉइड किया गया।',
'Pd_Void_Failed' => 'डिवाइस ने भुगतान वॉइड नहीं किया।',
'Pd_Kpi_Transactions' => 'लेनदेन',
'Pd_Kpi_Approved' => 'स्वीकृत कार्ड भुगतान',
