'Pd_Kpi_Unsuccessful' => 'अस्वीकृत / विफल',
'Pd_Charge_On_Device' => 'डिवाइस पर {amount} का शुल्क लें',
'Pd_Ready_To_Charge' => 'राशि सेट करें, फिर डिवाइस पर उसका शुल्क लें।',
'Pd_Waiting_For_Card' => '{device} पर ग्राहक के कार्ड की प्रतीक्षा…',
'Pd_Voiding' => 'डिवाइस पर वॉइड किया जा रहा है…',
'Pd_Charge_Approved' => 'कार्ड भुगतान स्वीकृत।',
'Pd_Charge_Exceeds_Due' => 'कार्ड भुगतान अन्य भुगतान पंक्तियों के बाद बची देय राशि से अधिक नहीं हो सकता।',
'Pd_Charge_First' => 'भुगतान पूरा करने से पहले डिवाइस पर कार्ड से शुल्क लें।',
'Pd_Amount_Changed' => 'राशि अब डिवाइस पर लिए गए शुल्क से मेल नहीं खाती। शुल्क वॉइड करें और फिर से शुल्क लें।',
'Pd_Wait_For_Device' => 'डिवाइस का काम पूरा होने तक प्रतीक्षा करें।',
'Pd_Line_Locked' => 'इस पंक्ति का शुल्क डिवाइस पर लिया जा चुका है। इसे बदलने के लिए पहले शुल्क वॉइड करें।',
'Pd_Needs_Online' => 'कार्ड टर्मिनल भुगतान के लिए इंटरनेट कनेक्शन आवश्यक है।',
'Pd_Device_Error' => 'डिवाइस तक नहीं पहुँचा जा सका।',
'Pd_Void_Charge' => 'शुल्क वॉइड करें',
'Pd_Void_Charge_Confirm' => 'डिवाइस पर {amount} का कार्ड भुगतान वॉइड करें?',
'Pd_Void_Before_Close' => 'डिवाइस पर पहले ही एक कार्ड भुगतान लिया जा चुका है। उसे वॉइड करके बंद करें?',
'Pd_Installments' => 'किस्तें',
'Pd_Single_Payment' => 'एकमुश्त भुगतान',
'Pd_Guide_How_Title' => 'यह कैसे काम करता है',
'Pd_Guide_How_Intro' => 'POS डिवाइस कैश काउंटर के पास रखा कार्ड टर्मिनल या फ़िस्कल कैश रजिस्टर है। Stocky उसे राशि भेजता है, ग्राहक के भुगतान की प्रतीक्षा करता है, और डिवाइस के स्वीकृत करने के बाद ही भुगतान दर्ज करता है।',
'Pd_Guide_Step_1' => 'डिवाइस यहाँ जोड़ें: मॉडल, गोदाम, और वह भुगतान विधि जिसके रूप में उसके कार्ड भुगतान दर्ज होते हैं (उदाहरण के लिए "क्रेडिट कार्ड")।',
'Pd_Guide_Step_2' => 'चुनें कि Stocky उस तक कैसे पहुँचे: कैशियर कंप्यूटर पर लोकल ब्रिज, या आपके प्रदाता का क्लाउड API। अपने बैंक या प्रदाता से मिली ID और कुंजियाँ दर्ज करें।',
'Pd_Guide_Step_3' => 'कनेक्शन टेस्ट करें दबाएँ। ब्रिज डिवाइस का टेस्ट उसी कैशियर कंप्यूटर से करना होगा जिस पर ब्रिज चलता है।',
'Pd_Guide_Step_4' => 'POS पर वह भुगतान विधि चुनें, "डिवाइस पर शुल्क लें" दबाएँ और ग्राहक को भुगतान करने दें। डिवाइस के स्वीकृत करते ही बिक्री पूरी की जा सकती है।',
'Pd_Guide_Step_5' => 'बिना बिक्री के लिए गए कार्ड भुगतान (उदाहरण के लिए, बीच में छोड़ा गया चेकआउट) के लिए लेनदेन देखें और उन्हें वॉइड या रिफंड करें।',
'Pd_Guide_Bridge_Text' => 'उन डिवाइस के लिए जो कैशियर PC पर किसी विक्रेता SDK से चलते हैं (USB, सीरियल या LAN पेयरिंग)। ब्राउज़र SDK को सीधे उपयोग नहीं कर सकता, इसलिए एक छोटा ब्रिज प्रोग्राम उसे संभालता है और इस कंप्यूटर पर सुनता है।',
'Pd_Guide_Bridge_Point_1' => 'POS हर अनुरोध कैशियर के ब्राउज़र से ब्रिज URL पर भेजता है; Stocky के सर्वर को कभी आपकी दुकान के नेटवर्क तक पहुँचने की ज़रूरत नहीं होती।',
'Pd_Guide_Bridge_Point_2' => 'अनुरोधों और उत्तरों पर साझा सीक्रेट से हस्ताक्षर होते हैं, इसलिए ब्राउज़र से कोई स्वीकृति नकली नहीं बनाई जा सकती।',
'Pd_Guide_Bridge_Point_3' => 'इस डिवाइस पर कार्ड भुगतान लेने वाले हर कंप्यूटर पर ब्रिज इंस्टॉल करें और चालू करें।',
'Pd_Guide_Cloud_Text' => 'उन प्रदाताओं के लिए जो इंटरनेट के माध्यम से डिवाइस तक पहुँचते हैं। Stocky का सर्वर API को कॉल करता है, इसलिए कैशियर कंप्यूटर पर कुछ भी इंस्टॉल नहीं करना पड़ता।',
'Pd_Guide_Cloud_Point_1' => 'API URL किसी सार्वजनिक पते पर https:// होना चाहिए।',
'Pd_Guide_Cloud_Point_2' => 'ग्राहक के भुगतान करते समय Stocky हर 2 सेकंड में स्थिति पूछता है, इसलिए status endpoint को भुगतान उसके संदर्भ से पहचानना चाहिए; यदि API कार्ड का काम पूरा होने से पहले उत्तर देता है ("pending"), तो पोलिंग परिणाम तय करती है।',
'Pd_Guide_Ide280_Title' => 'Ingenico IDE280',
'Pd_Guide_Ide280_Text' => 'IDE280 कार्ड रीडर वाला नई पीढ़ी का फ़िस्कल कैश रजिस्टर (YN ÖKC) है। इसे आमतौर पर Ingenico के ECR / GMP3 SDK, या आपके बैंक की इंटीग्रेशन सेवा के माध्यम से जोड़ा जाता है।',
'Pd_Guide_Ide280_Point_1' => 'Ingenico / बैंक के दस्तावेज़ में बताए अनुसार डिवाइस को कैशियर कंप्यूटर से पेयर करें, फिर ब्रिज (या API सेटिंग्स) को उस पर सेट करें।',
'Pd_Guide_Ide280_Point_2' => 'राशियाँ दशमलव में और kuruş (amount_minor) में, दोनों तरह से भेजी जाती हैं, मुद्रा TRY / 949 के साथ।',
'Pd_Guide_Ide280_Point_3' => '"पूरी फ़िस्कल रसीद" के साथ, हर आइटम में उसकी VAT दर का डिवाइस विभाग होता है — VAT विभागों को डिवाइस की प्रोग्रामिंग के अनुसार मिलाएँ।',
'Pd_Guide_Protocol_Title' => 'ब्रिज / API अनुबंध',
'Pd_Guide_Protocol_Intro' => 'Stocky ब्रिज या API से JSON में बात करता है। नीचे दिए पाथ डिफ़ॉल्ट हैं और हर डिवाइस के लिए उन्नत में बदले जा सकते हैं।',
'Pd_Guide_Operation' => 'ऑपरेशन',
'Pd_Guide_Default_Endpoint' => 'डिफ़ॉल्ट endpoint',
'Pd_Guide_When' => 'कब',
'Pd_Guide_When_Ping' => 'कनेक्शन टेस्ट करें बटन।',
'Pd_Guide_When_Sale' => 'कैशियर "डिवाइस पर शुल्क लें" दबाता है। कार्ड का काम पूरा होने पर उत्तर दे सकता है, या तुरंत स्थिति "pending" के साथ।',
'Pd_Guide_When_Status' => 'भुगतान लंबित रहने तक हर 2 सेकंड में।',
'Pd_Guide_When_Cancel' => 'कार्ड की प्रतीक्षा के दौरान कैशियर रद्द करता है।',
'Pd_Guide_When_Void' => 'किसी भुगतान को वॉइड करना (उसी दिन, पूरी राशि)।',
'Pd_Guide_When_Refund' => 'किसी भुगतान का कुछ हिस्सा या पूरा रिफंड करना।',
'Pd_Guide_Request_Title' => 'अनुरोध',
'Pd_Guide_Request_Text' => 'बिक्री के लिए Stocky जो body भेजता है। रिफंड और वॉइड में मूल भुगतान "original" के रूप में होता है।',
'Pd_Guide_Response_Title' => 'उत्तर',
'Pd_Guide_Response_Text' => 'फ़ील्ड नाम लचीले ढंग से पढ़े जाते हैं ("data" के अंदर भी); "status" या response_code "00" परिणाम तय करता है। कार्ड नंबर मास्क करके संग्रहीत होते हैं।',
'Pd_Guide_Signing_Title' => 'हस्ताक्षर (ब्रिज)',
'Pd_Guide_Signing_Text' => 'ब्रिज को Stocky का हस्ताक्षर जाँचना चाहिए, और उसे अपने उत्तर की हूबहू body पर हस्ताक्षर करना होगा तथा "reference" और "operation" दोनों लौटाने होंगे — बिना हस्ताक्षर वाले उत्तर, या किसी दूसरे ऑपरेशन के उत्तर अस्वीकार कर दिए जाते हैं।',
'Pd_Guide_Browser_Title' => 'ब्राउज़र एक्सेस (ब्रिज)',
'Pd_Guide_Browser_Text' => 'POS पेज ब्राउज़र से ब्रिज को कॉल करता है, इसलिए ब्रिज को ये CORS हेडर लौटाने होंगे (OPTIONS preflight सहित)।',
'Pd_Guide_Safety_Title' => 'जानने योग्य बातें',
'Pd_Guide_Safety_1' => 'बिक्री केवल उसी राशि के स्वीकृत डिवाइस भुगतान के साथ सहेजी जाती है; एक डिवाइस भुगतान कभी दो बिक्री का भुगतान नहीं कर सकता।',
'Pd_Guide_Safety_2' => 'कार्ड से शुल्क लेने के बाद भुगतान विंडो बंद करने पर पहले वह शुल्क वॉइड होता है।',
'Pd_Guide_Safety_3' => 'यदि डिवाइस समय पर उत्तर नहीं देता, तो भुगतान "कोई उत्तर नहीं" के रूप में दिखता है: डिवाइस जाँचें, और यदि कार्ड से शुल्क लिया गया था तो लेनदेन से उसे वॉइड करें।',
'Pd_Guide_Safety_4' => 'यहाँ के रिफंड और वॉइड केवल कार्ड पर पैसा लौटाते हैं; वे बिक्री नहीं बदलते। लौटाया गया सामान बिक्री वापसी में दर्ज करें।',
'Perm_Pos_Terminals_Manage' => 'POS डिवाइस: प्रबंधन, रिफंड और वॉइड',
'Perm_Pos_Terminals_Transactions' => 'POS डिवाइस: लेनदेन देखें',
'Pd_Check_Again' => 'फिर से जाँचें',
'Pd_Lost_Track' => 'डिवाइस के उत्तर देने से पहले संपर्क टूट गया। डिवाइस जाँचें, फिर "फिर से जाँचें" दबाएँ — जब तक स्थिति पता न हो, दोबारा शुल्क न लें।',
'Pd_Close_Anyway' => 'कार्ड भुगतान वॉइड नहीं हो सका। फिर भी बंद करें? यह POS डिवाइस › लेनदेन में "बिना बिक्री के शुल्क लिया गया" के रूप में रहेगा, ताकि वहाँ इसे वॉइड या रिफंड किया जा सके।',
'Pd_Devices_Loading' => 'कार्ड डिवाइस लोड हो रहे हैं — थोड़ी देर में फिर से प्रयास करें।',
