'Cd_Guide_2' => 'अपने डोमेन प्रदाता (GoDaddy, Namecheap, Cloudflare...) में साइन इन करें और दिखाया गया DNS रिकॉर्ड बनाएँ।',
'Cd_Guide_3' => 'वापस आएँ और DNS जाँचें पर क्लिक करें। सत्यापित होने के बाद, आपका वर्कस्पेस, ऑनलाइन दुकान और ग्राहक पोर्टल उस डोमेन पर खुलते हैं।',
'Cd_Guide_4' => 'आपका प्लेटफ़ॉर्म सबडोमेन कस्टम डोमेन के साथ-साथ काम करता रहता है।',
'Cd_Cloudflare_Note' => 'Cloudflare उपयोगकर्ता: सत्यापन पूरा होने तक रिकॉर्ड को DNS only (ग्रे क्लाउड) पर सेट करें।',
'Perm_custom_domains' => 'कस्टम डोमेन (सेटिंग्स > कस्टम डोमेन)',
'List_Too_Big_All' => 'इस सूची में {count} से अधिक पंक्तियाँ हैं, इसलिए सभी विकल्प बंद है। हर पेज पर 100 पंक्तियाँ दिखाई जा रही हैं। इसे सीमित करने के लिए खोज या फ़िल्टर उपयोग करें।',
'List_Too_Big_Export' => 'इस सूची में {count} से अधिक पंक्तियाँ हैं, जो एक बार में निर्यात करने के लिए बहुत अधिक हैं। इसे सीमित करने के लिए खोज या फ़िल्टर उपयोग करें।',
'PartiallyPaid' => 'आंशिक भुगतान',
'Ord_Guide_PayAuto_Tip' => 'बिक्री पर भुगतान दर्ज होने पर यह अपने-आप अपडेट होता है। भुगतान दर्ज करने का तरीका देखने के लिए क्लिक करें।',
'Ord_Guide_PayAuto_Intro' => 'यह कॉलम दिखाता है कि ऑर्डर का कितना भुगतान हो चुका है। यह ग्राहक के चेकआउट विकल्प से शुरू होता है, फिर ऑर्डर की पुष्टि से बनने वाली बिक्री पर भुगतान दर्ज होने के साथ अपने-आप अपडेट होता है। इसे इस पेज से संपादित नहीं किया जा सकता।',
'Ord_Guide_PayAuto_Paid' => 'पूरी राशि प्राप्त हो चुकी है। यदि ग्राहक ने किसी पेमेंट गेटवे से ऑनलाइन भुगतान किया है, तो ऑर्डर की पुष्टि करने पर बिक्री भुगतान किया गया के रूप में बनती है और भुगतान आपके लिए दर्ज हो जाता है। अन्यथा, बिक्री पर भुगतान कुल राशि के बराबर होते ही स्थिति भुगतान किया गया में बदल जाती है।',
'Ord_Guide_PayAuto_Partial' => 'बिक्री पर एक भुगतान दर्ज हुआ है, लेकिन कुल राशि का कुछ हिस्सा अभी देय है।',
'Ord_Guide_PayAuto_Pending' => 'अभी तक कोई भुगतान प्राप्त नहीं हुआ है: कैश ऑन डिलीवरी (COD), बैंक ट्रांसफ़र या कोई अन्य बाद में भुगतान वाली विधि। ऑर्डर की पुष्टि करने पर बिक्री भुगतान नहीं हुआ के रूप में बनती है, इसलिए पैसा वसूलने के बाद उसे आप खुद दर्ज करते हैं। नीचे दिए चरण देखें।',
'Ord_Guide_PayAuto_Note' => 'यहाँ दिखाई गई भुगतान स्थिति बिक्री का अनुसरण करती है: भुगतान सहेजने पर यह अपने-आप आंशिक भुगतान या भुगतान किया गया में बदल जाती है, और भुगतान हटाने पर वापस बदल जाती है। बिक्री ही लेखांकन रिकॉर्ड है, और यही आपकी भुगतान और लाभ रिपोर्ट को डेटा देती है। आपने जो दर्ज किया है उसे देखने या संपादित करने के लिए बिक्री पर भुगतान दिखाएँ उपयोग करें।',
'Ord_LinkedSale' => 'जुड़ी हुई बिक्री',
'Ord_LinkedSale_Missing' => 'इस ऑर्डर से कोई बिक्री जुड़ी नहीं है। हो सकता है बिक्री हटा दी गई हो, या ऑर्डर की पुष्टि ऑर्डर को बिक्री से जोड़ने की सुविधा आने से पहले हुई हो।',
