'Oc_Pull_Desc' => 'OpenCart उत्पाद आयात करता है, मौजूदा उत्पादों को मॉडल या SKU से मिलाता है और बाकी को बनाता है। लिंक किए गए उत्पाद नाम और मूल्य OpenCart से लेते हैं।',
'Oc_Pull_Stock' => 'नए उत्पादों के लिए OpenCart मात्राओं को प्रारंभिक स्टॉक के रूप में इस्तेमाल करें',
'Oc_Reset_Confirm' => 'उत्पाद लिंक रीसेट करें? ऑर्डर इतिहास के लिंक बने रहेंगे।',
