'Oc_Orders_Desc' => 'स्टोर ऑर्डर को बिक्री के रूप में आयात करता है ({ref} जैसे संदर्भ के साथ)। पहले से आयात किए गए ऑर्डर की केवल स्थिति और भुगतान अपडेट होते हैं, इसलिए दोबारा प्राप्त करना सुरक्षित है।',
'Oc_Orders_Since' => 'इस तारीख से ऑर्डर',
'Oc_Guide_1' => 'कनेक्शन टैब पर {company} Connector डाउनलोड करें।',
'Oc_Guide_2' => 'अपने OpenCart एडमिन में {installer} के अंतर्गत फ़ाइल अपलोड करें और Install पर क्लिक करें, फिर {modules} के अंतर्गत मॉड्यूल इंस्टॉल करें।',
'Oc_Guide_3' => '{name} मॉड्यूल खोलें, फिर स्टोर URL और सीक्रेट कॉपी करें।',
'Oc_Guide_4' => 'उन्हें कनेक्शन टैब पर पेस्ट करें, सहेजें, और {test} चलाएँ। इससे स्टोर को यह भी पता चल जाता है कि नए ऑर्डर कहाँ भेजने हैं।',
'Oc_Guide_5' => 'उत्पाद सेट करें: अगर स्टोर में पहले से कैटलॉग है तो प्राप्त करें, अगर {company} में है तो भेजें। स्वचालित स्टॉक पर निर्भर होने से पहले यह करें, क्योंकि स्टॉक के आँकड़ों का स्रोत {company} बन जाता है।',
'Oc_Guide_6' => 'अगर आपको इतिहास चाहिए तो हाल के ऑर्डर एक बार प्राप्त करें। उसके बाद ऑर्डर अपने-आप आते रहेंगे।',
'Oc_Identity_Title' => 'उत्पाद मॉडल और SKU से मिलाए जाते हैं',
'Oc_Identity_Desc' => 'यहाँ का उत्पाद कोड OpenCart के मॉडल और SKU से मिलाया जाता है। दोनों तरफ़ इन्हें एक जैसा रखें। यहाँ का स्टॉक मुख्य आँकड़ा है: हर ऑर्डर के बाद स्टोर इसी से अपडेट होता है।',
'Oc_Options_Title' => 'वेरिएंट के बिना विकल्प',
'Oc_Options_Desc' => 'OpenCart वेरिएंट का अपना स्टॉक होता है और वे यहाँ के वेरिएंट से मैप होते हैं। जिस उत्पाद में केवल विकल्प हों और कोई वेरिएंट न बनाया गया हो, वह एक उत्पाद के रूप में आयात होता है और उसका स्टॉक विकल्प के अनुसार नहीं बँटता।',
'Oc_Cancel_Title' => 'रद्द किए गए ऑर्डर',
'Oc_Cancel_Desc' => 'OpenCart में ऑर्डर रद्द करने पर यहाँ उसकी बिक्री उलट दी जाती है। अगर बिक्री पहले ही डिलीवर हो चुकी हो या उसकी वापसी हुई हो, तो कुछ भी पूर्ववत नहीं होता: आपकी समीक्षा के लिए बिक्री को उसके नोट्स और लॉग में चिह्नित कर दिया जाता है।',
'Oc_Download_Connector_3' => 'OpenCart 3 के लिए डाउनलोड करें',
'Oc_Opencart3_Title' => 'OpenCart 3 स्टोर',
'Oc_Opencart3_Desc' => 'OpenCart 3 में अपने वेरिएंट नहीं होते, केवल विकल्प होते हैं। एक विकल्प (जैसे Size) वाला उत्पाद हर विकल्प मान के स्टॉक के साथ सिंक होता है, जो यहाँ के वेरिएंट से मैप होता है। कई विकल्पों वाले उत्पाद के विकल्प हर संयोजन के स्टॉक के बिना बनाए जाते हैं: उसका स्टॉक पूरे उत्पाद पर रखा जाता है, और उसकी बिक्री पंक्तियाँ उत्पाद के नाम पर आती हैं।',
'Oc_G_Title' => 'OpenCart गाइड',
'Oc_G_Open_Settings' => 'OpenCart सेटिंग्स खोलें',
'Oc_G_Your_Setup' => 'आपका सेटअप',
'Oc_G_Your_Setup_Help' => 'यह वर्कस्पेस अभी किस स्थिति में है। आगे बढ़ने पर चरण अपडेट होते जाते हैं।',
'Oc_G_Step_Install' => 'अपने स्टोर पर {company} Connector इंस्टॉल करें',
'Oc_G_Step_Install_Help' => 'एक छोटा एक्सटेंशन जो {company} को उत्पादों, स्टॉक और ऑर्डर तक पहुँच देता है। OpenCart में इनके लिए अपना कोई API नहीं है।',
'Oc_G_Step_Connect' => 'स्टोर कनेक्ट करें',
'Oc_G_Step_Connect_Help' => 'मॉड्यूल पेज से स्टोर URL और सीक्रेट कनेक्शन टैब पर पेस्ट करें, सहेजें, फिर कनेक्शन टेस्ट करें चलाएँ।',
'Oc_G_Step_Connect_Done' => 'कनेक्टेड: OpenCart {opencart} पर कनेक्टर {connector}।',
'Oc_G_Step_Enable' => 'सिंक चालू करें',
'Oc_G_Step_Enable_Help' => 'इंटीग्रेशन बंद रहने तक कुछ भी आगे नहीं बढ़ता; स्टोर से आने वाले वेबहुक स्वीकार करके अनदेखा कर दिए जाते हैं।',
'Oc_G_Step_Products' => 'उत्पाद लिंक करें',
'Oc_G_Step_Products_Help' => 'स्टोर का कैटलॉग प्राप्त करें या अपना भेजें, ताकि स्टॉक का आना-जाना शुरू होने से पहले दोनों तरफ़ का हर उत्पाद लिंक हो जाए।',
'Oc_G_Step_Products_Done' => '{n} उत्पाद और {v} वेरिएंट लिंक किए गए।',
'Oc_G_Step_Orders' => 'ऑर्डर प्राप्त करें',
'Oc_G_Step_Orders_Help' => 'कनेक्ट होने के बाद नए ऑर्डर अपने-आप आते हैं। स्टोर में एक टेस्ट ऑर्डर दें और उसे बिक्री के अंतर्गत दिखते हुए देखें।',
'Oc_G_Step_Orders_No_Webhook' => 'ऑर्डर आयात हो गए, लेकिन स्टोर की सूचना के ज़रिए अभी तक कोई ऑर्डर नहीं आया है। अगर स्टोर इस पते तक नहीं पहुँच पाता, तब भी ऑर्डर हर कुछ मिनट में होने वाली जाँच से आते रहते हैं।',
'Oc_G_Step_Orders_Done' => 'स्टोर ऑर्डर सूचनाएँ भेज रहा है।',
'Oc_G_Install_Title' => 'कनेक्टर इंस्टॉल करें',
'Oc_G_Install_Intro' => 'अपना OpenCart संस्करण चुनें। कनेक्टर OpenCart के अपने एक्सटेंशन इंस्टॉलर से इंस्टॉल होता है; कोई फ़ाइल हाथ से संपादित नहीं करनी पड़ती।',
'Oc_G_Opencart_4' => 'OpenCart 4.x',
'Oc_G_Opencart_3' => 'OpenCart 3.x',
'Oc_G_I4_1' => 'OpenCart 4 के लिए कनेक्टर डाउनलोड करें।',
'Oc_G_I4_2' => 'अपने OpenCart एडमिन में {path} खोलें, फ़ाइल अपलोड करें और उसके आगे Install पर क्लिक करें।',
'Oc_G_I4_3' => '{path} खोलें, {name} ढूँढें और Install पर क्लिक करें, फिर Edit पर।',
'Oc_G_I3_1' => 'OpenCart 3 के लिए कनेक्टर डाउनलोड करें।',
'Oc_G_I3_2' => 'अपने OpenCart एडमिन में {path} खोलें, फ़ाइल अपलोड करें और चरण पूरे होने तक प्रतीक्षा करें।',
'Oc_G_I3_3' => '{path} खोलें, {name} ढूँढें और Install पर क्लिक करें, फिर Edit पर।',
'Oc_G_I_4' => 'मॉड्यूल पेज पर स्टोर URL और एक सीक्रेट दिखता है। दोनों कॉपी करें।',
'Oc_G_I_5' => 'यहाँ वापस आकर उन्हें कनेक्शन टैब पर पेस्ट करें, सहेजें, और {test} चलाएँ। इससे स्टोर को यह भी पता चल जाता है कि ऑर्डर सूचनाएँ कहाँ भेजनी हैं।',
'Oc_G_Requirements' => 'स्टोर के लिए क्या ज़रूरी है',
'Oc_G_Requirements_Desc' => 'OpenCart 3.0 या 4.0 और उससे ऊपर, cURL के साथ PHP (हर होस्ट पर मानक), और इंटरनेट से पहुँचने योग्य स्टोर पता। अगर स्टोर किसी निजी नेटवर्क पर है, तब भी ऑर्डर हर कुछ मिनट में चलने वाली जाँच से आते रहते हैं, बशर्ते यह वर्कस्पेस स्टोर तक पहुँच सके।',
'Oc_G_First_Title' => 'पहला सिंक',
'Oc_G_First_Shop_Has' => 'स्टोर में पहले से कैटलॉग है',
'Oc_G_First_Shop_Has_Text' => 'उत्पाद टैब पर उत्पाद प्राप्त करें। उत्पाद मॉडल या SKU से आपके उत्पाद कोड से मिलाए जाते हैं और न होने पर बनाए जाते हैं; स्टोर की मात्राओं को प्रारंभिक स्टॉक के रूप में लेने के लिए स्टॉक विकल्प पर टिक करें।',
'Oc_G_First_Company_Has' => 'कैटलॉग {company} में है',
'Oc_G_First_Company_Has_Text' => 'उत्पाद भेजें। जो उत्पाद नहीं हैं वे स्टोर में उनके स्टॉक के साथ बनाए जाते हैं; मौजूदा उत्पाद मॉडल या SKU से लिंक होकर अपडेट होते हैं।',
'Oc_G_First_Both' => 'दोनों तरफ़ उत्पाद हैं',
'Oc_G_First_Both_Text' => 'पहले प्राप्त करें, ताकि मौजूदा स्टोर उत्पाद डुप्लिकेट होने के बजाय लिंक हो जाएँ, फिर स्टोर में जो नहीं है उसे बनाने के लिए भेजें। दोनों तरफ़ उत्पाद कोड और मॉडल एक जैसे रखें।',
'Oc_G_Stock_Master' => 'स्टॉक का आँकड़ा {company} में रहता है',
'Oc_G_Stock_Master_Desc' => 'पहले सिंक के बाद स्टोर की मात्रा हमेशा {company} से लिखी जाती है। OpenCart में मात्रा संपादित करने का कोई स्थायी असर नहीं होता: अगला मूवमेंट या हर घंटे की जाँच उसे बदल देती है।',
'Oc_G_How_Title' => 'यह कैसे काम करता है',
'Oc_G_T_Products' => 'उत्पाद',
'Oc_G_Products_1' => 'उत्पाद को यहाँ के उसके कोड से स्टोर के मॉडल और SKU के साथ मिलाया जाता है। लिंक याद रखा जाता है, इसलिए बाद में उत्पाद का नाम बदलने से लिंक नहीं टूटता।',
'Oc_G_Products_2' => 'जब {company} कोई उत्पाद भेजता है तो वह मॉडल, SKU, नाम, मूल्य, स्थिति और स्टॉक सेट करता है। विवरण, चित्र और श्रेणी केवल तभी लिखे जाते हैं जब उत्पाद स्टोर में नया हो या उसमें ये न हों, ताकि OpenCart में लिखी गई सामग्री बनी रहे।',
'Oc_G_Products_3' => 'जो उत्पाद ऑनलाइन दुकान से छिपा है या यहाँ बिक्री के लिए नहीं है, वह स्टोर में नहीं बनाया जाता; पहले से लिंक किया गया ऐसा उत्पाद वहाँ अक्षम कर दिया जाता है।',
'Oc_G_T_Variants' => 'वेरिएंट और विकल्प',
'Oc_G_Variants_4' => 'OpenCart 4 में असली वेरिएंट होते हैं (Color और Size विकल्पों वाला उत्पाद), हर एक का अपना स्टॉक होता है। ये दोनों ओर से आपके वेरिएंट से मैप होते हैं, और हर एक अपने मॉडल से मिलाया जाता है।',
'Oc_G_Variants_3' => 'OpenCart 3 में वेरिएंट नहीं होते, केवल विकल्प होते हैं, और हर विकल्प मान का स्टॉक होता है। एक विकल्प (जैसे Size) वाला उत्पाद हर मान के स्टॉक के साथ सिंक होता है, जो आपके वेरिएंट से मैप होता है। कई विकल्पों वाले उत्पाद के विकल्प हर संयोजन के स्टॉक के बिना बनाए जाते हैं: उसका स्टॉक पूरे उत्पाद पर रहता है, और उसकी बिक्री पंक्तियाँ उत्पाद के नाम पर आती हैं।',
'Oc_G_Variants_Multi' => 'जिस स्टोर उत्पाद में केवल विकल्प हों और कोई वेरिएंट न बनाया गया हो, वह एक उत्पाद के रूप में आयात होता है; इसका उल्लेख लॉग में किया जाता है।',
'Oc_G_T_Stock' => 'स्टॉक',
'Oc_G_Stock_1' => 'स्टॉक स्विच चालू होने पर यहाँ का हर मूवमेंट (बिक्री, वापसी, खरीद, समायोजन, स्थानांतरण) पेज के जवाब देने के बाद कुछ ही सेकंड में स्टोर को अपडेट कर देता है, इसलिए कैशियर को कभी स्टोर का इंतज़ार नहीं करना पड़ता।',
'Oc_G_Stock_2' => 'हर घंटे एक बार हर लिंक किए गए उत्पाद की जाँच करके उसे ठीक किया जाता है, जिससे वे थोक बदलाव भी कवर हो जाते हैं जिन्हें लाइव भेजना नहीं देख पाता। स्टॉक टैब माँगने पर सब कुछ भेज देता है।',
'Oc_G_Stock_3' => 'सेवाएँ, हमेशा स्टॉक में चिह्नित उत्पाद, और जिन कॉम्बो के घटक असीमित हैं, वे स्टोर में हमेशा उपलब्ध दिखाए जाते हैं। केवल एक गोदाम गिनने के लिए कनेक्शन टैब पर वह गोदाम चुनें; अन्यथा सभी गोदामों का योग लिया जाता है।',
'Oc_G_T_Orders' => 'ऑर्डर और स्थितियाँ',
'Oc_G_Orders_1' => 'नए या बदले गए ऑर्डर की सूचना स्टोर तुरंत देता है और उसे साइन किए गए कनेक्शन से दोबारा पढ़ा जाता है, इसलिए सूचना की किसी भी सामग्री पर भरोसा नहीं किया जाता। हर कुछ मिनट में एक जाँच वह सब प्राप्त करती है जो किसी सूचना से छूट गया हो। हर ऑर्डर संदर्भ OC-<order number> के साथ एक बिक्री बनता है; ग्राहक को ईमेल से मिलाया जाता है या नया बनाया जाता है।',
'Oc_G_Col_List' => 'स्थिति सूची',
'Oc_G_Col_Meaning' => 'यहाँ यह क्या करती है',
'Oc_G_Col_Default' => 'आपके स्टोर से सेट',
'Oc_G_Default_Commit' => 'OpenCart में स्टॉक घटाने वाली स्थितियाँ (डिफ़ॉल्ट रूप से Pending, Processing, Shipped, Complete)',
'Oc_G_Default_Paid' => 'Processing, Processed, Shipped, Complete',
'Oc_G_Default_Cancel' => 'Canceled, Denied, Failed, Refunded, Reversed, Chargeback, Expired, Voided',
'Oc_G_Orders_2' => 'पहले कनेक्शन पर सूचियाँ आपके स्टोर से भरी जाती हैं और कनेक्शन टैब पर बदली जा सकती हैं। पहली सूची को OpenCart में स्टॉक घटाने वाली स्थितियों के समान रखें, ताकि दोनों तरफ़ स्टॉक एक ही चरण पर घटे-बढ़े।',
'Oc_G_Orders_3' => 'जिस ऑर्डर का कोई आइटम किसी उत्पाद से मेल नहीं खाता, उसे रोक दिया जाता है, और अगर वह उत्पाद स्टोर में मौजूद हो तो उसे वहाँ से आयात किया जाता है। रोके गए ऑर्डर हर निर्धारित जाँच पर फिर से आज़माए जाते हैं; बारह प्रयासों के बाद उन्हें लॉग करके आपके लिए छोड़ दिया जाता है ताकि आप उन्हें हाथ से प्राप्त करें।',
'Oc_G_T_Cancel' => 'रद्दीकरण और रिफंड',
'Oc_G_Cancel_1' => 'जब स्टोर में कोई ऑर्डर रद्द स्थिति में पहुँचता है, तो यहाँ उसकी बिक्री उलट दी जाती है: स्टॉक वापस आ जाता है, उसके भुगतान हटा दिए जाते हैं और बिक्री हटा दी जाती है, ठीक वैसे ही जैसे बिक्री पेज पर उसे हटाने से होता।',
'Oc_G_Cancel_2' => 'जो बिक्री पहले ही डिलीवर हो चुकी हो, जिसकी वापसी हुई हो, या जिसे कर प्राधिकरण ने स्वीकार कर लिया हो, उसे स्टोर कभी नहीं उलटता। आपकी समीक्षा के लिए उसे उसके नोट्स और लॉग में चिह्नित किया जाता है।',
'Oc_G_Cancel_3' => 'अगर बाद में स्टोर में ऑर्डर फिर से बहाल किया जाता है, तो वह एक नई बिक्री के रूप में दोबारा आता है।',
'Oc_G_T_Automation' => 'ऑटोमेशन स्विच',
'Oc_G_Auto_1' => 'ऑर्डर अपने-आप आयात करें: ऑर्डर सूचनाएँ और निर्धारित जाँच। बंद होने पर ऑर्डर तभी आते हैं जब आप उन्हें ऑर्डर टैब पर प्राप्त करते हैं।',
'Oc_G_Auto_2' => 'स्टॉक अपने-आप भेजें: लाइव स्टॉक अपडेट और हर घंटे की जाँच। बंद होने पर स्टोर तभी बदलता है जब आप हाथ से स्टॉक भेजते हैं।',
'Oc_G_Auto_3' => 'उत्पाद में बदलाव अपने-आप भेजें: यहाँ बनाया या संपादित किया गया उत्पाद तुरंत स्टोर को अपडेट करता है। बंद होने पर उत्पाद टैब का उपयोग करें।',
'Oc_G_T_Faq' => 'प्रश्न',
'Oc_G_Q_Secret' => 'कनेक्शन टेस्ट करें बताता है कि सीक्रेट मेल नहीं खाता',
'Oc_G_A_Secret' => 'OpenCart में {company} Connector मॉड्यूल खोलें और सीक्रेट फिर से कॉपी करें; दोबारा इंस्टॉल किए गए मॉड्यूल को नया सीक्रेट मिलता है। टेस्ट करने से पहले इसे कनेक्शन टैब पर पेस्ट करके सहेजें।',
'Oc_G_Q_Clock' => 'कनेक्शन टेस्ट करें बताता है कि स्टोर की घड़ी बहुत आगे-पीछे है',
'Oc_G_A_Clock' => 'साइन किए गए अनुरोधों में समय होता है और दोनों घड़ियों में पाँच मिनट से ज़्यादा का अंतर होने पर वे अस्वीकार कर दिए जाते हैं। स्टोर के सर्वर पर तारीख और समय सेट करें।',
'Oc_G_Q_Redirect' => 'कनेक्शन टेस्ट करें बताता है कि स्टोर किसी दूसरे पते पर रीडायरेक्ट करता है',
'Oc_G_A_Redirect' => 'आपका स्टोर किसी अलग पते पर जवाब देता है, आमतौर पर http के बजाय https पर या www के साथ। संदेश में दिखाए गए पते को स्टोर URL के रूप में इस्तेमाल करें।',
'Oc_G_Q_Not_Answering' => 'कनेक्शन टेस्ट करें बताता है कि कनेक्टर ने जवाब नहीं दिया',
'Oc_G_A_Not_Answering' => 'यह पता OpenCart स्टोर का नहीं है, या मॉड्यूल इंस्टॉल नहीं है या अक्षम है। स्टोर URL जाँचें, फिर यह कि Extensions → Modules के अंतर्गत {company} Connector इंस्टॉल और सक्षम दिखता है।',
'Oc_G_Q_No_Orders' => 'स्टोर में ऑर्डर दिए जाते हैं लेकिन दिखने में कई मिनट लगते हैं',
'Oc_G_A_No_Orders' => 'स्टोर इस वर्कस्पेस तक नहीं पहुँच पाता, इसलिए ऑर्डर केवल निर्धारित जाँच से आते हैं। मॉड्यूल पेज पर {company} का पता देखें: वह स्टोर के सर्वर से पहुँचने योग्य होना चाहिए। कनेक्शन टेस्ट करें चलाने से वह दोबारा पंजीकृत हो जाता है।',
'Oc_G_Q_Stock_Wrong' => 'स्टोर में कोई मात्रा गलत है',
'Oc_G_A_Stock_Wrong' => 'स्टॉक टैब पर स्टॉक भेजें, जो हर लिंक किए गए उत्पाद को यहाँ के आँकड़ों से दोबारा लिखता है। अगर यह बार-बार गड़बड़ होता है, तो जाँचें कि स्टॉक स्विच चालू है और कोई OpenCart में मात्राएँ संपादित नहीं कर रहा।',
'Oc_G_Q_Out_Of_Stock' => 'यहाँ स्टॉक होने के बावजूद स्टोर में उत्पाद स्टॉक से बाहर दिखता है',
'Oc_G_A_Out_Of_Stock' => 'OpenCart 3 पर कई विकल्पों वाला उत्पाद अपना स्टॉक पूरे उत्पाद पर रखता है; उसके विकल्पों के बजाय स्टोर में उत्पाद की मात्रा जाँचें। किसी भी उत्पाद के लिए, एक बार स्टॉक भेजें और उस उत्पाद के लॉग देखें।',
'Oc_G_Q_Held' => 'लॉग बताते हैं कि एक ऑर्डर रोका गया',
'Oc_G_A_Held' => 'उसका एक आइटम यहाँ किसी उत्पाद से मेल नहीं खाता और स्टोर से आयात नहीं हो सका, आमतौर पर इसलिए कि उत्पाद वहाँ हटा दिया गया था। उत्पाद बनाएँ या लिंक करें, फिर ऑर्डर टैब पर ऑर्डर प्राप्त करें।',
'Oc_G_Q_Deleted_Sale' => 'मैंने एक आयातित बिक्री हटाई और वह वापस आ गई',
'Oc_G_A_Deleted_Sale' => 'जब तक ऑर्डर स्टोर में सक्रिय है, अगली सूचना या जाँच उसे फिर से आयात कर देती है। इसके बजाय स्टोर में ऑर्डर रद्द करें, जिससे यहाँ बिक्री उलट जाती है।',
'Oc_G_Q_Uninstall' => 'मैं स्टोर को डिस्कनेक्ट कैसे करूँ?',
'Oc_G_A_Uninstall' => 'कनेक्शन टैब पर सिंक बंद करें; बंद रहने तक कुछ भी आगे नहीं बढ़ता। स्टोर से इंटीग्रेशन हटाने के लिए Extensions → Modules के अंतर्गत {company} Connector अनइंस्टॉल करें।',
'Oc_Full_Guide' => 'पूरी गाइड खोलें',
'Comm_Receipt_Account_Hint' => 'वह नकद या बैंक खाता जिससे यह भुगतान निकलता है। उसका शेष इस राशि से घट जाता है और लेजर उसके सामने बिक्री कमीशन व्यय (Sales Commission Expense) पोस्ट करता है।',
'Comm_G_Q_Ledger' => 'कमीशन भुगतान का खातों पर क्या असर होता है?',
'Comm_G_A_Ledger' => 'जब आप रसीद बनाकर कोई खाता चुनते हैं, तो उस खाते का शेष रसीद की राशि से घट जाता है और, अगर स्वचालित जर्नल चालू हैं, तो एक जर्नल पोस्ट होता है: डेबिट बिक्री कमीशन व्यय (Sales Commission Expense) (5200-COMM), क्रेडिट चुना गया नकद या बैंक खाता। कोई खाता न चुनने पर क्रेडिट डिफ़ॉल्ट नकद (Cash) खाते में जाता है और किसी शेष में बदलाव नहीं होता।',
'Hide_Zero_Decimals' => 'शून्य दशमलव छिपाएँ',
'Sys_Hide_Zero_Decimals_Help' => 'पूर्ण संख्या वाली राशियाँ बिना दशमलव के दिखाएँ: 100.00 बन जाता है 100, जबकि 100.50 के दशमलव बने रहते हैं। केवल प्रदर्शन के लिए; सहेजे गए मान और गणनाएँ नहीं बदलतीं।',
'Sys_Currency_Position_Before_NoSpace' => 'राशि से पहले, बिना स्पेस',
'Sys_Currency_Position_After_NoSpace' => 'राशि के बाद, बिना स्पेस',
'Supplier_Wallet' => 'प्रदायक वॉलेट',
'Supplier_Wallets' => 'प्रदायक वॉलेट',
'Supplier_Ledger' => 'प्रदायक खाता बही',
'Sys_Supplier_Wallet_Help' => 'प्रदायकों के पास अग्रिम शेष रखें: टॉप-अप, वापसी क्रेडिट, और वॉलेट से खरीद का भुगतान। इसके लिए योजना में प्रदायक वॉलेट सुविधा ज़रूरी है।',
