'SW_Freeze_Confirm' => 'फ़्रीज़ किया गया वॉलेट अनफ़्रीज़ होने तक हर लेन-देन अस्वीकार करता है। जारी रखें?',
'SW_Unfreeze_Confirm' => 'इस प्रदायक के लिए वॉलेट लेन-देन फिर से अनुमति दें?',
