'SW_Top_Up_Help' => 'प्रदायक को पहले से दिया गया पैसा। यह चुने गए खाते से निकलता है और खरीद पर खर्च होने तक वॉलेट में रहता है।',
'SW_Refund_Help' => 'प्रदायक अग्रिम का कुछ हिस्सा नकद में लौटाता है। राशि वॉलेट से निकलकर चुने गए खाते में आती है।',
'SW_Adjust_Help' => 'बिना नकद लेन-देन के मैन्युअल सुधार। कारण देना ज़रूरी है और वह खाता बही में रखा जाता है।',
'SW_Adjust_Credit' => 'वॉलेट में जोड़ें',
'SW_Adjust_Debit' => 'वॉलेट से घटाएँ',
