'SW_Pay_From_Wallet_Help' => 'राशि इस प्रदायक के पास रखे अग्रिम शेष से ली जाती है। किसी खाते या भुगतान विधि की ज़रूरत नहीं है।',
'SW_Credit_To_Wallet' => 'प्रदायक वॉलेट में क्रेडिट करें',
'SW_Credit_To_Wallet_Help' => 'नकद के बजाय, प्रदायक इस वापसी का निपटान वॉलेट क्रेडिट के रूप में करता है, जिसे आप बाद की खरीद पर खर्च कर सकते हैं।',
'SW_Disabled_Hint' => 'प्रदायक वॉलेट बंद है। इसे सिस्टम सेटिंग्स > विशेषताएँ में चालू करें (इसके लिए योजना में प्रदायक वॉलेट सुविधा भी ज़रूरी है)।',
