'SW_Perm_Manage' => 'प्रदायक वॉलेट: प्रबंधित करें',
'SW_Top_Ups_Total' => 'टॉप-अप (कुल)',
'SW_Spent_Total' => 'वॉलेट से खर्च',
'Purchases_Grand' => 'खरीद (कुल)',
'Purchases_Paid' => 'खरीद (भुगतान किया)',
'Purchases_Due' => 'खरीद (देय)',
'Purchase_Update_Selling_Price' => 'खरीद पर विक्रय मूल्य संपादित करें',
'Sys_Purchase_Update_Selling_Price_Help' => 'हर खरीद पंक्ति में लागत के बगल में एक विक्रय मूल्य फ़ील्ड जोड़ता है। वहाँ लिखा गया मूल्य खरीद सहेजने पर उत्पाद के विक्रय मूल्य की जगह ले लेता है; वर्तमान मूल्य रखने के लिए इसे खाली छोड़ें।',
'Current_Selling_Price' => 'वर्तमान विक्रय मूल्य',
'Keep_Current_Price' => 'वर्तमान मूल्य रखने के लिए खाली छोड़ें',
'Selling_Price_In_Base_Currency' => 'मूल मुद्रा में दर्ज',
'Purchase_Update_Product_Cost' => 'खरीद पर उत्पाद लागत अपडेट करें',
'Sys_Purchase_Update_Product_Cost_Help' => 'जब प्राप्त खरीद सहेजी जाती है, तो हर उत्पाद की लागत उसकी खरीद पंक्ति की शुद्ध इकाई लागत बन जाती है (पंक्ति छूट के बाद, कर के बिना, प्रति मूल इकाई)। लंबित और ऑर्डर की गई खरीद इसे नहीं बदलतीं।',
'Show_Stock_In_Search_Results' => 'खोज परिणामों में स्टॉक दिखाएँ',
'Show_Stock_In_Search_Results_Help' => 'POS खोज ड्रॉपडाउन में हर उत्पाद के बगल में उसकी उपलब्ध मात्रा दिखाएँ।',
'Layout_6_Tabular' => 'लेआउट 6 - तालिका',
'Show_Signature_Line' => 'हस्ताक्षर पंक्ति दिखाएँ',
'Show_Signature_Line_Desc' => 'रसीद के नीचे ग्राहक के हस्ताक्षर के लिए एक खाली पंक्ति प्रिंट करता है, चाहे कोई भी लेआउट चुना गया हो।',
'Customer_Signature' => 'ग्राहक के हस्ताक्षर',
'Set_Signature_Label' => 'हस्ताक्षर पंक्ति का लेबल (खाली = "ग्राहक के हस्ताक्षर")',
'Oc_Code_Source' => 'उत्पाद कोड स्रोत',
'Oc_Code_Source_Help' => 'यहाँ उत्पाद कोड कौन-सा OpenCart फ़ील्ड है। OpenCart में Model ज़रूरी होता है, इसलिए कुछ स्टोर उसमें श्रेणी या उत्पाद का प्रकार लिख देते हैं और असली आर्टिकल कोड SKU, ISBN, UPC, EAN, JAN या MPN में रखते हैं; ऐसे स्टोर के लिए वह फ़ील्ड चुनें। चुना गया फ़ील्ड खाली होने पर पहले Model, फिर SKU इस्तेमाल होता है। यह प्राप्त किए गए उत्पादों, मिलान और भेजने पर लागू होता है।',
'Oc_Code_Source_Model' => 'Model (डिफ़ॉल्ट)',
'Oc_Code_Source_Sku' => 'SKU',
'Oc_Connector_Link' => 'कनेक्टर वेबसाइट',
'Oc_Connector_Link_Help' => 'आपकी वेबसाइट का पता। OpenCart, Extensions > Installer पेज पर कनेक्टर के नाम को इससे लिंक करता है। इस {company} वर्कस्पेस का पता इस्तेमाल करने के लिए खाली छोड़ें।',
'Store_Warehouses_Help' => 'ऑनलाइन दिखाया और घटाया जाने वाला स्टॉक इन गोदामों से आता है। जब तक विशेषताएँ में "गोदाम के अनुसार उत्पाद सीमित करें" चालू है, दुकान केवल वही उत्पाद दिखाती है जो इन गोदामों से संबंधित हैं (या जिनका स्टॉक इनमें है)।',
'Oc_Code_Source_Needs_Update' => 'स्टोर में इंस्टॉल किया गया कनेक्टर (संस्करण {version}) केवल Model और SKU भेजता है। इस फ़ील्ड को पढ़ने के लिए कनेक्टर फिर से डाउनलोड करें और स्टोर में पुराने के ऊपर अपलोड करें।',
'Oc_L_Title' => 'OpenCart लॉग',
'Oc_L_Intro' => 'उत्पाद प्राप्त करने और भेजने की हर कार्रवाई, हर स्टॉक अपडेट, ऑर्डर और स्टोर कॉल यहाँ दर्ज होता है। क्या विफल हुआ यह देखने के लिए त्रुटियों पर फ़िल्टर करें, उसका अर्थ और क्या करना है पढ़ने के लिए कोई पंक्ति खोलें, और सपोर्ट को भेजने के लिए सूची निर्यात करें।',
'Oc_L_Tab_Hint' => 'पूरा लॉग पेज हर प्रविष्टि समझाता है, क्रिया और तारीख से फ़िल्टर करता है, और फ़ाइल में निर्यात करता है।',
'Oc_L_Open_Page' => 'लॉग पेज खोलें',
'Oc_L_Entries' => 'प्रविष्टियाँ',
'Oc_L_Errors' => 'त्रुटियाँ',
'Oc_L_Warnings' => 'चेतावनियाँ',
