'Oc_L_Col_Message' => 'क्या हुआ',
'Oc_L_Open_Row' => 'विवरण और क्या करना है देखने के लिए किसी पंक्ति पर क्लिक करें।',
'Oc_L_What_It_Means' => 'इसका क्या अर्थ है',
'Oc_L_What_To_Do' => 'क्या करें',
