'Oc_L_Raw' => 'कच्चा डेटा',
'Oc_L_Support' => 'अब भी अटके हैं? लॉग निर्यात करें और फ़ाइल सपोर्ट को भेजें, साथ में बताएँ कि आप क्या कर रहे थे।',
'Oc_L_D_Errors' => 'विफल आइटम',
'Oc_L_D_Warnings' => 'स्टोर से चेतावनियाँ',
'Oc_L_D_Codes_Suffixed' => 'किसी दूसरे स्टोर उत्पाद द्वारा पहले से इस्तेमाल किए गए कोड (यहाँ code-id के रूप में बनाए गए)',
'Oc_L_D_Options' => 'विकल्पों वाले लेकिन बिना वेरिएंट के उत्पाद (स्टॉक प्रति उत्पाद रखा जाता है)',
'Oc_L_D_Unmatched' => 'ऑर्डर आइटम जो यहाँ किसी उत्पाद से मेल नहीं खाते',
'Oc_L_D_Store_Total' => 'स्टोर में उत्पाद',
