'Oc_L_Act_orders_import' => 'ऑर्डर आयात',
'Oc_L_Act_orders_retry' => 'ऑर्डर पुनः प्रयास',
'Oc_L_Act_orders_reverse' => 'ऑर्डर रद्द',
'Oc_L_Act_orders_review' => 'ऑर्डर की समीक्षा ज़रूरी',
'Oc_L_Act_webhook_order' => 'ऑर्डर सूचना',
'Oc_L_Act_auto_sync' => 'ऑटो-सिंक',
'Oc_L_Act_connect_test' => 'कनेक्शन टेस्ट',
'Oc_L_Act_scheduled' => 'निर्धारित सिंक',
'Oc_L_Act_sync' => 'सिंक',
'Oc_L_H_Secret' => 'यहाँ सहेजा गया सीक्रेट OpenCart के कनेक्टर मॉड्यूल वाले सीक्रेट से अलग है, इसलिए स्टोर हर कॉल अस्वीकार कर देता है।',
'Oc_L_F_Secret' => 'OpenCart में Extensions → Modules → कनेक्टर खोलें, वहाँ दिखाया गया सीक्रेट कॉपी करें, उसे कनेक्शन टैब पर पेस्ट करें और सहेजें। मॉड्यूल दोबारा इंस्टॉल करने से नया सीक्रेट बनता है।',
'Oc_L_H_Clock' => 'OpenCart सर्वर की घड़ी हमारी घड़ी से बहुत अलग है, इसलिए साइन किए गए अनुरोध समाप्त हुए लगते हैं।',
'Oc_L_F_Clock' => 'होस्टिंग प्रदाता से सर्वर का समय (NTP) सेट करने को कहें। कुछ मिनट का अंतर भी कनेक्शन रोकने के लिए काफ़ी है।',
'Oc_L_H_Disabled' => 'कनेक्टर मॉड्यूल OpenCart में इंस्टॉल है लेकिन बंद है।',
'Oc_L_F_Disabled' => 'OpenCart में Extensions → Modules → कनेक्टर खोलें और Status को Enabled पर सेट करें।',
'Oc_L_H_Unreachable' => 'स्टोर ने सहेजे गए पते पर जवाब नहीं दिया, या वहाँ कनेक्टर मॉड्यूल इंस्टॉल नहीं है।',
'Oc_L_F_Unreachable' => 'स्टोर ऑनलाइन है यह जाँचने के लिए ब्राउज़र में स्टोर URL खोलें, पुष्टि करें कि कनेक्टर मॉड्यूल इंस्टॉल और सक्षम है, और जाँचें कि कोई फ़ायरवॉल या मेंटेनेंस मोड हमारे सर्वर को रोक नहीं रहा।',
'Oc_L_H_Redirect' => 'स्टोर आगंतुकों को किसी दूसरे पते पर भेजता है (उदाहरण के लिए http से https पर या www पर)।',
'Oc_L_F_Redirect' => 'संदेश में बताए गए पते को कनेक्शन टैब पर स्टोर URL के रूप में सहेजें।',
'Oc_L_H_Not_Configured' => 'स्टोर URL या सीक्रेट मौजूद नहीं है, इसलिए अभी कुछ भी नहीं भेजा जा सकता।',
'Oc_L_F_Not_Configured' => 'कनेक्शन टैब पर स्टोर URL और सीक्रेट भरें, सहेजें और कनेक्शन टेस्ट करें चलाएँ।',
'Oc_L_H_Model_Taken' => 'स्टोर को भेजे गए एक उत्पाद का कोड ऐसा है जिसे कोई दूसरा स्टोर उत्पाद, या उसका कोई वेरिएंट, पहले से अपने मॉडल के रूप में इस्तेमाल करता है।',
'Oc_L_F_Model_Taken' => 'दोनों में से किसी एक उत्पाद का कोड बदलें, या पहले उत्पाद प्राप्त करें ताकि मौजूदा स्टोर उत्पाद दोबारा बनने के बजाय लिंक हो जाए।',
'Oc_L_H_Model_Missing' => 'स्टोर को भेजे गए एक उत्पाद का कोई कोड या नाम नहीं है। OpenCart को दोनों चाहिए।',
'Oc_L_F_Model_Missing' => 'यहाँ उत्पाद को कोड और नाम दें, फिर दोबारा भेजें।',
'Oc_L_H_Held' => 'एक ऑर्डर प्राप्त हुआ लेकिन उसके कुछ आइटम यहाँ किसी उत्पाद से मेल नहीं खाते, इसलिए वह प्रतीक्षा में है और कोई बिक्री नहीं बनी।',
'Oc_L_F_Held' => 'जो उत्पाद नहीं हैं उन्हें बनाएँ या प्राप्त करें (आइटम नीचे सूचीबद्ध हैं), फिर ऑर्डर दोबारा प्राप्त करें। रोके गए ऑर्डर कुछ बार अपने-आप फिर से आज़माए जाते हैं।',
'Oc_L_H_Given_Up' => 'कई प्रयासों के बाद भी एक ऑर्डर आयात नहीं हो सका और अब उसे फिर से नहीं आज़माया जाता।',
'Oc_L_F_Given_Up' => 'सुनिश्चित करें कि उसके उत्पाद यहाँ मौजूद हैं, फिर ऑर्डर टैब से ऑर्डर से पहले की तारीख चुनकर हाथ से ऑर्डर प्राप्त करें।',
'Oc_L_H_Review' => 'यहाँ बिक्री डिलीवर या वापस होने के बाद OpenCart में एक ऑर्डर रद्द किया गया, इसलिए स्टॉक अपने-आप नहीं लौटाया गया।',
'Oc_L_F_Review' => 'बिक्री खोलें और तय करें कि आइटम वापस करने हैं या उसे वैसे ही छोड़ना है।',
'Oc_L_H_Reversed' => 'OpenCart में एक ऑर्डर रद्द किया गया और यहाँ उससे मेल खाती बिक्री उलट दी गई, जिससे उसका स्टॉक वापस आ गया।',
'Oc_L_H_Backlog' => 'निर्धारित ऑर्डर प्राप्ति को एक बार में संसाधित होने से अधिक ऑर्डर मिले, और यह अगली बार फिर से शुरू होगी।',
'Oc_L_F_Backlog' => 'बकाया ऑर्डर निपटाने के लिए ऑर्डर टैब से हाथ से ऑर्डर प्राप्त करें।',
'Oc_L_H_Paused' => 'स्टोर के जवाब देना बंद करने के कारण स्वचालित भेजना कुछ समय के लिए रोका गया। इस बीच किए गए बदलाव स्टोर के फिर से जवाब देने पर भेज दिए जाते हैं।',
'Oc_L_F_Paused' => 'जाँचें कि स्टोर ऑनलाइन है। और कुछ करने की ज़रूरत नहीं है; कतार अपने-आप फिर से शुरू हो जाती है।',
'Oc_L_H_Busy' => 'दो स्वचालित भेजने की प्रक्रियाएँ एक साथ चलीं और एक रुक गई। कुछ भी नहीं खोया।',
'Oc_L_H_Codes_Suffixed' => 'प्राप्त किए गए कुछ उत्पादों का कोड ऐसा है जो यहाँ पहले से किसी दूसरे स्टोर उत्पाद का था, आमतौर पर इसलिए कि चुना गया कोड फ़ील्ड खाली है या उसमें श्रेणी का नाम है। उन्हें OpenCart id जोड़कर बनाया गया ताकि कोई दो उत्पाद आपस में न मिलें।',
'Oc_L_F_Codes_Suffixed' => 'नीचे सूचीबद्ध उत्पादों के लिए OpenCart में कोड फ़ील्ड (Model, SKU, ISBN…) भरें, या कनेक्शन टैब पर कोई दूसरा उत्पाद कोड स्रोत चुनें, फिर उत्पाद लिंक रीसेट करके दोबारा प्राप्त करें।',
'Oc_L_H_Options' => 'कुछ स्टोर उत्पादों में वेरिएंट स्टॉक के बिना विकल्प (साइज़, रंग…) हैं, इसलिए स्टॉक पूरे उत्पाद के लिए ट्रैक किया जाता है।',
'Oc_L_F_Options' => 'कुछ करने की ज़रूरत नहीं है। हर विकल्प का स्टॉक ट्रैक करने के लिए OpenCart 4 में उन विकल्पों को वेरिएंट में बदलें, या OpenCart 3 में हर उत्पाद पर एक विकल्प इस्तेमाल करें।',
'Oc_L_H_Pull_Ok' => 'उत्पादों का यह पेज स्टोर से पढ़ा गया। बनाया गया का मतलब है यहाँ नया उत्पाद; अपडेट किया गया का मतलब है कि वह पहले से मौजूद था और लिंक किया गया।',
'Oc_L_H_Pull_Failed' => 'इस पेज के कुछ उत्पाद यहाँ सहेजे नहीं जा सके; हर एक कारण के साथ नीचे सूचीबद्ध है।',
'Oc_L_F_Pull_Failed' => 'OpenCart में सूचीबद्ध उत्पादों को ठीक करें (आमतौर पर नाम या कोड न होना कारण होता है) और दोबारा प्राप्त करें। केवल विफल उत्पाद प्रभावित होते हैं।',
'Oc_L_H_Push_Warnings' => 'उत्पाद स्टोर को भेजे गए, लेकिन स्टोर ने उनमें से कुछ में समस्याएँ बताईं, जैसे कोई चित्र जिसे वह डाउनलोड नहीं कर सका।',
'Oc_L_F_Push_Warnings' => 'नीचे दी गई सूची पढ़ें। चित्र स्टोर सर्वर से पहुँचने योग्य होने चाहिए; बाकी सब कुछ जैसा भेजा गया वैसा ही सहेजा गया।',
'Oc_L_H_Missing_Remote' => 'स्टॉक भेजा गया, लेकिन कुछ लिंक किए गए उत्पाद अब स्टोर में मौजूद नहीं हैं।',
'Oc_L_F_Missing_Remote' => 'उन्हें स्टोर में फिर से बनाने के लिए उत्पाद भेजें, या अगर उन्हें जानबूझकर हटाया गया था तो उत्पाद लिंक रीसेट करें।',
'Oc_L_H_Generic' => 'सिंक का एक चरण विफल हुआ। ऊपर दिया संदेश स्टोर या सर्वर का अपना कारण है।',
'Oc_L_F_Generic' => 'कनेक्शन टैब पर कनेक्शन टेस्ट करें चलाएँ। अगर वह सफल हो, तो चरण फिर से आज़माएँ; अगर विफल हो, तो उसके दिए संकेत का पालन करें।',
'Oc_L_H_Code_Fallback' => 'इस पेज के कुछ उत्पाद उत्पाद कोड स्रोत के रूप में चुने गए फ़ील्ड में बिना मान के आए, इसलिए उनका Model (अक्सर श्रेणी का नाम) कोड के रूप में इस्तेमाल किया गया।',
'Oc_L_F_Code_Fallback' => 'नीचे "हर फ़ील्ड वाले उत्पाद" जाँचें। अगर चुना गया फ़ील्ड 0 दिखाता है जबकि स्टोर में वे मान हैं, तो स्टोर उन्हें किसी दूसरे पहचानकर्ता नाम से रखता है; OpenCart में सूचीबद्ध कोई एक उत्पाद खोलें (Data टैब, Product Codes) और जो दिखे वह हमें भेजें। अन्यथा सूचीबद्ध उत्पादों के लिए OpenCart में फ़ील्ड भरें और दोबारा प्राप्त करें।',
'Oc_L_H_Old_Connector' => 'स्टोर में अब भी 1.1.0 से पुराना कनेक्टर चल रहा है, जो केवल Model और SKU भेजता है, इसलिए चुना गया कोड फ़ील्ड कभी नहीं आता और Model इस्तेमाल किया गया।',
'Oc_L_F_Old_Connector' => 'कनेक्टर फिर से डाउनलोड करें, OpenCart में पुराने को अनइंस्टॉल करके हटाएँ (Extensions → Installer), नया इंस्टॉल करें, उसका नया सीक्रेट कनेक्शन टैब पर पेस्ट करें और कनेक्शन टेस्ट करें चलाएँ। प्राप्त करने से पहले पेज पर Connector 1.1.0 दिखना चाहिए।',
'Oc_L_D_Code_Source' => 'उत्पाद कोड स्रोत',
'Oc_L_D_Code_Fallback_Count' => 'चुने गए फ़ील्ड के बिना उत्पाद',
'Oc_L_D_Codes_Seen' => 'हर फ़ील्ड वाले उत्पाद',
'Oc_L_D_Code_Fallback' => 'कोड के रूप में Model इस्तेमाल करने वाले उत्पाद (#OpenCart id, Model)',
'Oc_L_H_Codes_Fixed' => 'पहले Model को कोड बनाकर आयात किए गए कुछ उत्पादों में अब स्टोर में चुना गया फ़ील्ड है, इसलिए उनका कोड उसी के अनुसार ठीक किया गया।',
