'Warehouse_Prices_Enabled_Help' => 'किसी उत्पाद को हर गोदाम (स्टोर) में उसका अपना मूल्य, थोक मूल्य और न्यूनतम मूल्य दें। POS, बिक्री, कोटेशन और बारकोड लेबल चुने गए गोदाम का मूल्य इस्तेमाल करते हैं। ऑनलाइन दुकान और चैनल सिंक सामान्य मूल्य रखते हैं, और पहले से दर्ज बिक्री नहीं बदलती।',
