'Store_Prices_Add_Variants_First' => 'पहले वेरिएंट जोड़ें, फिर हर स्टोर के लिए उनके मूल्य सेट करें।',
'Store_Prices_Switch_Off' => 'स्टोर मूल्य आयात करने के लिए सिस्टम सेटिंग्स > विशेषताएँ में "हर स्टोर के लिए अलग मूल्य" चालू करें।',
'Store_Prices_Import_Help' => 'शीट निर्यात करें, price, wholesale_price और min_price कॉलम भरें, फिर उसे वापस आयात करें। खाली सेल का मतलब है कि उस स्टोर में सामान्य मूल्य लागू होता है। product और normal_price कॉलम केवल संदर्भ के लिए हैं। वेरिएंट के लिए वेरिएंट का अपना कोड इस्तेमाल करें।',
