'Trk_Intro' => 'अपनी ऑनलाइन दुकान से Google Analytics, Google Ads, Google Tag Manager और Meta Pixel कनेक्ट करें। केवल ID पेस्ट करें, कोड स्निपेट नहीं। पेज व्यू, उत्पाद व्यू, कार्ट में जोड़ना, चेकआउट और खरीदारी अपने-आप भेजे जाते हैं।',
'Trk_Google_Tag_ID' => 'Google tag ID',
'Trk_Google_Help' => 'Google Analytics > Admin > Data streams (G-…), Google Ads > Tools > Google tag (AW-…), या Tag Manager (GTM-…)। खरीदारी को Google Ads कन्वर्ज़न के रूप में गिनने के लिए कन्वर्ज़न ID उसके लेबल के साथ जोड़ें, जैसे AW-123456789/AbCdEf। कई ID को कॉमा से अलग करें।',
'Trk_Meta_Pixel_ID' => 'Meta Pixel ID',
'Trk_Meta_Help' => 'Meta Events Manager > Data sources: आपके Pixel नाम के नीचे दिखाई गई संख्या। कई ID को कॉमा से अलग करें।',
'Trk_Consent_Note' => 'कुकी बैनर चालू है: Google Analytics और Tag Manager तभी लोड होते हैं जब आगंतुक एनालिटिक्स कुकी स्वीकार करता है, और Google Ads तथा Meta Pixel तब जब वह मार्केटिंग कुकी स्वीकार करता है।',
'Trk_Invalid_Google' => 'अमान्य Google tag ID। G-, AW-, GT- या GTM- से शुरू होने वाली ID, या लेबल के साथ AW- कन्वर्ज़न ID इस्तेमाल करें।',
